window.__D("text/torat-shmuel/c035",{"p":[[2002180076,"שמחה להיותו למעלה מבחי' שמחה עדיין), אבל בבינה שהוא בחי' השגה כי עד\"מ השכל כשמשיגים אותו אז דוקא מקבל תענוג ממנו (ושמח בו בבחי' התפעלות מורגשת בבחי' התלהבות וגילוי אור כו', וענין) העבודה צ\"ל בשמחה דוקא וכמ\"ש תחת אשר לא עבדת<sup data-n=\"57\">24</sup> בשמחה שמשמע שצ\"ל עבודה בשמחה דוקא ועבודה בלא שמחה כו', שכאו\"א לפי ערך השגתו צ\"ל העבודה בשמחה דוקא. וזהו ההפרש שבין יו\"ט לשבת הגם כי שבת הוא בחי' מוחין דאבא ויו\"ט הוא בחי' מוחין דאימא<sup data-n=\"58\">25</sup>, עכ\"ז מצות השמחה הוא ביו\"ט דוקא וכמ\"ש ושמחת בחגך לפי שאז הם מועדים לשמחה כו'.\n<b>באו</b> לפניו ברננה הוא ג\"כ בחי' שמחה, רק שהיא בחי' שמחה שבאה מחמת מרירות<sup data-n=\"59\">26</sup> וכמו א' שהי' בבחי' מרירות ובא לו אח\"כ בחי' שמחה, וכמו הניגון שכלול ממרירות ושמחה כו'. וההפרש שבין שמחה לרננה זהו כמו ההפרש בין תמיד של שחר ובין תמיד של בין הערביים<sup data-n=\"60\">27</sup>, שרננה הוא כמו תמיד של בין הערביים בחי' מ\"ן בירורים דלמטה, ומזה בא השמחה הרי זהו בחי' רננה דהיינו כמשל הנ\"ל.\n<b>דעו</b> כי הוי' הוא האלקים<sup data-n=\"61\">28</sup>, הנה מזמור לתודה הוא בחי' חכ', ועבדו את ה' בשמחה הוא בחי' בינה, דעו כי ה' כו' הוא בחי' דעת. והענין הוא דהנה מי שלמד מס' אחת או שקיבל מרבו איזה דבר נק' חכם, הגם שהשכל אינו שלו עכ\"ז כשקיבלו נק' חכם. ובינה הוא להבין דבר מתוך דבר, שאומרים דבר א' ומבין ממנו עוד דבר א' שהיא חכ' יתירה, והראי' שנבונים בימי משה לא אשתכח כמ\"ש הבו לכם אנשים חכמים ונבונים וידועים, ואח\"כ כתי' ואקח את ראשי שבטיכם אנשים חכמים וידועים, ואלו נבונים לא אשתכח כו'. ודעת יש בו ג' פירושים<sup data-n=\"62\">29</sup>, רש\"י פי' שדעת הוא שיכול להביא טעם וראי' לדבריו, שהוא בחי' עומק החכמה שיכול להביא ראי' לדבריו שטעמו ונימוקו עמו. וה\"ר יונה פי' שדעת הוא ע\"ד שארז\"ל ולא במרכבה ביחיד אא\"כ הי' חכם ומבין מדעתו שדי לו ברמיזה, לפי שענין מרכבה הוא סוד נפלא לכן אין דורשים אא\"כ הי' חכם ומבין מדעתו ברמיזה. ובמד\"ר ויקרא פ\"א פי' ענין הדעת על הנהגת המדות שארז\"ל כל ת\"ח שאין בו דיעה נבילה טובה הימנו<sup data-n=\"63\">30</sup>, ולכן על משה",[["57","24","<b>העבודה צ\"ל בשמחה . . תחת אשר לא עבדת</b>: בכ\"ז ראה גם לעיל ח\"א ד\"ה החודש הזה לכם."],["58","25","<b>ההפרש שבין יו\"ט לשבת . . מוחין דאבא . . מוחין דאימא</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380123\" data-slug=\"likkutei-torah\" data-id=\"4001380123\">לקו\"ת צו יא, ד</a> ואילך. סידור עם דא\"ח ר, ב. רצו, ד ואילך. סה\"מ תר\"ל ע' רסב-ג. תרל\"ב ח\"א ע' סז-ח. וש\"נ. המשך וככה תרל\"ז פ\"ה ואילך (ע' ה ואילך)."],["59","26","<b>באו לפניו ברננה . . ג\"כ בחי' שמחה . . שבאה מחמת מרירות</b>: ראה בארוכה מאמרי אדה\"ז תקס\"ג ח\"א ע' רז ואילך. וע' שצב ואילך. יהל אור לתהלים שם ע' שעג-ד."],["60","27","<b>וההפרש שבין שמחה לרננה . . תמיד של שחר . . בין הערביים</b>: ביהל אור לתהלים שם ע' שעח מביא זה בשם הזח\"א רכט, ב."],["61","28","<b>דעו כי הוי' הוא האלקים</b>: בהבא לקמן בפיסקא זו ראה בארוכה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650259\" data-slug=\"or-hatorah-hb\" data-id=\"8316650259\">אוה\"ת נ\"ך (כרך ב) שם ע' תתקפח</a>-ט."],["62","29","<b>ודעת יש בו ג' פירושים</b>: הובאו ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650259\" data-slug=\"or-hatorah-hb\" data-id=\"8316650259\">אוה\"ת נ\"ך שם ע' תתקפח</a>-ט. ובארוכה באוה\"ת משפטים ע' א'קז ואילך."],["63","30","<b>ובמד\"ר ויקרא . . פי' . . על הנהגת המדות . . כל ת\"ח שאין בו דיעה נבילה טובה הימנו</b>: ראה פי' היפה תואר למד\"ר ויקרא שם (פ\"א, טו): כל תלמיד חכם שאין בו דעת כו', דעת הנזכר כאן הוא דרך ארץ, ולכן נבילה טובה ממנו, אף כי היא מאוסה ומסרחת לפני בני אדם, אבל המחוסר דרך ארץ נבזה הוא ונמאס בעיני בני אדם ומחלל גם את התורה. — הובא באוה\"ת נ\"ך שם ע' תתקפט. ובסה\"מ עת\"ר ס\"ע קטז-יז. תרפ\"ד ע' קמז. סה\"ש תרפ\"ד ע' 60."]]],[2002180077,"נא' כלי יקר שפתי דעת (משלי ך' ט\"ו), שהגם שהי' מקורב אעפ\"כ לא הלך עד שקרא לו הקב\"ה שנא' ויקרא אל משה דעת חסרת מה קנית דעת קנית מה חסרת. ובאמת ב' הפירושים אמת, כי הנה אל דעות שיש ב' דיעות כנ\"ל ד\"ע וד\"ת, והנה לפי פי' רש\"י ורי\"ו ז\"ל הדעת הוא בחי' דעת עליון שמחבר בחי' חו\"ב, שהוא בחי' הדעת עליון שמחבר המוחין והוא למעלה מן החכמה כו'. וד\"ת הוא בחי' דעת דבין כתפין שהוא המחבר מוחין ומדות<sup data-n=\"64\">31</sup>, והיינו שהחכם אם שהוא מבין היטב בגדולת הבורא ית' אבל אם אינו בא מזה כלל לבחי' המדות נבילה טובה הימנו והעיקר הוא שמתוך חכמה ובינתו יבא להפך המדות כו'. וזהו דעו כי הוי' הוא האלקים כולל ב' בחי' דעת כו'<sup data-n=\"65\">32</sup>.",[["64","31","<b>דעת עליון שמחבר בחי' חו\"ב . . וד\"ת . . המחבר מוחין ומדות</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370090\" data-slug=\"torah-or\" data-id=\"3901370090\">תו\"א תולדות יט, ב</a>. ועוד."],["65","32","<b>וזהו דעו כי הוי' הוא האלקים . . דעת כו'</b>: בסיום המאמר נמצא עוד קטע [ואח\"כ נרשם ע\"ז שאצ\"ל]: והנה כשיש כל הבחי' מזמור לתודה ועבדו בשמחה ודעו כי ה' הוא אלקים הוא עשנו ולו אנחנו פי' כשהוא עשנו ממילא ולא אנחנו, ופי' ולו הוא קרי בוא\"ו וכתיב אל\"ף, שהוא בחי' מ\"ע ומל\"ת כו'."]]],[2002180078,"<h3>והנה במג\"ע כו' עבדו את ה'</h3>\n<b></b><b>[לד\"ה עבדו את ה' בשמחה]</b>\n<b>והנה</b> במג\"ע אופן רל\"ט פי' עבדו את ה' בשמחה<sup data-n=\"66\">1</sup> ז\"ע בחי' כהנים בעבודתם, ובעבודה בתפילה זהו סידור הקרבנות, והיינו עד ברוך שאמר, בואו לפני ברננה זהו ענין לוים בדוכנם היינו שירן וזמרן שהיו משוררים ומזמרים, ובעבודה בתפילה זהו פסוד\"ז, דעו כי הוי' הוא האלקים ז\"ע ק\"ש שאומרים הוי' אלקינו ה' אחד שזהו בחי' ישראל במעמדן.\n<b>וי\"ל</b> דהנה נודע כי הוי' אלקינו הוא יחוד או\"א, והוי' אחד הוא יחוד זו\"נ, ובכדי שיוכל האדם לבוא לבחי' יחוד זה תקנו אנשי כנה\"ג פסוד\"ז שהם הקדמה באריכות ההתבוננות שנוכל ע\"י אריכות זו לבוא לבחי' הביטול דק\"ש, וכמו",[["66","1","<b>והנה במג\"ע . . פי' עבדו את ה' בשמחה</b>: רשימה זו היא מהדו\"ק מהמאמר שלאח\"ז ד\"ה עבדו את ה' בשמחה. וראה בהנסמן שם. רשימה זו נרשמה בגוכי\"ק לאחרי ההגהות לד\"ה מזמור לתודה וד\"ה ומעתה כו' הריעו לה'. [בגוכי\"ק נרשם לפני רשימה זו: ”עד כאן הועתק\" — ר\"ל שההגהות שנרשמו לפנ\"ז הועתקו ע\"י המעתיק בד\"ה מזמור לתודה. אך רשימה זו לא ניתנה להעתיק]."]]],[2002180079,"שבכדי שיבין התינוק צריכין להסביר לו הרבה כמ\"ש מזה בלק\"ת בד\"ה ענין ק\"ש אחד ואהבת<sup data-n=\"67\">2</sup> פ\"ג. וע\"פ משנת\"ל שפסוד\"ז זהו כעין שיר הלוי', י\"ל דהנה הלוי' נשאו המשכן והארון עם הלוחות, שהארון והלוחות זהו בחי' יחוד או\"א, והמשכן הוא בחי' יחוד ו\"ה, וה\"ז כמו בק\"ש הוי' אלקינו יחוד חו\"ב הוי' אחד יחוד זו\"נ. ועבודתם הי' בשירה וזמרה, פי' שענין השיר הוא לצאת מהגבלת הכלי כמאמר כל בעלי השיר יוצאין בשיר פי' שיוצאין מהגבלתם שהרי גם המלאכים יש להם גוף רק שהוא משני יסודות אש ורוח לבד, וכן הנשמה קודם בואה לגוף היא מוגבלת בהשגתה בג\"ע כמ\"ש מזה בד\"ה אז ישיר<sup data-n=\"68\">3</sup>, ובכדי שיצאו מהגבלתם זהו ע\"י השיר.\n<b>ועד\"ז</b> יובן שיר הלוי' שהוא בחי' רצו\"ש, כמו הרצו\"ש של החיות שפי' רש\"י ע\"פ והחיות רצו\"ש כמראה הבזק (יחזקאל סי' א' י\"ד) כלהבת הכבשן שיוצאה תמיד מפי הכבשן וממהרת לחזור ולכנוס כך כו', ועד\"ז יובן בשיר הלוים<sup data-n=\"69\">4</sup> ובעבודה שבאדם שנק' נר הוי' נשמת אדם, שצ\"ל בבחי' עליה וירידה תמיד בבחי' רצו\"ש בתמידות בלי הפסק, והוא שני מיני התפעלות זא\"ז תמיד, רצוא הוא תשוקה ליכלל ולבטל באוא\"ס, ואח\"כ הוא השוב בקיום התומ\"צ, וחוזר חלילה. והנה כמו שהחיות ע\"י רצו\"ש שלהם והיינו ע\"י שהם מתנשאים ברעש גדול בבחי' התפעלות, עי\"ז הם נושאים את הכסא שמעלים ומגביהים את השכינה, כך הוא ענין השיר של הלוים שהוא ג\"כ רצו\"ש עי\"ז היו בכוחם לשאת את המשכן ואת משכן העדות הוא הארון והלוחות, דהיינו להעלות ולהגביה את בחי' זו\"נ ולקשרו ולחברו בבחי' משכן העדות שהוא הארון והלוחות בחי' חו\"ב, וכמ\"ש ועבד הלוי הוא שעבודת הלוים הוא לקשר ולחבר בחי' עלמא דאתגלי' זו\"נ עם בחי' הוא עלמא דאתכסיא בינה, וחו\"ב הם תרדל\"מ.\n<b>ולכן</b> תקנו אנשי כנה\"ג פסוד\"ז הקדמה לק\"ש, שבכדי שיוכל האדם ליחד בפסוק ראשון דק\"ש שהוא כנגד דעו כי הוי' הוא האלקים שכולל הוי' אלקינו חו\"ב הוי' אחד זו\"נ כמ\"ש המג\"ע, תיקנו אנשי כנה\"ג פסוד\"ז שע\"י פסוד\"ז הוא להיות בחי' רוממות אל בגרונם שעי\"ז ידחה ההסתר דנה\"ב וז\"ע לזמר עריצים, ועי\"ז יתגלה בחי' פנימיות הלב שנוכל לבוא בפסוק ראשון דק\"ש לבחי' ביטול ומס\"נ באחד. וגם כי פסוד\"ז זהו כמו שיר הלוים בחי' רצו\"ש שעי\"ז תרומם הנפש, עד שתוכל ליחד יחוד העליון בפסוק ראשון דק\"ש באמרו הוי' אלקינו דהיינו ג\"כ חיבור",[["67","2","<b>בלקו\"ת בד\"ה ענין ק\"ש אחד ואהבת</b>: פ' ואתחנן יב, ב-ג. [הובא לקמן בד\"ה עבדו את ה' בשמחה]."],["68","3","<b>כמ\"ש בד\"ה אז ישיר</b>: תרל\"ט, הנדפס לעיל. וראה גם ד\"ה זה ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370280\" data-slug=\"torah-or\" data-id=\"3901370280\">תו\"א בשלח סב, ג</a>. [הובאו לקמן בד\"ה עבדו את ה' בשמחה]."],["69","4","<b>ועד\"ז יובן שיר הלוים</b>: בהבא לקמן בפיסקא זו ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380062\" data-slug=\"likkutei-torah\" data-id=\"4001380062\">לקו\"ת פקודי ה, ג</a> [הובא לקמן ד\"ה עבדו את ה' בשמחה]."]]],[2002180080,"ויחוד בחי' הארת הנשמה המלובש בגוף עם מקורה ושרשה שלמעלה בבחי' מזליה כמ\"ש בלק\"ת שה\"ש בד\"ה יונתי בחגוי<sup data-n=\"70\">5</sup> הסלע.\n<b>ובכדי</b> שיהי' עליית השיר דפסוד\"ז בחי' עבודת הלוים צ\"ל נמשך כח ע\"ז, י\"ל שזהו מה שסדרו לאמר פ' הקרבנות תחילה שז\"ע כהנים בעבודתם כנ\"ל, והוא ע\"ד לכה דודי לקראת כלה, שתחילה הוא עבדו את ה' בשמחה בחי' כהנים בעבודתם שהכהן ממשיך הכח בנש\"י שיוכל להתרומם אח\"כ ע\"י בחי' פסוד\"ז שיר הלוים בחי' בואו לפניו ברננה, וע\"י פסוד\"ז רצו\"ש דשיר הלוים, נוכל לבוא לבחי' דעו כי הוי' הוא האלקים בחי' יחוד פסוק דק\"ש בחי' הוי' אלקינו כו'.\n[לד\"ה מזמור לתודה]\nמצה וחמץ<sup data-n=\"71\">6</sup>. תודה או\"א בחכ' אתברירו. ע\"ה אסור לאכול בשר. ת\"ח עד כו' בשרא דתורא. נדרי' חכם מתיר הנדר. כס\"ה דרפ\"א ב'. עבדו. בואו. דעו. כהנים בעבודתם עד ב\"ש. לוים בדוכנם פסוד\"ז. דעו ק\"ש ה' אחד. במ\"ע אופן רל\"ט. וי\"ל דעו ק\"ש כפי' המד\"ר ת\"ח שאין בו דיעה דעת שבין כתפין שמחבר מוחין ומדות ובק\"ש זהו איך שהח' ז\"ר ששרשן ז' מדות בטלים לאלף שזהו לך ה' הגדולה, ועי\"ז כי כל שנמשך להיות היושבי בשמים המשכת היו\"ד דחכ' בשמי' מדות והוא ע\"י הדעת שמחבר הת\"ח בחי' תלמיד שמקבל מחכמה עם המדות שיהי' הנהגת המדות ע\"פ החכמה בתורה כו'.",[["70","5","<b>בלק\"ת שה\"ש בד\"ה יונתי בחגוי</b>: דף טז, ד. יז, א. [הובא לקמן בד\"ה עבדו את ה' בשמחה]."],["71","6","<b>מצה וחמץ</b>: רשימה זו נרשמה בגוכי\"ק בעלה בפ\"ע, והוא רישומי דברים לד\"ה מזמור לתודה דלעיל ולד\"ה עבדו את ה' בשמחה דלקמן."]]],[2002180081,"<h3>עבדו את ה' בשמחה כו' (ג)</h3>\n<b>בס\"ד. (ל\"ג בעומר, ט\"ל).\nתלים סי' ק' פסוק ב'.</b>\n<b>עבדו</b> את ה' בשמחה<sup data-n=\"72\">1</sup>. פי' במג\"ע<sup data-n=\"73\">2</sup> אופן רל\"ט ז\"ע כהנים בעבודתם, ובעבודה בתפילה זהו סידור הקרבנות, והיינו עד ברוך שאמר (שהיא תפילת העשייה), באו לפניו ברננה ז\"ע לוים בדוכנם היינו שירן וזמרן שהיו משוררים ומזמרים, ובעבודה בתפילה זהו פסוד\"ז<sup data-n=\"74\">3</sup>, ואח\"כ ק\"ש וברכותי' שאומרים ה' אלקינו ה' אחד זהו שאמר דעו כי הוי' הוא האלקים על יחוד פסוק הראשון של ק\"ש, ופי' שמע ישראל פי' תחילה<sup data-n=\"75\">4</sup> שז\"ע ישראל במעמדן.\n<b>ולהבין</b> פי' שמע ישראל למי אנו אומרים שמע. הנה אנו אומרים נשמה שנתת בי<sup data-n=\"76\">5</sup> טהורה היא אתה בראת כו', ולכאורה צ\"ל דהל\"ל אתה בראת כו' טהורה היא, שאיך שייך לקרוא אותה בשם טהורה קודם שנבראת<sup data-n=\"77\">6</sup> ונוצרה כו'. אך הענין הוא דלא כל הנשמה מלובשת בגוף שמה שמלובש בגוף מן הנשמה הוא הארה ומקצת לבד מן הנשמה, שהרי המלאך בשליש העולם עומד<sup data-n=\"78\">7</sup>, והנשמות גבוהים יותר מן המלאכים, שהמלאכים הם מחיצוניות הכלים ונשמות הם מבחי' פנימיות הכלים שקרובים להאור, ואיך תוכל להתלבש בגוף האדם שקטן מהכיל את הנפש, אלא",[["72","1","<b>עבדו את ה' בשמחה</b>: מאמר זה קשור עם המאמרים שלפנ\"ז ד\"ה מזמור לתודה וד\"ה ומעתה כו' הריעו לה'. וראה לעיל ד\"ה והנה במג\"ע כו' עבדו את ה' שהוא מהדו\"ק ממאמר זה. מעל המאמר נרשם בגוכי\"ק: ”לא הועתק\" [היינו שמאמר זה לא ניתן להעתיקו]. המאמר מיוסד על כמה דרושים: ד\"ה יונתי בחגוי ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381196\" data-slug=\"likkutei-torah\" data-id=\"4001381196\">לקו\"ת שה\"ש טז, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381197\" data-slug=\"likkutei-torah\" data-id=\"4001381197\">יז, א</a>. וד\"ה ענין ק\"ש בלקו\"ת ואתחנן יב, ב-ג. וד\"ה אז ישיר ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370280\" data-slug=\"torah-or\" data-id=\"3901370280\">תו\"א בשלח סב, ג</a>. וד\"ה אלה פקודי ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380062\" data-slug=\"likkutei-torah\" data-id=\"4001380062\">לקו\"ת פקודי ה, ג</a>. חלק מהמאמר הוא מד\"ה אז ישיר תרל\"ט [כנסמן לקמן בפרטיות].\nלהתחלת המאמר ראה יהל אור לתהלים עה\"פ ע' שסט. וד\"ה עבדו את ה' בשמחה בסה\"מ תרנ\"ח ע' מח.\nמאמר זה נאמר בל\"ג בעומר תרל\"ט יום הילולא דרשב\"י, וראה לקמן בהמאמר שמביא שרשב\"י אמר על עצמו בחד קטירא אתקטרנא כו'.\nראה לקמן מאמר זה בהנחות כ\"ק אדמו\"ר מוהרש\"ב נ\"ע."],["73","2","<b>פי' במג\"ע</b>: ס' מגלה עמוקות. — פי' זה של המגלה עמוקות הובא גם ביהל אור לתהלים שם ע' שסט. ובסה\"מ תרנ\"ח שם ע' מח. וראה גם זח\"ג ח, סע\"א [הובא ביהל אור שם ע' שעה]: עבדו את ה' בשמחה כו' שמחה בכהנא כו' רננה בליואי. עיי\"ש."],["74","3","<b>לוים בדוכנם . . זהו פסוד\"ז</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380062\" data-slug=\"likkutei-torah\" data-id=\"4001380062\">לקו\"ת פקודי שם ה, ג</a>. ח, א."],["75","4","<b>ופי' שמע ישראל פי' תחילה</b>: במגלה עמוקות שם בתחילת הדברים כ': תפלת שחרית התקינו מתחלה לסדר הקרבנות שהם לקביל כהנים בעבודתם, מן ברוך שאמר עד ישתבח הם פסוד\"ז לוים בשירן ובזמרן, ואח\"כ ק\"ש וברכותי' בסוד שמע ישראל שהם ישראל במעמדן כו'."],["76","5","<b>ולהבין פי' שמע ישראל . . אנו אומרים נשמה שנתת בי</b>: בהבא לקמן (עד פיסקא: ואח\"כ אומרים ואהבת) ראה ד\"ה יונתי ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381196\" data-slug=\"likkutei-torah\" data-id=\"4001381196\">לקו\"ת שה\"ש שם טז, ד</a>. יז, א. [והבא לקמן הוא ע\"פ ל' הלקו\"ת שם בשינויי הסדר ובתוס' הגהות וכו']. וראה בכ\"ז בארוכה סה\"מ תרכ\"ט ע' קמה ואילך. תרל\"ה ח\"ב ס\"ע תכד ואילך. תורת שמואל דרושי חתונה ע' סח."],["77","6","<b>ולכאורה צ\"ל . . שאיך שייך לקרוא . . טהורה קודם שנבראת</b>: ראה גם אוה\"ת מטות ע' א'רנו. סה\"מ תרל\"ג ח\"ב ע' שכז. וע' שעב. תרע\"ח ע' שלז. המשך תער\"ב ח\"ג ע' א'תד ואילך. ובכ\"מ."],["78","7","<b>שהרי המלאך בשליש עולם עומד</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381022\" data-slug=\"likkutei-torah\" data-id=\"4001381022\">לקו\"ת האזינו עד, סע\"ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381119\" data-slug=\"likkutei-torah\" data-id=\"4001381119\">ברכה צח, א</a>. וראה סה\"מ תרל\"ג ח\"א ע' כד [ובהנסמן שם]."]]],[2002180082,"שעיקר הנשמה היא למעלה, וקצת הארה מן הנשמה (שהוא בחי' נר\"ן, וזה תלוי לפי עבודתו אם שיאיר בו מבחי' נפש לבד או גם מרוח או מנשמה, שכללות הם בחי' או\"פ) הוא שמאיר בגוף.\n<b>וזהו</b> שארז\"ל גבי חברי דניאל אע\"ג דאינהו לא חזי מזלי' חזי, פי' מזלייהו היינו שרש ומקור הנשמה כמו שהיא למעלה היא חזי שרואה בחי' גילוי אלקים, שהרי א\"א לפרש מזלייהו על בחי' מזל ממזלות הרקיע שהרי ארז\"ל אין מזל לישראל<sup data-n=\"79\">8</sup>, אלא מזלייהו היינו שורש ומקור הנשמה שהיא בבחי' אין, שזהו פי' אין מזל היינו שבחי' אין הוא המזל, והיינו מה שנש\"י עלו במחשבה בחי' מחשבה הקדומה שהיא לבוש הפנימי לבחי' אין בבחי' החכמה שמאין תמצא שנת' בד\"ה מזמור לתודה שהחכמה היא ג\"כ אין ע\"ש. וזהו בנים אתם להוי' אלקי' שכמו שהבן נמשך ממוח האב<sup data-n=\"80\">9</sup> כו' כן נש\"י עלו במחשבה שהיא לבוש הפנימי דחכמה, ומחשבתן של ישראל ארז\"ל במד\"ר ר\"פ בראשית שקדמה לכל דבר היינו גם לתורה, והיינו כמ\"ש בתד\"א שני דברים קדמו לעולם תורה וישראל, דרכן של בנ\"א לומר תורה קדמה, אבל אני אומר ישראל קדמו, שהרי כל התורה היא צו את בנ\"י דבר אל בנ\"י, וא\"כ מוכרח לומר שישראל קדמו. ובזה יובן מה שלפעמים משמע שהתורה למעלה מישראל כמ\"ש בזהר תלת קשרין מתקשראן דא בדא ישראל באורייתא ואורייתא בקוב\"ה, שע\"י אמצעית התורה מתקשראין נש\"י לאלקות, ופעם מצינו להיפך<sup data-n=\"81\">10</sup> שאמרו רז\"ל ע\"פ תורה ציוה כו' מורשה א\"ת מורשה אלא מאורסה שהתורה היא מאורסה לאיש הם נש\"י, שנש\"י נק' חתן שמשפיעים לבחי' כלה היא התורה כו'. אלא שלגבי בחי' הארת הנשמה שמלובשת בגוף נק' ע\"ז אמרו תלת קשרין כו' שע\"י התורה מתקשרת הנשמה שבגוף להקב\"ה, אבל בחי' מזלייהו הוא שרש ומקור הנשמה כמו שהיא למעלה, היא למעלה מבחי' התורה ומשפעת בתורה. שלכן כתיב קדש ישראל לה' ראשית תבואתה, שישראל הם ראשית בחי' תבואתה דתורה, (וי\"ל תבואתה כתי' בה' וקרי בחולם שזהו כמו וא\"ו, שרומז על ה' חומשי תורה שמקרא בעשייה, ה' ספרים דספר תלים, חולם שדומה לוא\"ו רומז על שתא סדרי משנה שמשנה ביצי' לברר אילנא דטו\"ר שמתחיל ביצירה), שהרי כל התורה מליאה ציווים לבנ\"י כו'.\n<b>ועל</b> בחי' זו שבנשמה שהיא בחי' מקיף שבנשמה בחי' מזליא הוא שאומרים בק\"ש שמע ישראל, הוא בחי' ישראל העליון דהיינו הנשמה שבבחי' מקיף, ושם הוי' אלקינו בחי' ביטול במציאות ממש, עד שהוי' אחד בבחי' יחודא עילאה,",[["79","8","<b>וזהו שארז\"ל . . אע\"ג דאינהו לא חזי . . פי' מזלייהו . . אין מזל לישראל</b>: בהבא לקמן ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381010\" data-slug=\"likkutei-torah\" data-id=\"4001381010\">לקו\"ת האזינו עא, ד</a>. סה\"מ תרל\"ג ח\"א ע' רלט. וש\"נ."],["80","9","<b>וזהו בנים אתם . . שכמו שהבן נמשך ממוח האב</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא פ\"ב</a>. ובכ\"מ."],["81","10","<b>שלפעמים משמע שהתורה למעלה מישראל . . ופעם מצינו להיפך</b>: בהבא לקמן עד סוף הפיסקא ראה סה\"מ תרכ\"ט שם ע' קמה ואילך. תרל\"ה ח\"ב שם ע' תכה. תורת שמואל דרושי חתונה שם ע' סח."]]],[2002180083,"כי כל ההתחלקות והשתלשלות ריבוי המדרגות אינם אלא מבחי' זיו והארה בעלמא כו', שהרי אפי' ג\"ע נק' זיו השכינה כמארז\"ל צדיקים יושבים ונהנין מזיו כו', ונק' קבלת פרס לשון פרוסה<sup data-n=\"82\">11</sup> שהוא חלק מובדל מעצמיות אוא\"ס ב\"ה, משא\"כ בבחי' אין הנ\"ל אינו שייך שום התחלקות רק שם הוא יחוד אמיתי. ועל בחי' מזל זה שבנשמה נאמר ונוזלים מן לבנון, מלשון יזל מים מדליו שנוטף ממנו לבחי' הנשמה שמלבשת בגוף<sup data-n=\"83\">12</sup>, שתוכל לבא למס\"נ באחד בבחי' מסירת הרצון להיות בבחי' ועמך לא חפצתי, אפי' בבחי' מקור החיים ומקור התענוגים מאחר דכתיב בי' כי עמך מקו\"ח שמקו\"ח הוא עמך בטל וטפל לך, אי לזאת לא יחפוץ לא בשמים געה\"ע וארץ געה\"ת, ואפי' מה שעמך הוא בחי' מקו\"ח ומקור התענוגים לא חפצתי כלל, כ\"א להיות בבחי' רצון פשוט לאוא\"ס עצמותו ומהותו כו'.\n<b>ואח\"כ</b> אומרים ואהבת בכל כו', שזהו בחי' האהבה שע\"פ הטו\"ד, שהרי אומרים בכל לבבך וארז\"ל בשני יצריך שגם היצה\"ר ישוב לאהבת השם, שלכאורה איך ישוב היצה\"ר לאהבת ה', אלא שיצה\"ר זהו בחי' מדות רעות, כמו שיצ\"ט הוא בחי' מדות הטובות<sup data-n=\"84\">13</sup>, ונת' בד\"ה מזמור לתודה<sup data-n=\"85\">14</sup> שמדות ושכל הם בחי' השתלשלות, שזהו בחי' שערי בינה שמולידים המדות שהוא בחי' ההטיי' שבשכל למדה זו, שהרי לכל מדה יש שכל המולידה ומנהיגה שכאשר יתבונן שטוב לפניו כך, אזי ירצה בזה, ונמצא כי למדות דיצה\"ר יש שכל המולידם ומנהיגם, ובבחי' השכל דיצה\"ר יוכל להבין איך שצריכים להיות ואהבת את הוי'. אמנם זהו ע\"י התבוננות דבשכמל\"ו, שמבחי' אחד א\"א לנה\"ב להתפעל, כ\"א ע\"י שיתבונן בבחי' שם כבוד מלכותו, והיינו שכל התהוות העולמות דבי\"ע נתהוו מבחי' מלכותו ית' שמלך שמו נק' עליהם, שכל התפשטות הארתו הוא רק מבחי' שמו לבד, שהוא הארה בעלמא, שמבחי' זיו זה הוא שנברא יש מאין דבי\"ע, וכבוד מלכותו היינו הארת מבחי' מל', ושם כבוד מלכותו היינו הארה דהארה מבחי' המל' שהוא עצמו רק שמו נק' עליהם כנ\"ל. ובד\"כ ג' בחי' אלו הם נגד ג' עולמות בי\"ע<sup data-n=\"86\">15</sup> כו', ומאחר שכולם נתהוו רק מהארה, צ\"ל היש שנברא מהזיו בטל כמו הזיו עצמו עכ\"פ, שדי לבא כו' להיות כנדון, וכמו זיו השמש בשמש כו'. ובד\"כ זהו בחי' יחו\"ת בחי' ביטול היש לאין.",[["82","11","<b>קבלת פרס לשון פרוסה</b>: ראה [נוסף ל<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381197\" data-slug=\"likkutei-torah\" data-id=\"4001381197\">לקו\"ת שה\"ש שם יז, א</a>]. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370086\" data-slug=\"torah-or\" data-id=\"3901370086\">תו\"א תולדות יח, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380161\" data-slug=\"likkutei-torah\" data-id=\"4001380161\">לקו\"ת תזריע כ, ב</a>. דרושים לשמע\"צ פה, א. ועוד."],["83","12","<b>ונוזלים מן לבנון . . שנוטף ממנו לבחי' הנשמה שמלובשת בגוף</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381010\" data-slug=\"likkutei-torah\" data-id=\"4001381010\">לקו\"ת</a> שה\"ש שם נוסף כאן (בחצע\"ג): ועמ\"ש בד\"ה האזינו השמים [<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381010\" data-slug=\"likkutei-torah\" data-id=\"4001381010\">לקו\"ת האזינו עא, ד</a>], ובד\"ה ציון במשפט תפדה [לקו\"ת דברים א, א]."],["84","13","<b>שיצה\"ר זהו בחי' מדות רעות . . שיצ\"ט . . מדות הטובות</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370174\" data-slug=\"torah-or\" data-id=\"3901370174\">תו\"א מקץ לח, ב</a>. יהל אור לתהלים ע' תלח. ועוד."],["85","14","<b>ונת' בד\"ה מזמור לתודה</b>: תרל\"ט, לעיל ע' שסח. וש\"נ."],["86","15","<b>ושם כבוד מלכותו היינו הארה דהארה מבחי' המל' . . נגד ג' עולמות בי\"ע</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380212\" data-slug=\"likkutei-torah\" data-id=\"4001380212\">לקו\"ת אמור לא, סע\"ג</a>-ד. ועוד."]]],[2002180084,"<b>והנה</b> ארז\"ל כל המאריך באחד<sup data-n=\"87\">16</sup> שצ\"ל אריכות באחד. וזהו שתקנו אנשי כנה\"ג אריכות הדברים בברכת ק\"ש ופסוד\"ז, והן אמת שהתנאים והאמוראים לא היו מאריכים בתפילה כ\"כ<sup data-n=\"88\">17</sup> ובפרט בפסוד\"ז, זהו מפני שהיו מבחי' מוחין דגדלות, ובהתבוננות מועטת הי' די אצלם להיות קבוע בלבם בחי' אחד האמת בל תמוט, כמו רשב\"י שאמר ע\"ע בחד קטירא אתקטרנא, ור\"י הנשיא הי' מעביר ידיו ע\"ג עיניו ודיו, ורב יהודא הי' מצלי מתלתין יומין לתלתין יומין, כי לעורר הרצוא והתשוקה לא היו צריכים אריכות כלל, ועיקר עסקם הי' בבחי' השוב דתורה כו'. אבל אנחנו שנתגשמנו ונתרחקנו מרוחניות, שאנו צריכין להאריך עד שיותפס בשכלינו ולבינו, וכמשל התינוק שצריך להסביר לו ההלכה באריכות הדברים ובמשלים ומליצות שונות, לקרב אל שכלו הקטן לפי קטנו וריחוקו משכל הגמ' ומידיעת עניני טיב העולם במה שההלכה עסוקה בו. ועד\"ז יובן שמפני שנתמעטו הלבבות תקנו אנכה\"ג פסוד\"ז וברכת ק\"ש שע\"י אריכות הדברים יוקבע בלבנו אחדות אלקותו ית', שברכת ק\"ש הוא איך שהשרפים ואופנים וחיות הקדש בטלים, ונה\"ב שרשו משמרי אופנים, ועי\"ז יבוא גם הוא להסכים על בחי' הביטול להיות בכל לבבך בשני יצריך, ובכל נפשך בכל כוחות הנפש, (שז\"ע מס\"נ דנה\"ב, ע\"ד מסירת הרצון כי מה לי קטלא כולא או קטלא פלגא). ופסוד\"ז הם אריכות הסיפור איך שההילול הוא מן השמים וכל צבאם, ומן הארץ<sup data-n=\"89\">18</sup> וכל אשר בה, הגם שנתלבשו בהתלבשות גשמיים עכ\"ז בטלים ואומרים שירה. ועד\"ז צ\"ל בנשמת אדם שהיא חלק אלקה ממעל וירדה רק בשביל בירור הנה\"ב, צריכה להיות בבחי' ביטול בתכלית בבחי' שיר הנשמות, שזהו מצות ק\"ש שע\"ז נא' ברן יחד כל ככבי בקר שקאי על ק\"ש שיר ישראל.\n<b>ואמנם</b> מפני שהגוף והנה\"ב מסתירים לזאת תקנו פסוד\"ז שזהו ע\"ד שיר הלוים<sup data-n=\"90\">19</sup>, דהנה שרש בחי' השיר הוא שבו וע\"י יצאו מההגבלה, וזהו ענין שיר הלוים דכתי' בהם ועבד הלוי הוא, שעבודתם הי' להעלות בחי' עלמא דאתגליא בבחי' הוא היינו בחי' עלמא דאתכסיא, והיא ע\"י השיר שהוא בחי' העלאה מלמטה למעלה וכנודע מענין הניגון שהוא גורם התפעלות שכאשר יתבונן באיזה דבר בלא ניגון, שאף שההתבוננות פועל איזה פעולה עכ\"ז אינה ניכרת כ\"כ, אבל כשמתבונן בהתבוננות זה גופא רק שמשורר איזה שיר וניגון הנה ע\"י הניגון תתעורר ההתפעלות כי הניגון הוא תנועות וכל תנועה מוליד חום שהוא בחי' התפעלות",[["87","16","<b>והנה ארז\"ל כל המאריך באחד . . שתיקנו אנשי כנה\"ג</b>: בהבא לקמן בפיסקא זו ראה ד\"ה ענין ק\"ש בלקו\"ת ואתחנן שם יב, ב-ג [והוא ע\"פ ל' הלקו\"ת שם בשינויים והוספות]. וראה גם לעיל ח\"א ע' קסו."],["88","17","<b>שהתנאים והאמוראים לא היו מאריכים בתפילה כ\"כ</b>: בלקו\"ת ואתחנן שם נוסף כאן (בחצע\"ג): ועמ\"ש מזה בד\"ה ויעש משה נחש נחושת [לקו\"ת חוקת סב, א]."],["89","18","<b>איך שההילול הוא מן השמים . . ומן הארץ</b>: ראה לעיל ח\"א ד\"ה הללוי' גו' מן השמים ע' קסה ואילך."],["90","19","<b>ואמנם מפני שהגוף . . שיר הלוים</b>: הבא לקמן בפיסקא זו הוא מד\"ה אז ישיר תרל\"ט הנדפס לעיל ח\"א ע' קנד. וראה גם ד\"ה אז ישיר ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370280\" data-slug=\"torah-or\" data-id=\"3901370280\">תו\"א בשלח סב, ג</a>."]]],[2002180085,"לצאת מן הכלי כו'. וזהו משארז\"ל כל בעלי השיר יוצאים בשיר ונמשכים בשיר, וקאי על מלאכים שכאשר יוצאים מגדר הכלי הוא ע\"י השיר דוקא, כי המלאכים יש להם ג\"כ גופים רק שהגופים שלהם הוא מאש ורוח<sup data-n=\"91\">20</sup> בלבד כמ\"ש עושה מלאכיו רוחות משרתיו אש לוהט. וכן אפי' נשמות בג\"ע כאשר יוצאים מהשגה זו להשיג השגה יותר עליונה הוא ג\"כ ע\"י השיר, כי השגה הוא ג\"כ בחי' גבול בחי' כלי, ולכן כאשר צריכים לצאת מהשגה זו להשיג השגה עליונה יותר הוא ג\"כ ע\"י השיר, וזהו כל בעלי השיר הם מלאכים ונשמות יוצאין בשיר כו'.\n<b>ועד\"ז</b> יובן ענין שיר הלוים<sup data-n=\"92\">21</sup> להעלות עלמא דאתגלי' ולחברה בבחי' עלמא דאתכסיא שנק' הוא. וזהו שהלוים נשאו המשכן, וגם הארון והלוחות, ונודע כי משכן הוא ו\"ה והארון והלוחות הם י\"ה<sup data-n=\"93\">22</sup>, (י\"ל לוחות עשה\"ד יו\"ד ארון אור נו\"ן), וע\"י הזמרה שלהם הי' ביכולתם ג\"כ לשאת המשכן בחי' ה' תתאה עם בחי' וא\"ו, לחברם עם בחי' י\"ה משכן העדות. ועד\"ז יובן שע\"י פסוד\"ז יכול האדם לבוא בק\"ש לבחי' יחו\"ע שבפסוק ראשון של ק\"ש, ובחי' יחו\"ת שבבשכמל\"ו, שעי\"ז ואהבת בבחי' אהבה הנמשכת מבחי' הטו\"ד. דהנה שיר הלוים הוא ע\"ד דכתיב והחיות רצוא ושוב כמראה הבזק (יחזקאל א' י\"ד) ופירש\"י כלהבת הכבשן שיוצאה תמיד מפי הכבשן וממהרת לחזור ולכנוס כך החיות כו' ונרתעין לאחוריהם מפחד השכינה. וכך נה\"א שבאדם שנק' נר הוי' כמ\"ש נר ה' נשמת אדם צ\"ל עולה ויורד בבחי' רצוא ושוב בתמידות בלתי הפסק, והוא ב' מיני התפעלות הללו זא\"ז בתמידות, וכמ\"ש והחיות רצו\"ש פי' אחר הרצוא שוב, ואחר השוב רצוא, וכן חוזר חלילה, וז\"ע שיר הלוים על הקרבן. וזהו ג\"כ ענין שנשאו את המשכן גם מפני שע\"י השיר ברצוא ושוב מגביהים ומרוממים למשכן עד שנעשה יחוד עליון בבחי' משכן העדות, וכמו למעלה שחיות נושאות את הכסא ע\"י שהם מתנשאים ברעש גדול בהתפעלות עי\"ז הם מגביהים ומעלים את השכינה.\n<b>וכך</b> הוא ענין שיר הלוים<sup data-n=\"94\">23</sup> להיות בחי' התפעלות הנפש מצד עצמה, ולא מצד השגה להוליד מבינתו, מאחר שעבודתו הוא בבחי' הוא, אתה הוא ה' לבדך כו' דלית מחשבה תפיסא בי' כלל, אלא התפעלות רעותא דלבא שיהי' נוגע עד הנפש נקודת הלב, ולא להיות בחי' מקיף לבד (כמ\"ש בת\"א בד\"ה אז ישיר), ועי\"ז הם נושאים את",[["91","20","<b>המלאכים יש להם ג\"כ גופים . . מאש ורוח</b>: ראה תו\"א בראשית ד, ב. ובכ\"מ."],["92","21","<b>ועד\"ז יובן ענין שיר הלוים</b>: בהבא לקמן בפיסקא זו ראה ד\"ה אלה פקודי ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380062\" data-slug=\"likkutei-torah\" data-id=\"4001380062\">לקו\"ת פקודי ה, ג</a>. [והוא ע\"פ ל' ה<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380072\" data-slug=\"likkutei-torah\" data-id=\"4001380072\">לקו\"ת</a> בשינויים והוספות]. וראה גם שם ח, א."],["93","22","<b>ונודע כי משכן הוא ו\"ה והארון והלוחות הם י\"ה</b>: ראה בכ\"ז בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380058\" data-slug=\"likkutei-torah\" data-id=\"4001380058\">לקו\"ת פקודי שם ד, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380064\" data-slug=\"likkutei-torah\" data-id=\"4001380064\">וראה שם ו, א</a> ואילך."],["94","23","<b>וכך הוא ענין שיר הלוים</b>: בהבא לקמן בפיסקא זו (עד התיבות: עבודה תמה) ראה ד\"ה אז ישיר ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370280\" data-slug=\"torah-or\" data-id=\"3901370280\">תו\"א בשלח שם סב, ג</a> [והוא ע\"פ ל' התו\"א בשינויים והוספות]."]]],[2002180086,"המשכן דהיינו להעלות ולהגביה זו\"נ ולקשרו ולחברו בבחי' משכן העדות בחי' חו\"ב בחי' י\"ה. ועד\"ז נתקן פסוד\"ז שנק' זמרה שהם כעין ניגון שהוא רק הרחבת הדבור וביאור הענין בתוס' ביאור לפרש הדבר היטב להלהיב לבו ונפשו שיתפעל מזה, משא\"כ כשאומר הפסוקים ואינו נוגע לנקודת לבבו אין זה בחי' זמרה וניגון ואין זה עבודה תמה, (כמ\"ש בד\"ה אז ישיר בת\"א<sup data-n=\"95\">24</sup>). ונמצא כי סדר העבודה שתקנו פסוד\"ז בכדי לבא לק\"ש, שז\"ע להיות רוממות אל בגרונם שעי\"ז ידחה ההסתר דנה\"ב, והו\"ע זמיר ערצים, ועי\"ז יתגלה פנימיות הלב לבוא בפסוק ראשון דק\"ש לביטול דמס\"נ באחד. ונמצא פסוד\"ז כמו זמרה דלוים שנשאו המשכן שז\"ע לנשאות בחי' יחו\"ת, ואח\"כ פסוק ראשון דק\"ש יחו\"ע כמו משכן העדות.\n<b>ואמנם</b> בכדי להיות נר ה' נשמת אדם בבחי' רצו\"ש, זהו ע\"י הכהנים שהם ממשיכים זה בנש\"י כמ\"ש ובהעלות אהרן את הנרות, וכתי' בהעלותך את הנרות הם בחי' נר הוי' שתהי' בבחי' רצו\"ש דנר כו'. וזהו עבדו את ה' בשמחה, שכדי להיות בחי' שמחה גילוי פנימיות צ\"ל עבודה תחילה, זהו סידור פרשות הקרבנות, ואיזהו, והודו, שזהו ג\"כ הפסוקים שהיו אומרים לפני הארון בתמיד של שחר ובתמיד של בין הערביים, שבתמיד של שחר היו אומרין מן הודו עד שירו לה' ובתמיד של בין הערביים עד והלל לה' (והארון עם הלוחות זהו י\"ה כנ\"ל), וזהו עבודת הכהן שממשיך מלמעלמ\"ט כח בנש\"י להעלות את הנרות דנש\"י. ואח\"כ באו לפניו לבחי' פנימיות הלב דק\"ש, זהו ע\"י רננא שיר הלוים פסוד\"ז, שעי\"ז דעו בחי' היחוד דק\"ש בבחי' יחו\"ע ויחו\"ת ד\"ע וד\"ת, שכ\"ז נכלל בתיבת אלו כי הוי' הוא האלקים, הוי' הוא בחי' ה' אלקינו, ונודע כי בפסוק ראשון לבד נאמר אלקינו שמשה כלל עצמו ג\"כ לפי שזכה לבינה, אבל בואהבת אמר אלקיך<sup data-n=\"96\">25</sup> בחי' יחו\"ת ונכלל בכלל תיבת האלקים שנדעו ליחד שבחי' יחו\"ת ויחו\"ע הכל אלקות כמ\"ש בד\"ה מזמור לתודה<sup data-n=\"97\">26</sup> שגם ד\"ת הוא אמת, ופי' דעו כי הוי' הוא האלקים שכולא חד ואין עוד מלבדו כלל.",[["95","24","<b>בת\"א בד\"ה אז ישיר . . בד\"ה אז ישיר בת\"א</b>: פ' בשלח שם סב, ג."],["96","25","<b>ונודע כי . . נאמר אלקינו שמשה כלל עצמו . . שזכה לבינה . . בואהבת אמר אלקיך</b>: ראה בכ\"ז אוה\"ת ואתחנן ע' רכ."],["97","26","<b>בד\"ה מזמור לתודה</b>: תרל\"ט, נדפס לעיל."]]],[2002180087,"<h3>מי זאת הנשקפה כו' (א)</h3>\n<b></b><b>בס\"ד. [ש\"פ במדבר, ט\"ל].</b>\n<b></b>הדגלים כו' ענין המן כו' ב' בחי' הילוך בחול, בשבת - (פרק: א-ד)\nבמדבר\n<b>מי</b> זאת הנשקפה<sup data-n=\"98\">1</sup> כמו שחר יפה כלבנה ברה כחמה איומה כנדגלות, איומה כנדגלות הוא ענין הדגלים שהיו במדבר כו', והנה מתחלה כתיב מי זאת הנשקפה כמו שחר כו' ואח\"כ איומה כנדגלות, וכמו בשעת עשיית הדגלים שנא' מתחלה שאו את ראש כל עדת בנ\"י לגלגלתם, ואח\"כ כתיב עשיית הדגלים, והיינו שכדי שיהי' בחי' דגלים הוצרך להיות מתחלה שאו את ראש בנ\"י לגלגלתם כו', וכך כאן כתיב מי זאת הנשקפה כמו שחר ואח\"כ כתיב איומה כנדגלות. והנה להבין זה צ\"ל מתחלה מ\"ש ברבות אמור פך\"ח ע\"פ כי תבאו אל הארץ כו' והבאתם את עומר ראשית קצירכם אל הכהן, א\"ר ברכי' כשנתתי לכם את המן נתתי עומר לכל אחד ואחד מכם הה\"ד עומר לגולגולת, ועכשיו שאתם נותנים לי את העומר אין לי אלא עומר אחד מכולכם, ולא עוד אלא של שעורים.\n<b>ולהבין</b> זה י\"ל מתחלה ענין המן<sup data-n=\"99\">2</sup>, דהנה במן כתיב ויאמר משה אכלוהו היום כי שבת היום להוי' היום לא תמצאוהו בשדה, וי\"ל למה לא ירד המן בשבת והלא כל השפעות שבעוה\"ז הגשמיי' אינן נעצרין אפי' בשבת והכל נשפע מלמעלה שהרי אין לך עשב מלמטה כו', וגם מהו אכלוהו היום והלא כל הימים אכלו אותו. אך הנה כתיב הנני ממטיר לכם לחם מן השמים כו' למען אנסנו הילך בתורתי אם לא, ולהבין למה הקדים המן לקבלת התורה למען אנסנו אם יוכל להיות קבלת התורה, ואיזה שייכות יש לנסיון זה על התורה, וגם מהו לשון הילך בתורתי הל\"ל אם יקיימו תורתי כו'.\n<b>אך</b> הנה ידוע שהתורה הוא קיום העולם, שקיום עש\"מ הוא ע\"י עשה\"ד כו', וכמ\"ש אם לא בריתי יומם ולילה חקות שמים וארץ לא שמתי. וכן ארז\"ל תנאי התנה הקב\"ה עם מע\"ב אם יקיימו ישראל את התורה כו', וכן איתא בזהר באורייתא אתקיים עלמא כו', וכן אמרו בזהר ובמד\"ר ע\"פ עשרה עשרה הכף בשקל הקדש שעה\"ד מכוונים נגד עשרה מאמרות, שע\"י עשה\"ד נמשך קיום העולם, וכן אמרו",[["98","1","<b>מי זאת הנשקפה</b>: מאמר זה (מלבד ההתחלה) והמאמר שלאחריו (ד\"ה אך להבין מ\"ש למען אנסנו, מלבד הסיום [פרק ו']) מיוסדים והגהות על ד\"ה ויאמר משה אכלוהו היום ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370290\" data-slug=\"torah-or\" data-id=\"3901370290\">תו\"א בשלח סה, א</a> ואילך. [ונו\"א ממאמר התו\"א בס' מאמרי אדה\"ז תקס\"ח ח\"א ע' כח ואילך. וביאור ע\"ז שם ע' לד ואילך. ונו\"א במאמרי אדה\"ז הנחות הר\"פ ע' עב ואילך. ובארוכה במאמרי אדהאמ\"צ שמות ח\"א ע' קנו ואילך. ועם הגהות וכו' באוה\"ת בשלח ע' תקצה ואילך. תרח ואילך. תרכח ואילך. וביאור ע\"ז שם ע' תרלא ואילך. שם (כרך ז) ע' ב'תרעח ואילך. ד\"ה ויאמר גו' אכלוהו היום בסה\"מ תשל\"ו ע' 110 ואילך].\nלכמה מעניני המאמר ראה גם סה\"מ מלוקט ח\"א ע' רלה ואילך. ובארוכה המשך תער\"ב ח\"ב ע' א'סא ואילך. וראה גם ד\"ה ויאמר גו' אכלוהו היום בס' פלח הרמון שמות ע' רז ואילך. [מחגה\"ש תרי\"ב].\nוראה לקמן בהוספות הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה, נדפסה לקמן בהוספות."],["99","2","<b>ולהבין זה י\"ל מתחלה ענין המן</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370290\" data-slug=\"torah-or\" data-id=\"3901370290\">תו\"א בשלח שם סה, סע\"א</a>-ב."]]],[2002180088,"עוד במד\"ר ויקהל פמ\"ח אלה תולדות השמים והארץ אלה בזכות מי נבראו ובזכות מי הן עומדים בזכות ואלה שמות בנ\"י, ואלה בזכות מי נבראו ובזכות מי הן עומדים בזכות אלה העדות והחוקים כו', שנמצא בזכות התורה עומדים שמים וארץ, וכן כתיב אנכי עשיתי ארץ ואדם עלי' בראתי, בראתי בגימ' תרי\"ג, וי\"ל מה שייכות קיום העולם לתורה דוקא, שהרי ברה\"ע הי' קודם מ\"ת כו'.\n<b>אך</b> הענין הוא, דהנה כתיב אתה הוא הוי' לבדיך<sup data-n=\"100\">3</sup> אתה עשית את השמים כו', והנה את עשית את השמים כו' כתיב חסר ה', והיינו כי אתה הוא הוי' לבדיך זהו ע\"ד מ\"ש עד שלא נבה\"ע הי' הוא ושמו בלבד, והיינו שזה קאי על עולם האצי', וזהו עד שלא נברא העולם דהיינו עולם הבריאה הי' הוא ושמו בלבד, שהי' מאיר שם בחי' גילוי אוא\"ס ממש ואיהו וחיוהי חד ואיהו וגרמוהי חד כו', וכמ\"ש כל הנק' בשמי ולכבודי בראתיו כו' שנת' בכ\"ד שכל הנק' בשמי קאי על עולם האצי'<sup data-n=\"101\">4</sup>, שנק' בשם שמי, וא\"כ הי' הוא ושמו קאי ג\"כ על עולם האצי'. וזהו אתה הוא הוי' לבדיך מלא בה', והיינו שבאצי' מאיר כל הה' פרצופים בשלימות שהם כנגד ד' אותיות של שם הוי' וקוש\"י כו' שהוא בחי' כתר חו\"ב וז\"א ומל'. אך את עשית את השמים כו' חסר ה', והיינו שכדי שיתהוה בחי' עולמות בי\"ע חסר ה' שאינו מאיר שם בחי' ה' פרצופים בשלימות כי אימא מקננא בכורסיא, אבל בחי' חכ' וכתר אינו מאיר שם, וביצי' מאיר רק בחי' ז\"א וזהו חסר ה', והיינו שהוא ע\"ד מ\"ש בהבראם בה' בראם, שהה' הוא זעירא, והיינו שיש ג' בחי' אותיות אתוון רברבין ואתוון בינוני' ואתוון זעירין<sup data-n=\"102\">5</sup>, וכל התורה היא באתוון בינונים, ואתוון זעירין היינו שהוא בחי' קטנות וצמצום, וזהו חסר ה' שנתצמצם בחי' הה' שאינו מאיר שם בשלימות כו' שהוא בחי' אתוון זעירין כו'. ולהבין מהו אתוון זעירין, הענין הוא דהנה כתי' ואת תדבר אלינו אמר להם משה התשתם את כחי כנקבה, והיינו כי את חסר ה' הוא לשון נקבה, והנה גם כאן שנא' את עשית את השמים שהוא לשון נקבה, והיינו שיש שני בחי' אותיות וכמ\"ש בזהר ע\"פ לסוסתי ברכבי פרעה שיש סוסים נוקבין וסוסים דוכרין<sup data-n=\"103\">6</sup>, סוסים הוא בחי' אותיות וכמ\"ש במ\"ת כי תרכב על סוסיך מרכבותיך ישועה שנת' בכ\"ד",[["100","3","<b>אך הענין הוא דהנה כתיב אתה הוא הוי' לבדך</b>: בהבא לקמן ראה אוה\"ת בשלח שם ע' תרכז. וראה בכ\"ז בארוכה אוה\"ת ויחי שפה, ב ואילך. שצה, ב ואילך. סה\"מ תרל\"א ע' פ ואילך. תרל\"ב ח\"ב ע' תצ ואילך. תרנ\"ג ע' רנח-ט. תר\"ס ע' מג ואילך. עזר\"ת ע' קיז ואילך. קונטרסים ח\"ב רצו, א. תש\"א ע' 149. סה\"מ מלוקט ח\"ג ע' רכב ואילך."],["101","4","<b>שנת' בכ\"ד שכל הנק' בשמי קאי על עולם האצי'</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370010\" data-slug=\"torah-or\" data-id=\"3901370010\">תו\"א בראשית ג, א</a>. מאמרי אדה\"ז תקס\"ז ע' לב. אוה\"ת בראשית (כרך ו) תתרמו, א. ועוד."],["102","5","<b>שיש ג' בחי' אותיות . . רברבין . . בינוני' . . זעירין</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316520282\" data-slug=\"or-hatorah-hb\" data-id=\"8316520282\">אוה\"ת בשלח שם ע' תרכו</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380079\" data-slug=\"likkutei-torah\" data-id=\"4001380079\">לקו\"ת ויקרא א, סע\"ב</a>. ובארוכה מאמרי אדה\"ז תקס\"ח ח\"ב ע' תרסח ואילך. וע' תרעז. ביאוה\"ז להצ\"צ ח\"א ע' קעו ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200012\" data-slug=\"or-hatorah-hb\" data-id=\"8159200012\">אוה\"ת ויקרא (כרך ג) ע' תשכד</a> ואילך. סה\"מ תרע\"ח ע' רלד ואילך. תרצ\"ט ע' 203 ואילך. תש\"ה ע' 130 ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171001\" data-slug=\"likkutei-sichot\" data-id=\"1300171001\">לקו\"ש חי\"ז ע' 1</a> ואילך."],["103","6","<b>שני בחי' אותיות . . לסוסתי ברכבי . . סוסים נוקבין וסוסים דוכרין</b>: ראה בכ\"ז בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370285\" data-slug=\"torah-or\" data-id=\"3901370285\">תו\"א בשלח סג, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370288\" data-slug=\"torah-or\" data-id=\"3901370288\">סד, ג</a> ואילך."]]],[2002180089,"שהם בחי' אותיות<sup data-n=\"104\">7</sup>, ויש שני בחי' אותיות דוכרין ונוקבין, והיינו שיש בחי' אותיות דמ\"ה וב\"ן, ב\"ן בגימט' בהמה שהוא בחי' אתוון נוקבין שהתהוות בי\"ע הוא רק מבחי' אותיות דשם ב\"ן, וזהו בחי' אתוון זעירין כו', משא\"כ באצי' מאיר שם בחי' שם מ\"ה כו'.\n<b>אך</b> הנה זהו בתחלת ברה\"ע, ואמנם ע\"י התורה ממשיכים מבחי' אתה הוא הוי' לבדיך בבחי' אתה עשית את השמים, כי תורה היא בחי' ה' חומשי תורה שהוא מבחי' ה' עילאה אתה הוא ה' לבדיך כו', וכמ\"ש בלק\"ת מהאריז\"ל ס\"פ האזינו שחמשה חומשי תורה הם כנגד חמשה פרצופים דאצי' שזהו ענין אתה מלא ה' כנ\"ל. וזהו מ\"ש תורת ה' תמימה משיבת נפש כו' שיש שם ג' פסוקים שהם מן שתים שתים פסקה, וכל פסקה ופסקה מן חמשה תיבות כמ\"ש במד\"ר נשא<sup data-n=\"105\">8</sup> פי\"ג דרנ\"ד ב' בקרבן נתנאל, והיינו לפי שהוא מבחי' ה' עילאה בבחי' ו' מדות ו' סדרי משנה<sup data-n=\"106\">9</sup>. וזהו מ\"ש נגילה ונשמחה בך, שע\"י בך שהוא בחי' ך\"ב אותיות התורה עי\"ז נגילה ונשמחה בך דהיינו בעצמותו ומהותו ית' כו'. וזהו שע\"י התורה נתקיים העולם, שהוא המשכה מבחי' אתה הוא הוי' לבדיך כו' בבחי' אתה עשית את השמים כו' שמתחלה הי' חסר ה' כו', וע\"י התורה נתמלא החסרון. וזהו הילך בתורתי שהילוך הוא בחי' המשכה מלמעלה למטה כו'.\nב) <b>אך</b> הנה א\"א להיות המשכה מלמעלה למטה בלתי שיהי' מתחלה העלא' מלמטה למעלה, וכמ\"ש אם ישים אליו לבו רוחו ונשמתו אליו יאסוף, והנה העלאה זו הוא בחי' תפלה.\n<b>ובזה</b> יובן מה שהמלאכים ביקשו את התורה<sup data-n=\"107\">10</sup> וכמ\"ש תנה הודך על השמים והשיבם כלום יצה\"ר יש ביניכם כו', ולכאורה הלא בלתי יצה\"ר יכולים לקיים יותר<sup data-n=\"108\">11</sup> את התורה, ומה זו תשובה על שאלתם. אך הענין הוא דהנה יתרון האור הוא מתוך",[["104","7","<b>כי תרכב על סוסיך . . שנת' בכ\"ד שהם בחי' אותיות</b>: ראה הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370522\" data-slug=\"torah-or\" data-id=\"3901370522\">תו\"א מג\"א קטז, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381174\" data-slug=\"likkutei-torah\" data-id=\"4001381174\">לקו\"ת שה\"ש יא, סע\"ב</a> ואילך. סה\"מ תרכ\"ז ע' רו ואילך. תרל\"ד ע' שנג. שנט. [ובהנסמן בהע' שלפנ\"ז]."],["105","8","<b>שיש שם ג' פסוקים . . כמ\"ש במד\"ר נשא</b>: ז\"ל המד\"ר שם (פי\"ג, ט\"ז): כבשים בני שנה חמשה, חמשה כנגד ג' פסוקים של תורה שבהם ו' סדרי משנה, והן מן שתים פסקה, וכל פסקה ופסקה מן חמשה תיבות (הג' פסוקים כל פסוק נחלק לשתים הרי ששה חצאי פסוקים כל אחד במעלה אחרת של תורה, ובכל חצי פסוק חמשה תיבות — פ' מהרז\"ו), ואלו הם: תורת ה' תמימה משיבת נפש, עדות ה' גו', פקודי ה' וגו', מצות ה' וגו', יראת ה' וגו', משפטי ה' וגו'. [ועיי\"ש עוד במדרש שו' חצאי פסוקים אלו הם כנגד ששה סדרי משנה]."],["106","9","<b>שהוא מבחי' ה' עילאה בבחי' ו' מדות ו' סדרי משנה</b>: ראה לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב: יש כאן ג' פסוקים ובכל אחד יש ב' ענינים ובכל ענין יש ה' תיבות, והנה ה' תיבות הם ה\"א עילאה, וג' פסוקים ובכל אחד ב' ענינים הם וא\"ו, והוא שמה\"א נמשך לוא\"ו."],["107","10","<b>ובזה יובן מה שהמלאכים ביקשו את התורה</b>: בהבא לקמן בפרק זה ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370291\" data-slug=\"torah-or\" data-id=\"3901370291\">תו\"א בשלח שם סה, ב</a>."],["108","11","<b>כלום יצה\"ר יש ביניכם . . ולכאורה הלא בלתי יצה\"ר יכולים לקיים יותר</b>: בכ\"ז ראה גם לעיל ח\"א ד\"ה ראה ריח בני. ולקמן ד\"ה צאינה וראינה פ\"ב (באו\"א)."]]],[2002180090,"החשך דוקא, כד אתכפי' סט\"א אסתלק יקרא דקוב\"ה בכולהו עלמין, ואז יכול להיות המשכת התורה כי התורה נמשכה בכל יום, וזהו שאנו מברכין נותן התורה שמשמעו לשון הוה<sup data-n=\"109\">12</sup> והיינו שתמיד נמשך המשכת התורה, וכדי שיומשך המשכת התורה זהו ע\"י אתכפי' סט\"א דוקא. וזהו שניתנה התורה במדבר דוקא לפי שמדבר הוא מדבר העמים שהוא היפך מא\"י, כי בא\"י נמשך השפעות דקדושה כו', משא\"כ מדבר הוא היפך מזה, לכן ניתנה התורה דוקא במדבר כדי להפוך את המדבר, וכד אתכפי' סט\"א כו', וזהו ימצאהו בארץ מדבר יסובבנהו כו'. והנה בחי' אתכפי' זו הוא נעשה ע\"י התפלה, כי הנה תפלה נק' בשם אכילה וכמ\"ש באתי לגני אכלתי יערי עם דבשי כו', יערי הוא בחי' יוצר אור, דבשי הוא בחי' ק\"ש<sup data-n=\"110\">13</sup>, והיינו שכמו למשל האכילה הוא בחי' בירור שהטוב והמובחר שבמאכל נתהפך לדם האדם ועולה ללב ומוח, והפסולת נדחה לחוץ, וכך הוא ענין התפלה הוא בחי' בירור הטוב והרע וכמ\"ש רוממות אל בגרונם עי\"ז נעשה חרב פיפיות לעשות נקמה כו' שהוא בחי' הרע שבו עצמו כו'. וזהו מ\"ש מצרף לכסף וכור לזהב<sup data-n=\"111\">14</sup> ואיש לפי מהללו, שבמהללו בתפלה מצרף, שהגו סיגים מכסף, והמובחר נבלע באלקות ואהבת בכל לבבך כו', והפסולת נדחה לחוץ בשמ\"ע באמרו סלח לנו ואשמנו להעביר פסולת ולדחותו. וזהו שבתפלה דוקא אנו אומרים סלח לנו<sup data-n=\"112\">15</sup> כי חטאנו, והיינו שקודם התפלה דרך איש ישר בעיניו, אך ע\"י התפלה שהיא בחי' רוממות אל בגרונם התבוננות באלקות עי\"ז הוא מרגיש את הרע שבנפשו, ואפי' הרע הדק הוא ג\"כ מרגיש, וזהו ענין בירור שנתברר הרע מן הטוב ונעשה אתכפי' סט\"א, ולזה נק' התפלה בשם אכילה כו'. ולזה המלאכים שאין להם יצה\"ר לא ניתנה התורה להם לפי שאין להם בחי' בירור הרע כו'. וזהו מ\"ש הילך בתורתי שהוא כולל ב' בחי' הילוך דהיינו ממטה למעלה שהוא בחי' תפלה ומלמעלה למטה שהיא בחי' תורה, כי המשכת בחי' תורה א\"א להיות אלא אחר התפלה. וזהו משארז\"ל אבא בנימין אומר כל ימי הייתי מצטער על תפלתי שתהא סמוכה למטתי דוקא, בכדי שיהי' תחלה תפלה ואח\"כ תורה<sup data-n=\"113\">16</sup> כו'.\nג) <b>והנה</b> כמו שיש ב' בחי' הילוך בכל ימי השבוע כמו\"כ בשבת יש ג\"כ ב' בחי' הילוך, וכמשארז\"ל א\"ר יוחנן אלמלא שמרו ישראל שתי שבתות כהלכתן",[["109","12","<b>וזהו שאנו מברכין נותן התורה . . לשון הוה</b>: ראה תו\"א בשלח שם. ואוה\"ת בשלח שם ע' תקצז. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380172\" data-slug=\"likkutei-torah\" data-id=\"4001380172\">לקו\"ת תזריע כג, א</a>. מאמרי אדהאמ\"צ שמות ח\"א ע' קעה. וש\"נ. לקמן ע' תה."],["110","13","<b>אכלתי יערי . . בחי' יוצר אור דבשי הוא בחי' ק\"ש</b>: ראה סה\"מ תרל\"ג ח\"א ע' קט-י. וש\"נ."],["111","14","<b>וזהו מ\"ש מצרף לכסף וכור לזהב</b>: בהבא לקמן ראה הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370497\" data-slug=\"torah-or\" data-id=\"3901370497\">תו\"א פ' תשא קיא, ג</a>. סה\"מ תר\"ל ע' קיב. תרל\"ב ח\"א ע' צב. ועוד."],["112","15","<b>וזהו שבתפלה דוקא אנו אומרים סלח לנו</b>: בכ\"ז ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370498\" data-slug=\"torah-or\" data-id=\"3901370498\">תו\"א תשא שם קיא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380431\" data-slug=\"likkutei-torah\" data-id=\"4001380431\">לקו\"ת בהעלותך ל, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380858\" data-slug=\"likkutei-torah\" data-id=\"4001380858\">תצא לה, סע\"ב</a> ואילך. דרושים לש\"ש סה, ג. סה\"מ תר\"ל שם ע' קיג. תרל\"ב ח\"א שם ע' צג. לקמן ד\"ה וידבר גו' המטות פ\"ד. ד\"ה תקעו בחודש פ\"ד. ועוד."],["113","16","<b>משארז\"ל . . תפלתי שתהא סמוכה למטתי . . תפלה ואח\"כ תורה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381112\" data-slug=\"likkutei-torah\" data-id=\"4001381112\">לקו\"ת ברכה צו, ב</a>. ועוד. וראה הערת כ\"ק אדמו\"ר זי\"ע בהוספות להערות וציונים ללקו\"ת שם."]]],[2002180091,"מיד היו נגאלים, שיש ב' בחי' שבת<sup data-n=\"114\">17</sup>, דהיינו בכל שבת יש ב' בחי' מלמטה למעלה ומלמעלה למטה, וזהו כהלכתן ב' בחי' הילוך, דהיינו שבת דמעלי שבתא הוא בחי' העלאה ממטה למעלה וכמ\"ש כי ששת ימים עשה ה' כו' וביום השביעי שבת כו', דהיינו כמו למשל מי שעשה מלאכה שמחשבתו ושכלו מתלבש במעשה ההיא ואח\"כ כששובת מהמלאכה אז חוזר שכלו ומח' למקורו ושרשו, כמו\"כ למעלה אף שאין שייך בחי' שביתה ממלאכה שהרי לא בעמל ולא ביגיעה ברא הקב\"ה עולמו אעפ\"כ מה שנתלבש בבחי' עש\"מ שהוא בחי' מילין דהדיוטא ולאו אורחא דמלכא לאשתעי כו', ובשבת שהוא בחי' שביתה מעש\"מ שהוא בחי' העלאה למקורו ושרשו כו', וזהו שבת דמעלי שבתא שהוא בחי' העלאה כו', ושבת דיומא הוא בחי' המשכה מלמעלמ\"ט שהוא בחי' המשכת תענוג עליון וכמ\"ש וקראת לשבת ענג אז תתענג על הוי' כו', וזהו ענין ב' שבתות כהלכתן כו'.\n<b>וההפרש</b> שבין ההילוך שבכל ימי השבוע ובין בחי' ההילוך שבשבת<sup data-n=\"115\">18</sup>, והיינו שבשבת הוא בבחי' פנימיות, ובחול הוא רק בחי' חיצוני', שתפלה ותורה דשבת הוא באופן אחר ממש מבחי' תפלה ותורה דחול<sup data-n=\"116\">19</sup>. וע\"ד שאנו רואים ההפרש שבין אכילה דחול לבחי' אכילה דשבת<sup data-n=\"117\">20</sup>, וכמ\"ש צדיק אוכל לשובע נפשו ובטן רשעים תחסר, בטן רשעים תחסר קאי על בחי' אכילה דחול שהוא לברר את הניצוצות דקדושה שנפלו בשבה\"כ לבחי' ק\"נ, וע\"י האכילה שאדם אוכל ומברך תחלה וסוף עי\"ז הוא מברר הניצוצות ומעלה אותם לקדושה כי אמלאה החרבה (יחזקאל ך\"ו ב'), וכשנעשה בטן רשעים תחסר, חיל בלע ויקיאנו ומבטנו יורישנו אל, נתמלא ירושלים דקדושה כו'. אך בחי' אכילת שבת אינו ע\"ד בחי' בירור, כי בשבת בורר אסור, רק הוא ע\"ד צדיק אוכל לשובע נפשו, נפשו הוא בחי' נפש דוד שהוא בחי' מל', וצדיק אוכל לשובע נפשו הוא בחי' המשכה מבחי' צדיק חי עלמין שהוא בחי' יסוד בבחי' נפשו, וזהו לשובע נפשו שהוא ע\"ד מ\"ש ואכלתם לחמכם לשובע, שובע שמחות כו', שהוא המשכת פנימי' ומשביע לכל חי רצון, המשכת הרצון העליון, ואין באכילה זו בחי' פסולת כלל. וכך יש הפרש בין תפלת החול שהיא בבחי' בירור הרע, אבל בשבת התפלה הוא שנמשך ענג וקראת לשבת ענג, ולכן אין אומרים סלח לנו בשבת שאין בו בירור כו'.\n<b>וזהו</b> ענין ב' שבתות כהלכתן ב' בחי' הילוך שיש בשבת. אך הנה אעפי\"כ א\"א להגיע לבחי' ב' שבתות כהלכתן הנ\"ל כ\"א ע\"י בחי' הילוך שבחול, הילך בתורתי כו', כי מי שטרח בע\"ש יאכל בשבת, ולכן ארז\"ל בפ\"ז דשבת דס\"ט ע\"ב היה",[["114","17","<b>אלמלא שמרו ישראל שתי שבתות . . ב' בחי' שבת</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380048\" data-slug=\"likkutei-torah\" data-id=\"4001380048\">לקו\"ת בשלח ב, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">בהר מא, א</a> ואילך. ועוד."],["115","18","<b>וההפרש שבין ההילוך . . ימי השבוע . . .שבשבת</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370291\" data-slug=\"torah-or\" data-id=\"3901370291\">תו\"א בשלח שם סה, סע\"ב</a>-ג."],["116","19","<b>שתפלה . . דשבת . . באופן אחר . . תפלה . . דחול</b>: ראה [נוסף לתו\"א בשלח שם] סידור עם דא\"ח ריא, ג. ועוד."],["117","20","<b>ההפרש שבין אכילה דחול . . אכילה דשבת</b>: בכל הבא לקמן ראה [נוסף לתו\"א בשלח שם] תו\"א חיי\"ש טו, ג ואילך. סידור עם דא\"ח רב, ג ואילך."]]],[2002180092,"מהלך בדרך או במדבר ואינו יודע אימתי שבת מונה ששה ימים ומשמר יום אחד, שלכאו' מפני מה אינו משמר שבת תחילה, אלא מפני שא\"א להגיע לבחי' הילוך דשני שבתות כהלכתן כ\"א ע\"י שימנה ששה ימי החול תחלה שהוא בחי' העלאה בתפלה והמשכה דתורה שבחול, וע\"י שטרח בע\"ש היינו בבחי' הבירור דחול עי\"ז יאכל בשבת הוא בחי' תפלה ותורה דשבת שנמשלו ג\"כ לאכילה רק שבשבת האכילה היא לשובע נפשו שאין בו פסולת כנ\"ל.\nד) <b>אך</b> הנה ב' בחי' הילוך אלו<sup data-n=\"118\">21</sup> הם רק בבחי' אתעדל\"ת אתעדל\"ע, ואמנם כדי להיות ב' בחי' אלו בין בחול ובין בשבת הוא ע\"י המן, כי במן נא' ותעל שכבת הטל, שהיא מבחי' טל שאין לו הפסק וכמשארז\"ל כנס\"י שאלו שלא כהוגן ויבא כגשם לנו והקב\"ה השיבם כהוגן אהי' כטל<sup data-n=\"119\">22</sup> לישראל, כי ענין ויבא כגשם זהו באתעדל\"ת אתעדל\"ע וכמ\"ש ואד יעלה מן הארץ והשקה כו', שכשיש העלאה מלמטלמ\"ע אזי נמשך הגשם להשקות כו', אבל כשלא יש בחי' העלאה אינו נמשך מצד עצמו, אבל הקב\"ה השיבם כהוגן אהי' כטל כו' שאינו פוסק לעלמין והוא מבחי' אתעדל\"ע מצד עצמו שלא ע\"י אתעדל\"ת. ולכן כשאמר אלי' חי ה' אם יהי' טל ומטר פעל על המטר שלא ירד כ\"א ע\"פ דברו, אבל לא על הטל כי טל לא מיעצר שהוא בחי' אתעדל\"ע גם כשלא יש בחי' אתעדל\"ת כו', והיינו כי טל הוא בחי' אור וכמ\"ש כי טל אורות טליך, והנה אור הוא למעלה מבחי' מים<sup data-n=\"120\">23</sup>, כי מים הוא יורד מגבוה לנמוך שהוא בחי' תורה שנק' מים, משא\"כ טל שהוא בחי' אור הוא למעלה מבחי' מים, שהוא בחי' סתים שבתורה כי אורייתא סתים וגליא כו'.\n<b>וזהו</b> מ\"ש במן והוא כזרע גד לבן (בפ' בשלח ט\"ז ל\"א), וארז\"ל (יומא דע\"ה ע\"א) גד הוא בחי' אגדה<sup data-n=\"121\">24</sup>, והנה באגדה מלובש בחי' פנימי' התורה בחי' טעמי תורה, וכמ\"ש רש\"י ע\"פ ישקני מנשיקות פיהו, והיינו שע\"י המן הי' מתחבר סתים שבישראל בבחי' סתים שבתורה, כי ע\"י גליא שבתורה מחברים בחי' גלי' שבנש\"י בבחי' גלי' שבתורה, אך ע\"י המן הי' מתחבר בחי' סתים שבנש\"י בבחי' סתים שבתורה שהוא בחי' טל אורות. וזהו משארז\"ל (כתובות די\"א ע\"ב) כל המשתמש באור תורה אור תורה מחייהו, ובילקוט ישעי' סוף רמז רצ\"ח גרס כל המשתמש בטל תורה טל תורה מחייהו.",[["118","21","<b>אך הנה ב' בחי' הילוך אלו</b>: להתחלת הפיסקא ראה תו\"א בשלח שם סה, ג."],["119","22","<b>וכמשארז\"ל כנס\"י שאלו שלא כהוגן . . ויבא כגשם . . אהי' כטל</b>: בכ\"ז ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381015\" data-slug=\"likkutei-torah\" data-id=\"4001381015\">לקו\"ת האזינו עג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381020\" data-slug=\"likkutei-torah\" data-id=\"4001381020\">עד, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381026\" data-slug=\"likkutei-torah\" data-id=\"4001381026\">עה, ד</a>. עטרת ראש מד, א ואילך. סה\"מ תרל\"ב ח\"ב ע' תקע ואילך. תקעד ואילך. ובכ\"מ."],["120","23","<b>אור הוא למעלה מבחי' מים</b>: ראה בארוכה סידור עם דא\"ח ע, א ואילך. סה\"מ תרל\"ה ח\"ב ע' תנד ואילך. תרל\"ח ע' קמג ואילך. וש\"נ."],["121","24","<b>וזהו מ\"ש במן והוא כזרע גד לבן . . בחי' אגדה</b>: בהבא לקמן עד סוף הפרק ראה אוה\"ת בשלח ס\"ע תרו-ז. וע' תריז. שם (כרך ח) ע' ב'תקסו. סה\"מ תרכ\"ו ע' רא. תרכ\"ז ע' שפה. סה\"מ תר\"מ ח\"א ד\"ה מצה זו פס\"א."]]],[2002180093,"<b>ועוי\"ל</b> כזרע גד הוא בחי' גמול דלים<sup data-n=\"122\">25</sup>, דל הוא בחי' יצ\"ט, וכמ\"ש אשרי משכיל אל דל שקאי על היצ\"ט, כי היצ\"ט נק' דל ע\"ש שנא' בו ילד חכם ומסכן, אבל היצה\"ר נק' מלך זקן וכסיל, ופי' גמול דלים שהוא בחי' גומל חסדים טובים לבחי' דל, דהיינו שהמן הי' נותן כח ביצ\"ט להתגבר על היצה\"ר שהוא בחי' אתעדל\"ע המעורר בחי' אתעדל\"ת כו', וזהו כזרע גד לבן. ופי' לבן הוא ע\"ד מ\"ש וישכם לבן בבוקר, ואח\"כ נא' ויעקב הלך לדרכו, והיינו שכדי שיהי' בחי' ויעקב הלך לדרכו שהוא בחי' ב' מיני הילוך הנ\"ל, זהו ע\"י וישכם לבן בבקר שהוא בחי' לבן דקדושה<sup data-n=\"123\">26</sup> בחי' לובן העליון שהוא בחי' לבושי' כתלג חיור ושער רישי' כעמר נקי, ומשם נמשך המשכה בבחי' בקר דאברהם בחי' חסד כמ\"ש וישכם אברהם בבקר להמשיך רחמים להיות מעורר אתעדל\"ת ולהיות אתעדל\"ע תלוי באתעדל\"ת, וזהו מ\"ש במן עומר לגולגולת שהוא בחי' המשכה מבחי' ושער רישי' כעמר נקי כו'. וזהו ג\"כ שבציצית הוא משיכיר בין תכלת ללבן, כי ציצית הוא ג\"כ המשכה מבחי' ושער רישי' כו'. וזהו שנק' מן כי מן הוא ע\"ש ה' מנת חלקי וכוסי כו', וכמשארז\"ל ע\"פ ויצא מבת ציון כל הדרה מן כתי', שיש לנו מנה אחת ה' מנת חלקי, והיינו ששרש של המן נמשך מבחי' ה' מנת חלקי כו' תומיך גורלי, שבחי' גורל הוא שלמעלה מהשכל וטו\"ד<sup data-n=\"124\">27</sup>, וזהו שהמן הי' כדי שיהי' יוכל להיות אח\"כ קבלת התורה כו'.\n<b>וזהו</b> שנק' לחם אבירים, והיינו אבירים הוא ע\"ד משארז\"ל ע\"פ שמעו אלי אבירי לב<sup data-n=\"125\">28</sup> הרחוקים מצדקה שכל העולם כולו ניזון בצדקה של הקב\"ה והם ניזונים בזרוע לפי שהם צדיקים גמורים, ולכך נק' אבירי לב דהיינו שיש להם בחי' אהבה דבכל מאדך, וכך המן נק' לחם אבירים שהמן נותן כח שיהי' להם בחי' אהבה דבכל מאדך כו', וכמ\"ש מידי אביר יעקב, יעקב הוא בחי' מ\"ש ויעקב הלך לדרכו שהוא ענין תומ\"צ, ואביר יעקב הוא הכח שיוכל לקיים תומ\"צ, ולכך נק' המן לחם אבירים לפי שהוא הכח על תומ\"צ כו'.",[["122","25","<b>ועוי\"ל כזרע גד הוא בחי' גמול דלים</b>: ראה סה\"מ תרכ\"ו שם ע' רא. תרכ\"ז שם ע' שפד. תר\"מ שם."],["123","26","<b>וישכם לבן בבוקר . . ויעקב הלך לדרכו . . לבן דקדושה</b>: ראה בכ\"ז תו\"א ויצא כד, ב."],["124","27","<b>שבחי' גורל . . שלמעלה מהשכל וטו\"ד</b>: ראה בארוכה סה\"מ תרכ\"ו ע' קעג ואילך. תרל\"ב ח\"ב ע' שצב ואילך. ת ואילך. [ובהנסמן שם]."],["125","28","<b>וזהו שנק' לחם אבירים . . ע\"ד . . אבירי לב</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470101\" data-slug=\"or-hatorah-hb\" data-id=\"8316470101\">אוה\"ת בשלח ע' תקסז</a>-ח. ס\"ע תרטו-ז. שם (כרך ח) ע' ב'תתקסה."]]],[2002180094,"<h3>[הנני ממטיר] אך כו' למענן אנסנו כו' (ב)</h3>\n<b></b><b>בס\"ד. (ש\"פ נשא, ט\"ל).</b>\n<b></b>זמן סדר זמנים ולמעלה מהנ\"ל בשנים דרכים כו' דבר יום ביומו לבד ביום וא\"ו כו' ענין הדגלים - (ה-ז)\nנשא\nה) <b>אך</b> להבין מ\"ש למען אנסנו<sup data-n=\"126\">1</sup> הילך בתורתי, מהו הנסיון<sup data-n=\"127\">2</sup>. הענין הוא דהנה במן כתיב דבר יום ביומו למען אנסנו כו', והנסיון הוא איש אל יותר ממנו עד בקר כו', כי ארז\"ל (במכילתא פ\"ב ע\"פ דבר יום ביומו (בשינוי לשון קצת) כל מי שיש לו פת בסלו ודואג על למחר ה\"ז מקטני אמנה, שהוא בבחי' קטנות. והיינו לפי שהמן הי' נמשך מבחי' טל העליון בחי' אני הוי' לא שניתי שהוא למעלה מן הזמן כו', דהיינו אפי' מבחי' סדר זמנים. וכידוע שיש ג' בחי', זמן שהוא בחי' מל' מלך מלך וימלוך, וסדר זמנים היינו שהוא בחי' מקור לזמן, וכמ\"ש במדרש ע\"פ ויהי ערב ויהי בקר מלמד שהי' סדר זמנים קודם לכן שהוא בחי' מדות, אך למעלה מבחי' מדות הוא למעלה מן הזמן ממש<sup data-n=\"128\">3</sup>, ושרש המן נמשך מבחי' שלמעלה מן הזמן ממש כו'. וזהו כמ\"ש במכילתא מי שברא יומו ברא פרנסתו עמו, דהיינו שמי ברא יומו שהוא בחי' מדות ברא פרנסתו עמו שמבחי' זו נמשך גם הפרנסה דהיינו המן, כי כל ההשפעות שהוא בחי' אין לך עשב מלמטה שאין לו מזל מלמעלה הוא רק מבחי' זמן ומבחי' סדר זמנים שהוא בבחי' ז\"א ומל' כו', משא\"כ המן כו'.\n<b>(ויש</b> לפרש זה בשני דרכים<sup data-n=\"129\">4</sup>, הא' הוא שזמן הוא במל' מלך מלך ימלוך, וסדר זמנים י\"ל שזהו בחי' מדות, אבל למעלה מבחי' מדות ה\"ה למעלה גם מסדר זמנים, וזהו מי שברא יומו ברא פרנסתו, שבחי' מי הוא בורא בחי' יום, ע\"ד מי ברא אלה, אל\"ה הם בחי' ו\"ק דז\"א ובחי' מי הוא בינה<sup data-n=\"130\">5</sup> ברא בחי' אלה הם בחי' ששה מדות דז\"א, שהם סדר זמנים, והם בחי' יומו של הקב\"ה שהוא אלף שנה כמ\"ש כי אלף שנה בעיניך כיום אתמול שיומו של הקב\"ה הוא אלף שנה, וכמ\"ש באדה\"ר כי ביום אכלך כו' ומחסד ה' החליף יום של אדה\"ר על יום של הקב\"ה שהוא אלף שנה,",[["126","1","<b>אך להבין מ\"ש למען אנסנו</b>: מאמר זה הוא המשך להמאמר שלפנ\"ז ד\"ה מי זאת הנשקפה. לכללות המאמר ראה בהנסמן שם בתחילת המאמר.\nהנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה נדפסה לקמן בהוספות ושם התחלת המאמר ד\"ה ”הנני ממטיר לכם\"."],["127","2","<b>מ\"ש למען אנסנו . . מהו הנסיון</b>: להתחלת הפרק ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370292\" data-slug=\"torah-or\" data-id=\"3901370292\">תו\"א בשלח סה, ג</a>."],["128","3","<b>וכידוע שיש ג' בחי', זמן . . וסדר זמנים . . למעלה מן הזמן ממש</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' לד ואילך. תקס\"ט ע' רפב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830293\" data-slug=\"or-hatorah-hb\" data-id=\"8158830293\">אוה\"ת בשלח ע' תרלג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600543\" data-slug=\"or-hatorah-hb\" data-id=\"8316600543\">בלק ע' תתקעט</a>-פ. ענינים ע' צו. יהל אור לתהלים ס\"ע רמב. וע' תקמג. ביאוה\"ז להצ\"צ ח\"א ע' רנז ואילך. דרמ\"צ (מצות האמנת אלקות) נז, א ואילך. סה\"מ תרכ\"ז ס\"ע לז-ח. תרכ\"ח ר\"ע קסט. לקמן ד\"ה בהעלותך פ\"ד. המשך תרס\"ו ע' מא ואילך."],["129","4","<b>ויש לפרש זה בשני דרכים</b>: בהבא לקמן בהגה\"ה זו ראה בדרושים שנסמנו בהערה שלפנ\"ז."],["130","5","<b>מי ברא אלה . . ו\"ק דז\"א . . מי הוא בינה</b>: ראה בכ\"ז בארוכה סה\"מ תרכ\"ז ע' שסז ואילך. [ובהנסמן שם בתחילת המאמר]. תרל\"ה ח\"ב ע' שפז ואילך. [ובהנסמן שם בתחילת המאמר]."]]],[2002180095,"והיינו בחי' חסד אל כל היום, שכל מדה מששה מדות דז\"א שהם בחי' סדר זמנים כשמתגלה בבחי' מלכותו ית' נעשה מזה למטה אלף שנים<sup data-n=\"131\">6</sup>, ולכן אלף שנים הראשון היו כולם חסד כמארז\"ל דור אנוש היו נזונים בחסדו של הקב\"ה, לפי שאלף שנים הראשון היו מספירת מדת החסד שהאיר במל', שמבחי' סדר זמן של מדת החסד נעשה במל' אלף שנה שהי' נשפע חסד למטה, וכן מסדר זמן שבמדת הגבורה כשהאיר בבחי' מל' נעשה במל' בחי' זמן של אלף שנים שהם מבחי' הגבורה ולכן הי' בהם המבול (שהי' אלף ותרנ\"ו ליצירה) והפלגה (הי' אלף תתקצ\"ו ליצירה), ואלף שנים השלישי הם ממדת הת\"ת ולכן בהם הי' מ\"ת, שמ\"ת הי' שני אלפים ותמ\"ח ליצירה<sup data-n=\"132\">7</sup>. אמנם הנה כ\"ז הוא בבחי' המדות שהם בחי' סדר זמנים עכ\"פ, אבל בחי' מי הוא למעלה גם מסדר זמנים, וכמ\"ש במ\"א בענין ההבדל שבין מוחין למדות שענין המדות הם לזולתו דוקא, כי הן עצם המדה והן פעולת המדה היא לזולת דוקא כמשנ\"ת מזה בכ\"ד<sup data-n=\"133\">8</sup>, משא\"כ בחי' המוחין הן מצד עצמם והן מצד פעולתם כמשנ\"ת בד\"ה אשר ברא אלקים<sup data-n=\"134\">9</sup> לעשות הראי' מרפב\"י ורשב\"י בגמ' שבת פ' במה מדליקין דל\"ג סע\"ב, ולכן המוחין דחו\"ב הם למעלה גם מסדר זמנים, וזהו מי שהוא בינה ברא יומו, וברא פרנסתו ג\"כ כו'. ומ\"ש רז\"ל אלפים שנה קדמה תורה לעולם שהם אאלפך חכמה אאלפך בינה ונק' ג\"כ יום כמ\"ש ואהי' אצלו שעשועים יום יום, זהו רק שם המושאל לבד, שבאמת אינו שייך כלל במוחין דחו\"ב גם בחי' סדר זמנים כו'. ועוי\"ל שזמן הוא במל', וסדר זמנים הוא כלליות הע\"ס, או בחי' המל' שבכל הט\"ס שלמעלה מבחי' המל' שמהם נבנית המל' להיות בבחי' פרצוף שלם. ולמעלה מע\"ס אינו שייך גם בחי' סדר זמנים, וזהו בחי' מי שברא יומו, כי פי' מי הוא שאינו מושג מי הוא ע\"ד בחי' והחכמה מאין תמצא ומשם הוא שרש המן כו').\n<b>ולכן</b> בכל המאכלים מותר להכין מיום לחבירו לפי שיכול להיות שיהי' נפסק ההשפעה למחר כו', משא\"כ המן שהוא נמשך מבחי' שנמשכים המדות שהוא בחי' אני הוי' לא שניתי ע\"כ אסור להכין מיום לחבירו לפי שמשם אין שייך שינוי כלל כו', ולכן צ\"ל דבר יום ביומו.\n<b>(ועדיין</b> צ\"ל<sup data-n=\"135\">10</sup> מה שביום הששי לקטו לחם משנה שני העומר לאחד שיום הששי מכין לשבת, דלכאורה קשה אע\"ג שבשבת א\"א להיות ירידת והמשכת",[["131","6","<b>כמ\"ש כי אלף שנים בעיניך . . שכל מדה מששה מדות . . נעשה מזה למטה אלף שנים</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380952\" data-slug=\"likkutei-torah\" data-id=\"4001380952\">לקו\"ת</a> דרושים לר\"ה נח, ב. שה\"ש יז, ד. מאמרי אדה\"ז תקס\"ז ע' שמז. עטרת ראש ה, א-ב. ביאוה\"ז לאדהאמ\"צ קי, ד. מאמרי אדהאמ\"צ דברים ח\"א ע' רז. וש\"נ. אוה\"ת דברים (כרך ה) ע' ב'צו. סה\"מ תרכ\"ט ע' שלג ואילך. וש\"נ."],["132","7","<b>המבול (שהי' אלף ותרנ\"ו ליצירה . . שמ\"ת הי' שני אלפים ותמ\"ח ליצירה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201027\" data-slug=\"likkutei-sichot\" data-id=\"1300201027\">לקו\"ש ח\"כ ע' 27</a> ואילך. סה\"ש תשמ\"ח ח\"א ע' 281 ואילך."],["133","8","<b>וכמ\"ש במ\"א בענין ההבדל שבין מוחין למדות . . כמשנ\"ת מזה בכ\"ד</b>: סה\"מ תרכ\"ז ע' פו. וע' רעז. תרכ\"ט ע' ט. וע' תו. וש\"נ. תר\"ל ס\"ע פ-פא. וע' רסז. תרל\"ג ח\"א ע' צ. וע' שטו. ח\"ב ס\"ע תקמ ואילך. תרל\"ד ע' נד ואילך. [ובהנסמן בהערה שלאח\"ז]."],["134","9","<b>כמשנ\"ת בד\"ה אשר ברא אלקים</b>: סה\"מ תרכ\"ח ע' ד ואילך."],["135","10","<b>(ועדיין צ\"ל מה שביום הששי . . יום ביומו דוקא כנ\"ל)</b>: אודות הגה\"ה זו כותב כ\"ק אדמו\"ר מהר\"ש בהגהותיו להמאמר ”בס' להבין מ\"ש בע\"ח דק\"ד ע\"ב\", והכוונה לביאור לד\"ה ויאמר גו' אכלוהו היום הנדפס באוה\"ת בשלח ע' תרלא, הגה\"ה זו נעתקה אח\"כ בכת\"י מעתיק בס' תרל\"ט ונוספו ע\"ז הגהות בגוכי\"ק."]]],[2002180096,"המן מטעם שית' לקמן עכ\"ז אינו מובן איך יכול לירד ביום הששי על שני ימים כיון שבחי' המן נמשך דבר יום ביומו, וא\"א שיומשך מיום אחד למחרתו כי כל יום הוא מדה עליונה דאצי' ונמשך בכל מדה בפ\"ע מבחי' מו\"ס שמשם שרש המן ולא נמשך על יום מחר שהוא מדה אחרת כו', וא\"כ איך ביום הששי נמשך וירד על ב' ימים שהם ב' מדות יסוד ומל' כו' כי המל' נק' שביעאה מלמעלמ\"ט כנודע<sup data-n=\"136\">11</sup>. אך הענין הוא לפי שנעוץ תחלתן בסופן וסופן בתחלתן, והנה יום הששי הוא סוף דששת ימי המעשה, כי יום השביעי הוא בחי' מובדלת מששת ימי המעשה כי הם בבחי' ירידה והמשכה מאצי' לבי\"ע מלמעלה למטה, משא\"כ השבת שהוא בחי' עלי' מלמטה למעלה מבי\"ע לאצי' עד שהעלי' הוא למעלה מהזמן, ע\"כ יום הששי נק' סופן דששת ימי המעשה, ולכן לפי שנעוץ תחלתן בסופן ע\"כ יש מעלה יתירה ביום הששי מכל הימים עד שהוא מכין על שבת, כי הנה בגמר יום הששי נכנס השבת היינו שבסוף הירידה נעשה בחי' או\"ח ועליי', וזהו ענין בין השמשות דע\"ש. ויובן זה<sup data-n=\"137\">12</sup> ממשל אור השמש דהנה למעלה מעלה האויר חם מאד, וגם למטה על הארץ וסמוך לי' האויר חם, ובאמצע האויר קר מאד כידוע בס' התכונה, ולכאורה תמוה דהרי אויר התחתון רחוק יותר מהשמש מאויר האמצעי ומדוע האויר האמצעי הוא קר ואויר התחתון שהוא רחוק יותר הוא חם. אך הטעם מפני שהכאת השמש על הארץ שהוא בסוף המדרגה של התפשטות אור השמש, אז דוקא נעשה בחי' או\"ח ע\"ד נעוץ תחב\"ס שנמשך חום השמש כאשר בתחלתה באויר הראשון הסמוך לשמש. וכך ביום הששי שהוא בחי' סופן נעשה בחי' או\"ח ועליי', וזהו יום הששי ויכולו השמים לשון כלות הנפש ועליי' כו', נמצא ב' בחי' אלו מתחברים יחד ממש היינו יום הששי ועליי' דשבת כו', ולכן מתורץ מה שביום הששי נמשך מן על שני הימים שזהו ג\"כ דבר יום ביומו, משא\"כ בשאר הימים א\"א להיות כן כי צ\"ל דבר יום ביומו דוקא כנ\"ל).\n<b>וזהו</b> שהוא נסיון על התורה<sup data-n=\"138\">13</sup> כי התורה צ\"ל ג\"כ דבר יום ביומו, בכל יום יהיו בעיניך כחדשים, כי נער הייתי גם זקנתי שרו של עולם אמרו, משא\"כ קמי' קודב\"ה מי איכא זקנה מאחר שהוא אני הוי' לא שניתי, וזהו שאנו מברכין נותן התורה שבכל יום נמשך המשכת התורה לפי שבכל יום צ\"ל בעיניך כחדשים כו', (ולפי ב' הפירושים הנ\"ל הנה לפי פי' הא' הנה אורייתא מחכמה נפקת שזהו מבחי' מוחין שלמעלה גם מסדר זמנים, ולכן צ\"ל כחדשים בכ\"י כמו שהמן הי' דבר יום ביומו כו'. ולפי' הב' צ\"ל פי' אורייתא מחכמה נפקת שיציאתה לידי גילוי הוא מבחי' חכמה, אבל שרשה ומקורה הוא בבחי' הכתר כי תרי\"ג מצות דאורייתא וז' דרבנן",[["136","11","<b>המל' נק' שביעאה מלמעלמ\"ט כנודע</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316520292\" data-slug=\"or-hatorah-hb\" data-id=\"8316520292\">אוה\"ת בשלח שם ע' תרלו</a> ואילך. המשך תער\"ב ח\"ב ע' א'פו ואילך."],["137","12","<b>ויובן זה ממשל אור השמש . . למעלה מעלה האויר חם . . למטה . . חם, ובאמצע . . קר</b>: ראה בארוכה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשמא. אוה\"ת בשלח שם ע' תרלא. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380734\" data-slug=\"likkutei-torah\" data-id=\"4001380734\">לקו\"ת ואתחנן ה, ג</a>. שה\"ש יז, רע\"ג. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940286\" data-slug=\"or-hatorah-hb\" data-id=\"8159940286\">אוה\"ת בחוקותי (כרך ב) ע' תרצב</a>. נ\"ך (כרך א) ע' שמט. סה\"מ תר\"ל ע' רלט. ועוד."],["138","13","<b>וזהו שהוא נסיון על התורה</b>: בהבא לקמן בפיסקא זו ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370292\" data-slug=\"torah-or\" data-id=\"3901370292\">תו\"א בשלח שם סה, ג</a>."]]],[2002180097,"הם תר\"ך עמודי אור בחי' כתר כו'), וזהו למען אנסנו הילך בתורתי דהיינו שהנסיון הוא איש אל יותר ממנו עד בקר כו' אלא דבר יום ביומו כו'.\nוא\"ו) <b>ובזה</b> יובן מה שהמן לא הי' יורד בשבת<sup data-n=\"139\">14</sup>, והיינו לפי שכדי שיומשך המן שהוא בחי' גבוה מאד א\"א להיות נמשך למטה כ\"א ע\"י צמצומים וכמ\"ש שראשי נמלא טל<sup data-n=\"140\">15</sup> קווצותיו רסיסי לילה, שכדי שיומשך הטל למטה הוא ע\"י קווצותיו רסיסי לילה שהוא בחי' שערות בחי' צמצומים כו', שעי\"ז נמשך השפעה עליונה זו למטה בגשמי', והרי בשבת הוא בחי' עלי' ושביתה מבחי' צמצומים הנ\"ל, ולכן לא ירד בשבת (ולפי ב' הפירושים הנ\"ל צ\"ל בפי' וענין שביתה דשבת, שלפי' הא' הוא השביתה מכל אשר עשה, ולפי' הב' הוא בחי' השביתה מכל אשר ברא כמשנ\"ת בלק\"ת בד\"ה את שבתותי תשמורו<sup data-n=\"141\">16</sup> ע\"ש). וזהו לא תמצאוהו בשדה, שבשדה לא נמצא לפי שמוכרח לירד ע\"י צמצומים<sup data-n=\"142\">17</sup>, משא\"כ למעלה הי' יורד המן, ואדרבה שמשבת היו מקבלים ששת ימי החול לפי שעיקר ההשפעה של המן הי' נמשך בשבת, רק שלא הי' יכול לירד למטה בשבת לפי שא\"א לירד למטה כ\"א ע\"י צמצומים כו', ובשבת הוא למעלה מבחי' צמצום כו'. אך הנה אעפ\"כ אמר היום לא תמצאוהו בשדה אבל לע\"ל יהי' נמצא<sup data-n=\"143\">18</sup> כו', כמ\"ש במכילתא הובא בילקוט בשלח רמז רס\"א ע\"פ היום לא תמצאוהו בשדה, והיינו לפי שעתה אינו יכול להיות נמשך למטה כ\"א ע\"י צמצום כו', כי היום לא תמצאוהו בשדה, לא הוא ע\"ד מ\"ש והחכמה מאין תמצא שאינו מושג בחי' האין, כי לא באל\"ף הוא מורה על בחי' שאינו מושג לנו, אבל לע\"ל יהי' נמשך בחי' האין בגילוי, וע\"כ גם המן יהי' נמצא בשבת לפי שיומשך למטה שלא ע\"י צמצומים כלל.\n<b>וזהו</b> ענין ג\"פ היום שנאמר בשבת<sup data-n=\"144\">19</sup>, והיינו לפי שהוא כנגד ג' סעודות דשבת, אכלוהו היום הוא כנגד שבת דמעלי שבתא שהוא כנגד שמור, שמור לנוק', ובזה מתורץ הקושי' הלא גם בשאר הימים אכלו מן, אלא שבשבת גם סעודת הלילה נק' יום<sup data-n=\"145\">20</sup>, לפי שבשבת לא נאמר ויהי ערב ויהי בקר, וכמארז\"ל במד\"ר פ' בראשית פי\"א ל\"ו שעות שימשה אותה האורה, וכמ\"ש הרמ\"ז ר\"פ בא, והיינו כי האכילה",[["139","14","<b>ובזה יובן מה שהמן לא הי' יורד בשבת</b>: בהבא לקמן בפיסקא זו ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370292\" data-slug=\"torah-or\" data-id=\"3901370292\">תו\"א בשלח שם סה, סע\"ג</a>-ד."],["140","15","<b>וכמ\"ש שראשי נמלא טל קווצותיו רסיסי לילה . . בחי' צמצוצים</b>: [כן הובא בכ\"מ. ובפסוק: קווצותי] ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381272\" data-slug=\"likkutei-torah\" data-id=\"4001381272\">לקו\"ת שה\"ש לה, סע\"ד</a>."],["141","16","<b>כמשנ\"ת בלק\"ת בד\"ה את שבתותי תשמורו</b>: פ' בהר מב, ד ואילך."],["142","17","<b>שבשדה לא נמצא לפי שמוכרח לירד ע\"י צמצומים</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370292\" data-slug=\"torah-or\" data-id=\"3901370292\">תו\"א בשלח שם סה, סע\"ג</a>: היום לא תמצאוהו בשדה, שדה היינו בחי' עולם ו' קצוות."],["143","18","<b>אעפ\"כ אמר היום לא תמצאוהו . . אבל לע\"ל יהי' נמצא</b>: בהבא לקמן ראה אוה\"ת בשלח שם ע' תרה. וס\"ע תריט-כ."],["144","19","<b>וזהו ענין ג\"פ היום שנאמר בשבת</b>: בהבא לקמן ראה גם אוה\"ת בשלח שם ס\"ע תרג-ד. ס\"ע תרכ ואילך. וע' תרלא."],["145","20","<b>ובזה מתורץ הקושי' . . גם סעודת הלילה נק' יום</b>: ראה בכ\"ז אוה\"ת בשלח שם ע' תרד. וע' תרכא."]]],[2002180098,"דשבת הוא למעלה מבחי' בירורים דטו\"ר שנק' לילה כמ\"ש ותקם בעוד לילה ותתן טרף, בירור רפ\"ח ניצוצין, כי בע\"ש עם חשיכה נפרד הרע מן הטוב, והטוב מתעלה, והאכילה הוא לשובע נפשו בחי' נפש דוד כנ\"ל, ולכן גם סעודה דמעלי שבתא נאמר בלשון יום, אכלוהו היום כו'. כי שבת היום להוי' הוא כנגד זכור, זכור לדכורא. היום לא תמצאוהו בשדה, הוא כנגד סעודה שלישית<sup data-n=\"146\">21</sup> דשבת שהוא בחי' זכור ושמור בדבור א' נאמרו, שזהו בחי' עדן עין לא ראתה, וקראת לשבת ענג, ענג הוא בחי' ר\"ת עדן נהר גן, גן הוא סעודה דמעלי שבתא, ושבת דיומא הוא בחי' נהר, וסעודה הג' הוא בחי' עדן כו', וזהו שנאמר היום לא תמצאוהו בשדה, לא הוא ע\"ד בחי' אין.\n<b>ועפ\"ז</b> יובן ענין מה שהמן הי' עומר לגולגולת, והיינו שע\"י המן הי' נעשה אצלם בחי' רצה\"ע שלמעלה מהשכל<sup data-n=\"147\">22</sup> וטו\"ד המושג, וכמ\"ש שאו את ראש כל עדת בנ\"י לגלגלתם כו', שהוא בחי' גלגלתא דחפיא על מוחא בחי' רצה\"ע שלמעלה מהשכל כו'.\n<b>אך</b> כ\"ז<sup data-n=\"148\">23</sup> הי' מלמעלמ\"ט שהי' בחי' אתעדל\"ע שלמעלה מאתעדל\"ת, וכ\"ז הוא מיצ\"מ עד ביאת הארץ שהי' בחי' אתעדל\"ע, והי' יורד המן מלמעלמ\"ט. אך כי תבאו אל הארץ שאז צריך שיהי' בחי' אתעדל\"ת איני מבקש מכם אלא עומר א' של שעורים, והיינו כי שעורה הוא בחי' שעור ה', ה' הוא בחי' ה' חומשי תורה דהיינו בחי' גליא שבתורה כו'. ובעבודה הוא בחי' ההתבוננות מבחי' ה' בהבראם בה' בראם ה' זעירא הנ\"ל, והיינו איך שנתהווה העולם מאין ליש וכמ\"ש שאו מרום עיניכם וראו מי ברא אלה, וכל חד וחד לפום שעורא דילי' צריך להתבונן בזה, ועי\"ז יגיע לבחי' יראה שהוא בחי' קבעומ\"ש שזה הוא בחי' השער ופתח הראשון כשצריך לידבק באלקות א\"א כ\"א ע\"י יראה וכמ\"ש בזאת יבא אהרן אל הקדש, וכן ארז\"ל כל אדם שיש בו תורה ואין בו יר\"ש דומה לגזבר שמסרו לו מפתחות הפנימית ומפתחות החיצוני' לא מסרו לו בהי עייל. וזהו ועתה ישראל מה ה' שואל מעמך כ\"א ליראה שהבקשה מלמטה הוא רק בחי' יראה, ואח\"כ ממילא יהי' התגלות בחי' עליונות יותר וכמ\"ש שם לאהבה את ה' אלקיך וללכת בדרכיו כו'. וזהו שפסח נק' חג האביב שהוא בחי' שעורה וכמ\"ש והשעורה אביב, ואח\"כ הוא חג השבועות שהוא בחי' קציר חטים<sup data-n=\"149\">24</sup>, וכמ\"ש וחג הקציר בכורי מעשיך קציר חטים כו', והיינו שמתחלה צ\"ל רק בחי'",[["146","21","<b>היום לא תמצאוהו . . כנגד סעודה שלישית</b>: ראה אוה\"ת בשלח שם ע' תרלא. נדפס גם בס' מאה שערים מד, א. ובהנסמן ע\"ז בהערות וציונים שם (בהוצאת קה\"ת). סה\"מ תרכ\"ז ע' קלג. וש\"נ. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211084\" data-slug=\"likkutei-sichot\" data-id=\"1300211084\">לקו\"ש חכ\"א ע' 84</a> ואילך. וש\"נ."],["147","22","<b>וכמ\"ש שאו את ראש . . לגלגלתם . . בחי' רצה\"ע שלמעלה מהשכל</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380312\" data-slug=\"likkutei-torah\" data-id=\"4001380312\">לקו\"ת במדבר א, א</a> ואילך."],["148","23","<b>אך כ\"ז הי' מלמטלמ\"ע</b>: בהבא לקמן בפיסקא זו ראה אוה\"ת בשלח ס\"ע תקפט-צ."],["149","24","<b>וזהו שפסח נק' חג האביב . . שעורה . . חג השבועות . . חטים</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380348\" data-slug=\"likkutei-torah\" data-id=\"4001380348\">לקו\"ת במדבר י, א</a> ואילך. אוה\"ת משפטים ע' א'קעח ואילך. פנחס ע' א'ריב ואילך. סה\"מ תר\"ל ע' קלב ואילך. וע' רה ואילך. סה\"מ מלוקט ח\"ה ע' קסט ואילך."]]],[2002180099,"שעורה ואח\"כ ממילא נמשך בחי' קציר חטים. וזהו שנאמר תספרו חמשים יום, והלא אין אנו סופרים רק מ\"ט יום, והיינו כשתספרו מ\"ט יום אז ממילא נתגלה בחי' שער הנו\"ן<sup data-n=\"150\">25</sup>, לפי שספירה הוא בחי' בירור של נה\"ב מאכל בהמה, וכשמבררים את נה\"ב אז יכול להיות התגלות שער הנו\"ן, אך זה נמשך ממילא כו'. וזהו שאיני מבקש מכם אלא עומר א'<sup data-n=\"151\">26</sup> של שעורים כו', אבל כשנתתי לכם נתתי לכאו\"א עומר לגולגולת, דהיינו שע\"י העומר עי\"ז הי' נמשך בכל א' בחי' לגלגלתם שהוא בחי' גלגלתא דחפי' על מוחא שהוא בחי' רצה\"ע שלמעלה מהשכל, כי הוא נמשך מבחי' התבוננות של מהו\"ע כו' ולא מבחי' בריאה יש מאין, והיינו לפי שהמן הי' נמשך מבחי' טל טלא דבדולחא דנטיף מע\"י שהוא בחי' טל תורה טל שעתיד להחיות בו מתים, וע\"כ ע\"י הי' מאיר בחי' לגלגלתם בחי' רצון פשוט. והנה ע\"י שהי' אצלם בחי' לגלגלתם וכמ\"ש שאו את ראש כו' לגלגלתם, צוה ה' לעשות להם דגלים.\nז) <b>ולהבין</b> ענין הדגלים, הענין הוא, דהנה כתיב כי כארבע רוחות השמים פרשתי אתכם וארז\"ל כשם שא\"א לעולם בלי רוחות<sup data-n=\"152\">27</sup> כך א\"א לעולם בלא ישראל, והיינו שרוחות הוא בחי' ד' רוחות העולם מזרח מערב צפון דרום, מזרח ע\"ש שממנו האור יוצא לעולם. והנה שרש של ד' רוחות העולם הוא בחי' ד' חיות המרכבה מיכאל גבריאל רפאל אוריאל, והנה מיכאל הוא ע\"ש מי כמוכה באלים כו' או מי אל כמוך נושא עון כו', גבריאל הוא ע\"ש פלא יועץ אל גבור כו' (ישעי' ט' פסוק ה'), אוריאל הוא ע\"ש אל ה' ויאר לנו, רפאל הוא ע\"ש אל נא רפא נא לה. ולכאורה אינו מובן הלא ד' חיות המרכבה הם בבריאה ואיך שייך לומר שמיכאל הוא בחי' מי אל כמוך כו'. אך הענין הוא דהנה בחיות הקדש כתיב והחיות נושאות את הכסא דהיינו שנושאים את בחי' אדם שעל הכסא לבחי' כי לא אדם<sup data-n=\"153\">28</sup> הוא, כי אדם הוא בחי' ציור קוין חסד דרועא ימינא כו', שהוא בחי' המשכה בבחי' מדות, אך החיות נושאות את הכסא למעלה מבחי' אדם דהיינו כי לא אדם כו'. וזה שנק' מיכאל גבריאל שיש בחי' שם אל בכל א'<sup data-n=\"154\">29</sup> ע\"ש כי אל אנכי ולא איש, ולכאורה אינו מובן שהרי ארז\"ל בכ\"מ ואין איש אלא הקב\"ה שנאמר ה' איש מלחמה, וכאן נאמר כי אל אנכי ולא איש, והיינו לפי שבחי' איש הוא כשנמשך בבחי' מדות אז נק' איש, אך למעלה מבחי' מדות אינו נק' איש כי אל אנכי ולא איש. והנה המלאכים ע\"י עבודתם",[["150","25","<b>תספרו חמשים יום . . סופרים רק מ\"ט . . ממילא נתגלה . . שער הנו\"ן</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380351\" data-slug=\"likkutei-torah\" data-id=\"4001380351\">לקו\"ת במדבר שם י, ד</a>. יב, א ואילך. ובכ\"מ."],["151","26","<b>וזהו שאיני מבקש מכם אלא עומר א'</b>: בהבא לקמן ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316520250\" data-slug=\"or-hatorah-hb\" data-id=\"8316520250\">אוה\"ת בשלח ע' תקצד</a>-ה. וע' תרכב-ג."],["152","27","<b>ולהבין ענין הדגלים . . כשם שא\"א לעולם בלי רוחות</b>: בהבא לקמן ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830034\" data-slug=\"or-hatorah-hb\" data-id=\"8158830034\">אוה\"ת במדבר ע' לד</a>-<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830043\" data-slug=\"or-hatorah-hb\" data-id=\"8158830043\">ה. וע' לח</a> ואילך. שם בהוספות (הוצאת תשנ\"ה) ע' 23 ואילך. אוה\"ת נ\"ך (כרך א) ע' תקח. — וראה עוד בענין הדגלים בד\"ה מי זאת הנשקפה באוה\"ת במדבר ע' מג ואילך. וע' מח ואילך. ובביאוה\"ז לאדהאמ\"צ פה, א ואילך. ולהצ\"צ ח\"א ע' תמט ואילך [ובדרושים שלאחריו]."],["153","28","<b>והחיות נושאות את הכסא . . לבחי' כי לא אדם</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370317\" data-slug=\"torah-or\" data-id=\"3901370317\">תו\"א יתרו עא, ב</a>."],["154","29","<b>שנק' מיכאל גבריאל שיש בחי' שם אל בכל א'</b>: ראה בארוכה סה\"מ תרכ\"ט ע' ריב. וש\"נ."]]],[2002180100,"שנושאי' את הכסא למעלה מבחי' אדם שהוא בחי' מדות ע\"כ נק' בחי' אל כו' ע\"ש כי אל אנכי ולא איש, וזהו שנק' מיכאל ע\"ש מי כמוכה באלים כו', ונמשך ע\"י עבודתם מבחי' מי כמוכה באלים הוי' להיות מי אל כמוך נושא עון, לפי שהם נושאי' את הכסא. וכן גבריאל הוא ע\"ש פלא יועץ אל גבור כו', דהנה ארז\"ל איזהו גבור הכובש את יצרו<sup data-n=\"155\">30</sup> שנאמר טוב ארך אפים מגבור, ולכאורה אינו מובן איך למדו זה שאיזהו גבור הכובש את יצרו מפסוק טוב ארך אפים מגבור. אך הענין הוא דהנה כמו שלמטה יש בחי' גבור הכובש את יצרו, כך למעלה נק' הקב\"ה בשם כובש את יצרו, והיינו כשיש ח\"ו התגברות הדינין וקטרוגים על ישראל ח\"ו וכובש את הקטרוגים נק' בשם גבור הכובש את יצרו כו', וזהו טוב ארך אפים מגבור שארך אפים נמשך מגבור שהוא בחי' גבור הכובש את יצרו כו'. וזהו שגבורה הוא ג\"פ ע\"ב כו' כי חסד הוא בגימט' ע\"ב, אך גבורה שהוא רי\"ו הוא ג\"פ ע\"ב לפי שהוא בחי' התגברות החסדים להכניע את היצר וקטרוגים כו', והכלי לזה הוא בחי' גבריאל לפי שהם ממשיכים מבחי' כי אל אנכי ולא איש ע\"כ יכול להיות נמשך משם בחי' התגברות החסדים על הגבורות כו'. וזהו ענין ד' דגלים למעלה בחי' ד' חיות המרכבה כו' שהוא שרש של ד' רוחות העולם.\n<b>והנה</b> כמו שלמעלה יש בחי' ד' דגלים כמו\"כ ציוה הקב\"ה לעשות דגלים למטה<sup data-n=\"156\">31</sup>, כי הדגלים שלמטה הם כנגד הדגלים שלמעלה, ויש בזה פלוגתא בין המד\"ר לזהר, שהמד\"ר סובר שיהודה הוא כנגד גבריאל כי גבריאל הוא בחי' גבור, וביהודה נאמר יהודה גבר באחיו, והזהר סובר שיהודה הוא כנגד אוריאל<sup data-n=\"157\">32</sup> לפי שדגל יהודה הי' במזרח, ואוריאל הוא ג\"כ במזרח כו'. והיינו כמו שהדגלים שלמעלה הם ממשיכים מבחי' כי לא אדם הוא, ועי\"ז נמשך בחי' מי אל כמוך נושא עון, איזהו גבור הכובש את יצרו כו', כמו\"כ ע\"י הדגלים שלמטה נמשך ג\"כ מעצמות אוא\"ס שלמעלה מבחי' מדות, ואדרבה שע\"י הדגלים שלמטה נמשך ממקום עליון יותר, לפי שיתרון האור הוא מתוך החשך דוקא, שלכך לא ניתנה התורה למלאכים. וע\"כ הדגלים שלמטה ממשיכים ממקום עליון יותר וכמ\"ש ה' בחכמה יסד ארץ כונן שמים בתבונה, שבשמים אינו מאיר רק בחי' תבונה, ובארץ מאיר מבחי' חכמה, ע\"כ הדגלים שלמטה ממשיכים ממקום עליון יותר להיות נושא עון כו'. אך כ\"ז כשיש מתחלה בחי' שאו את ראש כל עדת בנ\"י לגלגלתם שהוא בחי' רצון פשוט שלמעלה מהשכל, עי\"ז ע\"י הדגלים יכולים להמשיך מבחי' מי אל כמוך כו' מי כמוכה באלים אל גבור כו' כמו הדגלים שלמעלה, וזהו כשם שא\"א לעולם בלי רוחות שהוא ענין ד' חיות המרכבה, כך א\"א לעולם בלי ישראל לפי שישראל הם ממשיכים ג\"כ כמו חיות הקדש כו'.",[["155","30","<b>ארז\"ל איזהו גבור הכובש את יצרו</b>: בהבא לקמן ראה לקמן ד\"ה ובראשי חדשיכם פ\"ג."],["156","31","<b>והנה כמו שלמעלה . . ד' דגלים כמו\"כ . . דגלים למטה</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830030\" data-slug=\"or-hatorah-hb\" data-id=\"8158830030\">אוה\"ת במדבר ע' ל</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830028\" data-slug=\"or-hatorah-hb\" data-id=\"8158830028\">קרח ע' תשיד</a>-טו. סה\"מ תרל\"ד ס\"ע רח-ט. תרע\"ח ע' שיב. וראה גם סה\"מ עטר\"ת ע' תלו-ז. ה'ש\"ת ע' 106. תשי\"ד ס\"ע 115-114. תשט\"ו ע' 287. וע' 292."],["157","32","<b>ויש בזה פלוגתא בין המד\"ר לזהר . . שיהודה הוא כנגד גבריאל . . כנגד אוריאל</b>: ראה ביאוה\"ז להצ\"צ שם ע' תס."]]],[2002180101,"<b>אך</b> כ\"ז הי' כשהי' בהמ\"ק קיים שהי' מאיר אצלם בחי' רצון פשוט כו', אך כשחרב בהמ\"ק שאין להם רצון פשוט, איך הם ממשיכים בחי' דגלים כמו חיות הקדש, זהו מ\"ש מי זאת הנשקפה כמו שחר, יפה כלבנה ברה כחמה איומה כנדגלות, והיינו שפסוק זה נאמר כנגד ד' גליות וכמ\"ש ברבות<sup data-n=\"158\">33</sup> פ' בא פ' ט\"ו הנשקפה כמו שחר זה בבל שהי' שם דניאל, יפה כלבנה זה מדי שהיתה שם אסתר, כי לבנה היא שלשים יום ובאסתר כתיב ואני לא נקראתי לבוא אל המלך זה שלשים יום, ברה כחמה זה יון, וזהו שמצות נר חנוכה היא משתשקע החמה, והיינו לפי שחמה היא בחי' יון, וכשגברו החשמונאים התקינו שיהי' נר חנוכה משתשקע החמה של היוונים כו', ואיומה כנדגלות הוא בחי' אדום. והיינו שזהו משארז\"ל כי כארבע רוחות השמים פרשתי אתכם, צדקה עשה הקב\"ה עם ישראל שפיזרן לבין האומות, והיינו שע\"י הד' גליות עי\"ז יכולים להגיע לבחי' איומה כנדגלות שהוא בחי' ד' דגלים, לפי שאף שאין להם בחי' שאו את ראש לגלגלתם בחי' ראש ומוחין, אעפ\"כ בחי' נצח יש לכאו\"א דהיינו בחי' אתכפי', והנה אתכפי' זו נעשה ע\"י הד' גליות כו', וכתיב וגם נצח ישראל לא ישקר, וע\"י בחי' נצח יכולים להגיע ג\"כ לבחי' דגלים שהי' מקדם ע\"י שאו את ראש כו', כמו\"כ ע\"י הגליות יכולים להגיע לבחי' דגלים שיהי' נמשך מבחי' מי אל כמוך נושא עון, אל גבור.\n<b>ועוי\"ל</b> כשם שא\"א לעולם בלא רוחות<sup data-n=\"159\">34</sup> כך א\"א לעולם בלא ישראל, היינו רוחות הוא רוחות הנושבות לפי שא\"א להיות קיום העולם בלתי רוחות הנושבות כו' לפי שע\"י הבל אדם ובהמה נתקלקל האויר והי' נעשה האויר מעופש, והרוחות הנושבות הם מזככים את האויר<sup data-n=\"160\">35</sup> שיהיה האויר מתוקן, ויש כמה בחי' רוחות יש רוח הנושב מלמטה למעלה ויש רוח הנושב מלמעלה למטה, וכמו\"כ א\"א לעולם בלי ישראל שהם מתקנים ומזככים את האויר, ויש בזה ג\"כ כמה בחי' רוח מלמטה למעלה ומלמעלמ\"ט וכמ\"ש והרוח תשוב אל האלקים אשר נתנה שהוא בחי' העלא' מלמטלמ\"ע, ורוח אייתי רוח ואמשיך רוח מלמעלה למטה, אם ישים אליו לבו רוחו ונשמתו אליו יאסוף כו', ונחה עליו רוח הוי' רוח חכמה ובינה רוח עצה וגבורה כו' שהוא בחי' המשכה מלמעלה למטה כו', וזהו כשם שא\"א לעולם בלי רוחות כך א\"א לעולם בלי ישראל, לפי שהם מתקנים את העולם וממשיכים בחי' רוח מלמטה למעלה ומלמעלמ\"ט כנ\"ל.",[["158","33","<b>מי זאת הנשקפה . . כנגד ד' גליות וכמ\"ש ברבות</b>: הובא ונת' בד\"ה מי זאת הנשקפה ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770209\" data-slug=\"or-hatorah-hb\" data-id=\"8316770209\">אוה\"ת שה\"ש (כרך ב) ע' תקעז</a>."],["159","34","<b>ועוי\"ל כשם שא\"א לעולם בלא רוחות</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830023\" data-slug=\"or-hatorah-hb\" data-id=\"8158830023\">אוה\"ת בשלח ע' תרי</a>-יא [ושם: ועוי\"ל פי' שלישי המורכב מב' הפי'. עיי\"ש]. במדבר בהוספות (הוצאת תשנ\"ה) ע' 23. וראה (באו\"א) <a class=\"ft-cite\" href=\"#/read/torah-or/3901370291\" data-slug=\"torah-or\" data-id=\"3901370291\">תו\"א בשלח שם סה, ב</a>."],["160","35","<b>והרוחות הנושבות הם מזככים את האויר</b>: באוה\"ת שם מובא זה בשם המהרש\"א לע\"ז י, א. עיי\"ש."]]],[2002180102,"<h3>צאינה וראינה כו' (א)</h3>\n<b></b><b>בס\"ד. (חה\"ש ט\"ל, יום א' קודם התפלה).</b>\n<b></b>ג' עטרות כו' על ג\"ד העולם כו' רוקע הארץ כו' מלח, מים חיים כו' עטרה דלעל\"ל - ז\"פ\nיום א' דחה\"ש\n<b>צאינה</b> וראינה<sup data-n=\"161\">1</sup> בנות ציון במלך שלמה בעטרה שעטרה לו אמו ביום חתונתו, פי' במלך שלמה היינו במלך שהשלום שלו זה הקב\"ה, בעטרה שעטרה לו אמו זה כנס\"י, כמשארז\"ל לא זז מחבבה עד שקראה בתי כו' עד שקראה אחותי כו' עד שקראה אמי, הרי כי נקראים נש\"י בשם אמי. ביום חתונתו זו מ\"ת, וא\"כ הרי נתבאר שבמ\"ת עטרו והכתירו נש\"י עטרה להקב\"ה. ולכאורה צ\"ל הלא ארז\"ל בשעה שהקדימו ישראל נעשה לנשמע ירדו מלאכי השרת וקשרו להם ב' כתרים אחד כנגד נעשה ואחד כנגד נשמע, הרי כי בשעת מ\"ת עטרו את כ\"א מישראל בשני כתרים, ואיך נאמר בעטרה שעטרה לו להקב\"ה אמו זו כנס\"י ביום חתונתו זו מ\"ת.\n<b>אך</b> באמת שניהם אמת. דהנה במד\"ר פ' קדושים ע\"פ קדושים תהיו כי קדוש אני איתא משל למלך שעשו לו בני המדינה ג' עטרות מה עשה המלך נטל אחת ונתן בראשו ושנים נתן בראש בניו, כך העליונים מכתירים ג' קדושות להקב\"ה בכל יום וכמש\"א כתר יתנו לך מלאכים כו' ועמך ישראל, מה עושה הקב\"ה נוטל קדוש א' לעצמו, הה\"ד כי קדוש אני, ושנים נותן בראש בניו (אלו נש\"י כמ\"ש בני בכורי ישראל בנים אתם להוי' אלקיכם) הה\"ד קדושים תהיו, וכתיב והתקדשתם והייתם קדושים, וא\"כ יש כאן ג' עטרות אחד שנטל לעצמו ושנים שנתן בראש בניו, וזהו בעטרה שעטרה לו להקב\"ה אמו זו כנס\"י זהו עטרה שנטל לעצמו. (והגם כי במד\"ר אמר העליונים מכתירים ג' קדושות שהכוונה על המלאכים שאומרים ג\"פ קדוש, ואיך היא העטרה שעטרה לו אמו זו כנס\"י. אך זה יובן ע\"פ מארז\"ל (בחולין דצ\"א סע\"ב) שאין מלאכי השרת אומרים שירה עד שיאמרו ישראל למטה תחלה שנאמר ברן יחד כל כוכבי בקר והדר ויריעו כל בני אלקים (איוב ל\"ח ז') שנמצא שמה שהמלאכים מכתירים תלוי בישראל דוקא. ומ\"ש ביום חתונתו זו מ\"ת והלא בכ\"י מכתירים נש\"י והעליונים הם מה\"ש ולמה תלה זה במ\"ת. אך הנה השירה שנש\"י אומרים זהו ק\"ש שמע ישראל כו' אחד, וארז\"ל במד\"ר ואתחנן קרוב לסוף הפרשה,",[["161","1","<b>צאינה וראינה</b>: מאמר זה (והמשכו המאמר שלאח\"ז ד\"ה והנה איתא בס\"י אם רץ לבך) הוא מיוסד והגהות על ד\"ה זה בס' תרט\"ז [גוכי\"ק אדמו\"ר מהר\"ש 1029 קכה, א. והוא כרך כת\"י הכולל הנחות של מאמרי אדמו\"ר הצ\"צ משנת תרט\"ז], והוא מיוסד על ד\"ה קדושים תהיו: בס' מאמרי אדה\"ז תקס\"ב ח\"א ע' קעד ואילך. ח\"ב ע' תכ ואילך. מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תקלג. וע' תקפב. אוה\"ת ויקרא (כרך ד) ע' א'נח ואילך. דרך מצותיך קנג, ב ואילך. ובשינויים וכו' בד\"ה והתקדשתם בסה\"מ תרכ\"ו ע' פ ואילך. ד\"ה קדושים תהיו: בסה\"מ תרכ\"ט ע' קעח ואילך. (ובהנסמן שם בתחילת המאמר). תרנ\"ד ע' רמה. תרנ\"ו ע' שלז. עטר\"ת ע' שפז. תרפ\"ג ע' רכא.\nפ\"א ורפ\"ב של המאמר כאן נמצא ג\"כ בתוס' הגהות בסה\"מ תר\"ן ע' שנא-שנג. והמשך המאמר כאן נמצא שם בהרחבת הביאור ע' שנג ואילך. ובד\"ה צאינה וראינה: בסה\"מ עזר\"ת ע' קצג ואילך. ובסה\"מ תרח\"ץ ע' רמב ואילך. ועד\"ז בסה\"מ תש\"ח ע' 201 ואילך.\nראה להלן בהוספות הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע ממאמר זה, ושם הוא מחולק לב' ד\"ה: א) ד\"ה צאינה וראינה (עד סוס\"ג). ב) ד\"ה על ג' דברים (ס\"ד ואילך)."]]],[2002180103,"שמהיכן זכו ישראל לק\"ש ממתן תורה, שפתח הקב\"ה שמע ישראל, אנכי ה' אלקיך כו', נענו כולן ואמרו ה' אלקינו ה' אחד, והיינו כי ה' אלקינו הוא<sup data-n=\"162\">2</sup> קיבול על הדבור אנכי ה' אלקיך, וה' אחד הוא קיבול על דבור לא יהי' לך, ונמצא מובן שז\"ע העטרה שעטרה אמו זו כנס\"י ביום חתונתו זו מ\"ת דוקא. אמנם באמת מכתירין אותו בכל יום בבחי' עטרה זו, כי יש בחי' מתן תורה בכל יום שזהו שמברכין נותן התורה ל' הוה כו' כמ\"ש מזה בת\"א ד\"ה ויאמר משה אכלוהו היום<sup data-n=\"163\">3</sup> ובמ\"א בד\"ה מי זאת הנשקפה כמו שחר<sup data-n=\"164\">4</sup> ובכ\"ד, וק\"ש היינו ה' אלקינו ה' אחד הוא קבלה על אנכי ולא יהי' לך שכוללים כלליות תרי\"ג מצות שאנכי כולל רמ\"ח מ\"ע, ולא יהי' לך כולל שס\"ה ל\"ת כמ\"ש בסש\"ב ר\"פ ך'<sup data-n=\"165\">5</sup>) ושנים שנתן בראש בניו זהו שבשעה שהקדימו נעשה לנשמע ירדו מלאכי השרת וקשרו להם ב' כתרים אחד כנגד נעשה כו'.\n<b>ולהבין</b> ענין ג' עטרות, והעטרה שנטל לעצמו, גם להבין מ\"ש (ישעי' ד' ג') והי' הנשאר בציון והנותר בירושלים קדוש יאמר לו וארז\"ל (בב\"ב דע\"ה ע\"ב) עתידין צדיקים שיאמרו לפניהם קדוש כדרך שאומרים לפני הקב\"ה, ופי' רש\"י ז\"ל שלע\"ל יאמרו המלאכים קדוש לפני הצדיקים כדרך שאומרים עכשיו לפני הקב\"ה. ולכאורה זהו דבר תימא מאד איך יתכן שיאמרו קדוש לפני הצדיקים כדרך שאומרים לפני הקב\"ה. ובס' כלי פז על ישעי' הביא שהרמ\"ק<sup data-n=\"166\">6</sup> בס' הפרד\"ס שלו",[["162","2","<b>כי ה' אלקינו הוא קיבול על הדבור אנכי ה' אלקיך וה' אחד הוא קיבול על דבור לא יהי' לך</b>: ראה גם לקמן ד\"ה את ה' האמרת ובהערת כ\"ק אדמו\"ר זי\"ע שם. ובסה\"מ תש\"ח שם (ע' 203) מעיר ע\"ז כ\"ק אדמו\"ר זי\"ע: עפמ\"ש בירושלמי ברכות פ\"א ה\"ה. — והנה לכאורה זה הוא רק להסוברים דלא יהי' לך הוא אזהרה דיחוד, וכדעת הרמב\"ם (סהמ\"צ מל\"ת א. הל' יסוה\"ת פ\"א ה\"ו) הרמב\"ן (על סהמ\"צ מ\"ע א ומל\"ת ה) סמ\"ג (מל\"ת א) ועוד. ועייג\"כ שאילתות יתרו נב. אבל לא לדעת בה\"ג (כפי גירסתנו וכפי' הרמב\"ן שם) רש\"י (שמות כ, ג) וסייעתם, דס\"ל דלא יהי' לך הוא אזהרה לקיום צלמים. — אבל באמת גם לשיטת בה\"ג ורש\"י כן הוא, דמלבד דאמונת היחוד הבאה ב”ה' אחד\" במילא שוללת גם קיום צלמים הנאסר ב”לא יהי' לך\", הנה: א) אף דלא יהי' לך הוא אזהרה פרטית דקיום צלמים, ענינה וכונתה הוא השלילה דע\"ז בכלל (בצד הל\"ת) וחיוב אמונת היחוד (בצד הקום עשה). דוגמא לדבר לא תבערו אש, שהוא ציווי פרטי דהבערה, וענינו וכונתו השלילה דחילול שבת וחיוב דקדושת שבת. — ב) גם לבה\"ג ורש\"י אין מקרא דלא יהי' לך יוצא מידי פשוטו שהוא איסור ע\"ז אלא דמאחר דכמה לווין כתובים בע\"ז, במקום דאיכא למידרש דרשינן, ודרשינן מיתורא גם איסור דקיום צלמים. וכמש\"פ בביאור מהרי\"פ פערלא לסהמ\"צ להרס\"ג מ\"ע ג-ד. וע\"פ שתי דרכים אלו סרה התמי' על שיטת בה\"ג ורש\"י ממרז\"ל דלא יהי' לך הוא ענינא דע\"ז (ראה גיטין נז, ב. ירוש' קידושין פ\"א ה\"ב. שמ\"ר פמ\"ד, ט. במד\"ר פ\"ח, ד. זח\"ב פו, א. ועוד). גם יובן מפני מה לא יהי' לך שמענו מפי הגבורה (עיין מו\"נ ח\"ב פל\"ג. תניא רפ\"כ). וסרה ג\"כ קושית הרמב\"ן (בפי' עה\"ת) על שיטה הנ\"ל.\nוראה לקמן בהוספות הערת ומכתב הרה\"ג הרה\"ח הרא\"ח ראזנבוים ששאלו את כ\"ק אדמו\"ר מהר\"ש עמ\"ש כאן במאמר זה, ומה שהשיב ע\"ז."],["163","3","<b>בת\"א ד\"ה ויאמר משה אכלוהו היום</b>: פ' בשלח סה, ב."],["164","4","<b>ובמ\"א בד\"ה מי זאת הנשקפה כמו שחר</b>: תרל\"ט, לעיל ע' שצב."],["165","5","<b>כמ\"ש בסש\"ב ר\"פ ך'</b>: ראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח שם ע' 204."],["166","6","<b>ובס' כלי פז . . הביא שהרמ\"ק</b>: הובא באוה\"ת קדושים שם ע' א'נח. נ\"ך (כרך ב) ע' תשסב. עיי\"ש."]]],[2002180104,"הקשה קושי' זו וכתב שקשה הדבר להולמו, ותירץ הרמ\"ק בס' הפרד\"ס שצדיקים יתעלו לע\"ל בצדיק וצדק שהם יסוד ומל' ונודע כי יסוד ומל' הם מע\"ס דאצי' וא\"כ כשהמלאכים (דבריאה) יאמרו קדוש לפני הקב\"ה פי' הקב\"ה הוא ז\"א ומל' ממילא יאמרו לפני הצדיקים ג\"כ כנ\"ל שהצדיקים יתעלו לע\"ל בבחי' צדיק וצדק יסוד ומל'. אך זהו דוחק ורבינו ז\"ל תירץ תירוץ אחר<sup data-n=\"167\">7</sup> כמשי\"ת לקמן אי\"ה. ובכדי להבין ענין ג' עטרות שהם ג\"פ קדוש צ\"ל משארז\"ל על שלשה דברים העולם עומד על התורה ועל העבודה ועל גמ\"ח, והנה שלשה דברים אלו הם כנגד ג' עטרות הנ\"ל שהם ג\"פ קדוש כנ\"ל.\n<b>ולהבין</b> זה, הנה כתיב לרוקע הארץ<sup data-n=\"168\">8</sup> על המים כי לעולם חסדו, פי' כי הנה מצד טבע הבריאה היו המים על הארץ, שהמים היו מקיפים את הארץ מכל צד והארץ היתה מוקף מן המים, לפי כי יש ד' יסודות ארמ\"ע<sup data-n=\"169\">9</sup>, ע' בבחיי פ' בראשית, והנה ע\"פ דרכי הטבע הדבר אשר הוא כבד יותר נופל למטה יותר והדבר הקל בטבע שט למעלה, והדבר היותר קל שט יותר למעלה. ולכן יסוד העפר מפני כי הוא יסוד הגשמי יותר מכל הד' יסודות הי' למטה יותר, והמים מפני שהם קלים יותר בטבע מעפר היו על הארץ, וכנ\"ל שהמים היו מקיפים את הארץ מכל צד והארץ היתה מוקפת מן המים, ויסוד הרוח מחמת שהוא יותר קל ורוחני מן יסוד המים, לכן משכנו על יסוד המים כמ\"ש ורוח אלקים מרחפת ע\"פ המים, ויסוד האש מפני שהוא יותר רוחני מן יסוד הרוח<sup data-n=\"170\">10</sup> משכנו תחת גלגל הירח כנודע. וזהו מצד הבריאה ע\"פ דרכי הטבע כו', אבל אח\"כ גזר הוא ית' גזירה שיקוו המים<sup data-n=\"171\">11</sup> מתחת השמים אל מקום",[["167","7","<b>ורבינו ז\"ל תירץ תירוץ אחר</b>: ראה בד\"ה קדושים תהיו בס' מאמרי אדה\"ז תקס\"ב שם. וראה אוה\"ת נ\"ך (כרך ב) שם ע' תשסא: עתידים צדיקים שאומרים לפניהם קדוש כו' בד\"ה קדושים תהיו תקס\"ב פי' רבינו ז\"ל ענין ג\"פ קדוש ע\"ד ג' עטרות א' נטל לעצמו ושתים נתן לבניו כו' וסיים שזהו\"ע עתידים צדיקים כו' דלפי שע\"י האהבה דבכל מאדך גורמים המשכה מאוא\"ס ב\"ה באצי' שזהו\"ע הקדוש הראשון כו' לכן עתידים המלאכים שיאמרו על קדושת נש\"י קדוש כדרך שאומרים לפני הקב\"ה שהענין הוא שממשיכים מבחי' קדש העליון להיות ג\"פ קדוש, כמו\"כ למלאכים יומשך בחי' קדוש מנש\"י, והטעם לפי שנש\"י גרמו המשכת הקדשוה מאוא\"ס ממש בראשית האצי'. [וראה כאן לקמן בסוף המאמר פ\"ו-ז]."],["168","8","<b>ולהבין זה הנה כתיב לרוקע הארץ</b>: בהבא לקמן (עד סוף פרק א') ראה גם אוה\"ת קדושים שם ע' א'נט ואילך. סה\"מ תרכ\"ט שם ע' קעט ואילך (ובהנסמן שם ע' קעח). סה\"מ עזר\"ת שם ע' רד ואילך. סה\"מ תש\"ט ע' 185 ואילך. וראה הנסמן לעיל בתחילת המאמר."],["169","9","<b>לפי כי יש ד' יסודות ארמ\"ע</b>: בהערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח שם (ע' 204): ע\"ד ד' יסודות במד\"ר במדבר פי\"ד, יב. זח\"ב, כג, ב. רנד, ב. זח\"ג רכה, א. זהר חדש בראשית ספ\"ה. ברמב\"ם הל' יסוה\"ת ספ\"ג ורפ\"ד. ועוד. ע\"כ. וראה בארוכה בסה\"מ תרל\"ג ח\"ב ע' שפ ואילך."],["170","10","<b>ויסוד האש מפני שהוא יותר רוחני מן יסוד הרוח</b>: בהערת כ\"ק אדמו\"ר זי\"ע שם: שיסוד האש למעלה מיסוד הרוח כ\"ה בשמו\"ר פכ\"ג, יג. במדב\"ר שם, זח\"ב שם. ועוד. ומ\"ש באוה\"ח ס\"פ בראשית (ו, ה) מתורץ עפמ\"ש בתו\"א ס\"פ מקץ. ע\"כ."],["171","11","<b>אבל אח\"כ גזר הוא ית' גזירה שיקוו המים</b>: ראה אוה\"ת קדושים שם ס\"ע א'נט. והערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח שם (ע' 205)."]]],[2002180105,"אחד ותראה היבשה שנעשה הארץ למעלה מן המים שהם הים כו', וזהו לרוקע הארץ על המים כו'. ולכן כתיב יורדי הים שההולכים בים נקראים בשם יורדי הים שהוא בחי' ירידה לפי שהארץ הוא למעלה מן הים וכמ\"ש לרוקע הארץ על המים, כי לעולם חסדו שזהו חסד מאתו ית'.\nב) <b>והנה</b> באמת צ\"ל מפני מה מצד הבריאה היו המים על הארץ ואח\"כ גזר גזירה שיהיו המים מתחת לארץ והארץ יהי' על המים, ולמה לא ברא לכתחלה שיהי' הארץ על המים כמו עכשיו אחר הגזירה כו', ואף שזהו נגד הטבע הלא הוא ית' כל יכול כו'. והענין הוא דהנה ים ויבשה הם עלמא דאתכסיא ועלמא דאתגליא<sup data-n=\"172\">12</sup>, שים הוא בחי' עלמא דאתכסי' ויבשה היא הארץ בחי' עלמא דאתגליא. והנה ארז\"ל כל מה שיש ביבשה יש בים, והיינו שכל מה שיש בעלמא דאתגליא ישנו גם בעלמא דאתכסי', שכמו שנמצא ברואים בעלמא דאתגלי' ככה יש ברואים בעלמא דאתכסי' שהם המלאכים כו', ולכן מצינו שהמלאך אומר על עצמו בי נשבעתי, ולכאורה איך יכול לאמר על עצמו בי נשבעתי, והיינו מפני שאינו מסתיר כלל, ואף שהמלאכים יש להם ג\"כ גופים, רק שהגופים שלהם הם מאש ורוח<sup data-n=\"174\">13</sup> כמ\"ש עושה מלאכיו רוחות משרתיו אש לוהט הרי כי יש להם ג\"כ גופים אך הגוף שלהם אינו מסתיר כלל על האור המאיר כו', ומפני כי הגוף שלהם אינו מסתיר הם בבחי' ביטול ולכן יכול לומר על עצמו בי נשבעתי כו'. וכן אמר משה במשנה תורה ונתתי מטר<sup data-n=\"173\">14</sup> ארצכם, והקשו איך אמר על עצמו ונתתי. אך הענין הוא מפני כי משה הי' מעלמא דאתכסי' כמ\"ש מן המים משיתיהו, ולכן לא הי' הגוף שלו מסתיר כלל, ולכן הי' יכול לומר על עצמו ונתתי כו'. וזהו שנקראו המלאכים בזהר בשם נוני דימא רבא, והיינו שכמו ברואים שבים הם בטלים ומובלעים בתוך הים, שדגים שבים מיד שפורשים מן הים הם מתים שא\"א להם להפרד מן הים, גם כי הדגים הם קרירים בטבע לפי שהם מיסוד המים, משא\"כ ברואים שבארץ<sup data-n=\"175\">15</sup> אף שמקבלים חיות מן הארץ כי הארץ תוציא צמחה וכמ\"ש ארץ ממנה יצא לחם, והאדם ושאר הנבראים אוכלים מן הצומח כו', ואעפ\"כ אינם בטלים ומובלעים בארץ כמו ברואים שבים כו'. ובד\"כ ענין ים ויבשה הם מלאכים ונשמות, שהמלאכים הם ברואים שבים כנ\"ל שכמו הברואים שבים הם נבלעים בתוך הים כך המלאכים הם בטלים לו ית' כו', גם אין להם בחי' הבחירה כלל<sup data-n=\"176\">16</sup>, שמפני שהם מוקפים מן הים הם תמיד בבחי' הביטול, ע\"ד מ\"ש במשה כי מן המים משיתיהו",[["172","12","<b>והענין הוא דהנה ים ויבשה הם עלמא דאתכסיא ועלמא דאתגליא</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380143\" data-slug=\"likkutei-torah\" data-id=\"4001380143\">לקו\"ת צו טז, ד</a> ואילך. מאמרי אדה\"ז פרשיות ח\"א ע' רנה ואילך. רסז ואילך. שער האמונה לאדהאמ\"צ פנ\"ב ואילך. (פד, א ואילך). ובכ\"מ."],["174","13","<b>שהמלאכים . . שהגופים שלהם הם מאש ורוח</b>: ראה גם לעיל ד\"ה אז ישיר וד\"ה עבדו את ה' בשמחה. וש\"נ."],["173","14","<b>שהמלאך אומר . . בי נשבעתי . . וכן אמר משה ונתתי מטר</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380290\" data-slug=\"likkutei-torah\" data-id=\"4001380290\">לקו\"ת בחוקתי נ, א</a>. סה\"מ תרכ\"ט ע' ריד ואילך. תרל\"ב ח\"א ע' לט. תרל\"ג ח\"א ע' נא. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300031276\" data-slug=\"likkutei-sichot\" data-id=\"1300031276\">לקו\"ש ח\"ג ע' 1014</a>. ח\"ד ע' 1087. ועוד."],["175","15","<b>שדגים שבים מיד שפורשים . . משא\"כ ברואים שבארץ</b>: ראה לקמן בהנחת השומעים מהמאמר הערת הרה\"ח הרא\"ח ראזנבוים ע\"ז."],["176","16","<b>המלאכים . . אין להם בחי' הבחירה כלל</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט (נב, רע\"ב</a>). <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560384\" data-slug=\"or-hatorah-hb\" data-id=\"8316560384\">אוה\"ת נח תרנח, ב</a>. סה\"מ תרכ\"ט ע' קסד-ה. וש\"נ. תר\"ל ע' רסח. ועוד."]]],[2002180106,"היינו שהרבותא במשה הי' הגם כי הי' בבחי' ארץ אבל עכ\"ז הי' תמיד בבחי' הביטול, וזהו ע\"ד וידגו לרוב בקרב הארץ שיש נשמות שאפי' בבחי' ארץ הם בטלים כביטול הנוני ימא בבחי' ים, אבל זהו פרטי נשמות, אבל בד\"כ כל הנשמות כמו שנתלבשו בגוף הם ברואים שביבשה שכמו ברואים שביבשה הם נפרדים מן הארץ כך הנשמות הם נבראים נפרדים כו', גם יש להם בחירה שאם ירצה האדם יכול להיות כמשה רבינו (וכמארז\"ל מתי יגיעו מעשי למעשה אבותי, שקאי על האבות, וכן יכול להיות כמרע\"ה), וכמ\"כ בהיפך ח\"ו כו'.\n<b>והנה</b> מצד הבריאה כל שהוא נעלה במדריגה יותר הוא למעלה מן המדריגה שלמטה הימנו, ולכן מצד כי עלמא דאתכסי' הוא במעלה יותר מן עלמא דאתגלי', כי עלמא דאתכסי' הוא בחי' ביטול כנ\"ל, לכן הים שהוא בחי' עלמא דאתכסי' הי' למעלה מן הארץ דוקא, אבל אח\"כ גזר גזירה שהארץ יהי' למעלה מן הים שזהו מ\"ש לרוקע הארץ על המים, והיינו כי עיקר המכוון הוא הארץ דוקא שלכן ניתנה התורה למטה על הארץ דוקא כמשארז\"ל ששאלו אי' התורה, הים אמר אין בי, תהום אמר אין עמדי, רק היא ניתנת על הארץ דוקא. ולכן לא ניתנה התורה למלאכים כנודע שהמלאכים ביקשו שינתן להם התורה<sup data-n=\"177\">17</sup> והשיבם כלום יצה\"ר יש ביניכם, ולכאורה אין זה תירוץ כלל על מה שביקשו דאם היו מבקשים התורה כמו שהיא בגשמי' הי' תירוץ במה שהשיבם כלום יצה\"ר יש ביניכם ובלא יצה\"ר יש כמה מצות שא\"א לקיימם כו', אבל הלא המלאכים ביקשו התורה כמו שהיא ברוחניות וא\"כ מהו התירוץ כלום יצה\"ר יש ביניכם. אלא שלכך לא ניתן התורה למעלה למלאכים להיות שמפני עוצם הגילוי של התורה א\"א שתתגלה כ\"א למטה על הארץ דוקא, וכמו משל החותם שאינו ניכר על האבן טוב כלל מפני בהירות האבן טוב כ\"א כאשר חותמים בשעוה אז ניכר האותיות שבאבן טוב, וכמו\"כ התורה א\"א שתתגלה למעלה כ\"א למטה דוקא. וגם הנה כתיב אנכי עשיתי ארץ ואדם עלי' בראתי, בראתי גימ' תרי\"ג אלו תרי\"ג מצות, ואדם הוא בחי' התורה שנמשכת מבחי' אדם דלעילא שעל הכסא דמות כמראה אדם עליו מלמעלה, ושני בחי' אלו שהם בחי' תורה ומצות הם על הארץ דוקא, וכמ\"ש אנכי עשיתי ארץ ואדם עלי' היינו על הארץ דוקא בראת\"י תרי\"ג כנ\"ל, והיינו לפי שבאמת יש דיעה שהארץ קדמה אפי' לשמים וכ\"ש מבחי' הים שהשמים מקיפים את הים, והארץ היא קדמה גם לשמים, כמשארז\"ל בש\"א שמים קדמו ובה\"א ארץ קדמה, ונת' בכ\"ד שבמח' ארץ קדמה לשמים<sup data-n=\"178\">18</sup>, ולכן הי' הגזירה אח\"כ שיקוו המים מתחת השמים אל מקום אחד ותראה היבשה כמ\"ש לרוקע הארץ על המים, וזהו כי לעולם חסדו שהוא חסד שנמשך מאתו ית', וגם חסד נק' התורה כמ\"ש פיה פתחה בחכמה ותורת חסד על לשונה, שנק' התורה תורת חסד כו'.",[["177","17","<b>כמארז\"ל ששאלו אי' התורה . . כנודע שהמלאכים ביקשו שינתן להם התורה</b>: ראה גם ביאוה\"ז לאדהאמ\"צ א, סע\"ד ואילך. להצ\"צ ע' תריב ואילך."],["178","18","<b>ונת' בכ\"ד שבמח' ארץ קדמה לשמים</b>: ראה סה\"מ תרכ\"ז ע' רעו ואילך. תרכ\"ט ע' כג ואילך. שצח ואילך. תרל\"ב ח\"א ע' קט ואילך. וש\"נ."]]],[2002180107,"ג) <b>ולהבין</b> בתוס' ביאור ענין ים ויבשה<sup data-n=\"179\">19</sup>, הנה מי הים הם מלוחים וכמשארז\"ל (בשבת דף ק\"ט וכפרש\"י שם) שאסור לרחוץ בים בשבת מפני שמחזי כרפואה, ולכן נקראו מנהיגי הים בשם מלחים כמ\"ש (ביונה א' ה') ויראו המלחים, וכתיב (יחזקאל ך\"ז ט') כל אניות הים ומלחיהם, ע\"ש שמי הים הם מלוחים. והנה המים אלו של הים כאשר הם בוקעים את עפר הארץ נעשו מים חיים, שהמים אלו גופא נעשו מים חיים וכמ\"ש כל הנחלים הולכים אל הים כו' אל מקום שהנחלים הולכים שם הם שבים כו'. והנה המלאכים הם בים עלמא דאתכסיא נוני דימא רבא כנ\"ל, וכן הנשמות קודם התלבשותם בגוף הם ג\"כ בבחי' ים וכמ\"ש חי ה' אשר עמדתי לפניו, שכמו המלאכים שהם בבחי' ים כתיב בהם ויעמידם לעד כו' כך בנשמות קודם התלבשותם בגוף כתיב חי הוי' אשר עמדתי לפניו כנ\"ל, וגם בכתבי האריז\"ל מבואר שבשביעי ש\"פ שהוא זמן קרי\"ס אז הוא זמן לידת הנשמות והיינו כנ\"ל שהנשמות קודם התלבשותם בגוף הם בבחי' ים, וכאשר באים בגוף הנה העלי' שאחר הירידה היא במה שנעשו כמו בחי' מים חיים, כנ\"ל במשל שכאשר המי הים בוקעים את עפר הארץ נעשו מים חיים כו', ומים חיים הוא גבוה במדריגה יותר נעלה מבחי' ים, שהם מחולקים גם לענין טהרת הטומאה שהים יש דיעה שהים הוא כמקוה, ויש דיעה שמטהר בזוחלין, אבל טומאות חמורות כמו זבין (וזבות יש ג\"כ דיעה בב\"י ריש ה' מקוואות רסי' ר\"א שצריכה מים חיים, רק אנן לא קיי\"ל כן כ\"א כמ\"ש התוס' מברייתא דת\"כ חומר בזב מבזבה שהזב טעון מ\"ח והזבה אינה טעונה מ\"ח) ומצורעים ומי חטאת אין הים מטהרן, אבל מים חיים מטהר כל הטומאות חמורות הנ\"ל<sup data-n=\"180\">20</sup>, כי מים חיים הוא מדרגה גבוה מאד וכמשארז\"ל באבות דר\"נ עשרה דברים נקראו חיים הקב\"ה נק' חיים שנאמר וה' אלקים אמת הוא אלקים חיים, תורה נק' חיים שנאמר עץ חיים היא כו', המים נקראו חיים שנאמר והי' ביום ההוא יצאו מים חיים כו', וא\"כ מים חיים הם מדרגה גבוה מאד.\n<b>ולהבין</b> ענין מי הים מלוחים שלכאורה הוא חסרון אך באמת גם זהו מעלה ומדרגה גבוה רק שמים חיים הוא מדרגה היותר נעלה, כי הנה כתיב ולא תשבית מלח<sup data-n=\"181\">21</sup> ברית אלקיך כו' על כל קרבנך תקריב מלח, שמלח הוא ברית ה' אלקי', שענין המלח הוא מה שהוא נותן טעם בדבר הנאכל וכמ\"ש היאכל תפל מבלי מלח, שהמלח אף שהוא עצמו הטעם שלו אינו טוב אך הוא נותן טעם טוב בהתבשיל, וכמו\"כ יובן למעלה שענין המלח הוא ברית ה' אלקי' שמחבר בחי' שם הוי' בשם אלקים כי הנה מחמת שם אלקים שיש בו ק\"ך צירופים יש יניקה לחיצוני'",[["179","19","<b>ולהבין בתוס' ביאור ענין ים ויבשה</b>: בהבא לקמן ראה אוה\"ת קדושים שם ע' א'סא ואילך. סה\"מ תרכ\"ט שם ע' קפ ואילך (ובהנסמן שם בע' קעח). סה\"מ עזר\"ת שם ע' ריב ואילך."],["180","20","<b>אבל מים חיים מטהר כל הטומאות חמורות הנ\"ל</b>: ראה גם אוה\"ת חוקת ע' תתס. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380481\" data-slug=\"likkutei-torah\" data-id=\"4001380481\">לקו\"ת שלח מב, ב</a>. ובציונים שם."],["181","21","<b>כי הנה כתיב ולא תשבית מלח</b>: בהבא לקמן ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380089\" data-slug=\"likkutei-torah\" data-id=\"4001380089\">לקו\"ת ויקרא ג, סע\"ד</a> ואילך. סה\"מ תרכ\"ט שם ע' קפ. סה\"מ עזר\"ת שם ע' ריח ואילך."]]],[2002180108,"כי בשם אלקים יש ה' אותיות<sup data-n=\"182\">22</sup> וכל אות יש בו ך\"ד צירופים ומצרופים אחרונים יש יניקה לחיצונים, ופעולת המלח היא שנותן טעם והיינו שהוא המשכה מבחי' טעמים בשם אלקים להמתיק הדינים דשם אלקים, וכמו שהמלח מפליט הדם מן הבשר כנודע שהדם הוא בחי' הגבורות שבו נאחזים הקליפות כו', וזהו שהים הוא מלוח ע\"ש כי אותיות י\"ם הם מצירופים אחרונים דשם אלקים וממ\"ח צירופים אחרונים דשם אלקים משם הוא יניקת הקליפות וכמ\"ש ותשליך במצולות ים כל חטאתם, שמצולות ים הוא בחי' עומקי הקליפות ושרש אחיזתם הוא באותיות י\"ם משם אלקים, והמלח הוא מחבר שם הוי' בשם אלקים להיות בחכמה אתברירו כו', וזהו שמי הים הם מלוחים שהוא בחי' הטעם הנמשך בשם אלקים, ושרש הטעמים גבוהים מאד שהוא מבחי' טעמים נקודות תגין אותיות<sup data-n=\"183\">23</sup> כו', וזהו מלח בגימ' מזל<sup data-n=\"184\">24</sup> שנמשך מבחי' מזל כו'.\n<b>אמנם</b> מים חיים גבוהים יותר. ובד\"כ החילוק בין מים חיים למי הים הוא, שבחי' מלח בחי' מי הים מלוחים בד\"כ הוא ענין הצדיקים, וזהו ברית ה' אלקיך ומאן דנטיר ברית אקרי צדיק<sup data-n=\"185\">25</sup> כמ\"ש בזהר בכמה דוכתי, משא\"כ מים חיים הוא בחי' בע\"ת ובמקום שבע\"ת עומדים צד\"ג אינם יכולים לעמוד שם, והיינו כי בע\"ת הוא בחילא יתיר יותר מבחי' הצדיקים.\n<b>ובד\"כ</b> בחי' צדיקים ובע\"ת הוא ב' בחי' אהבה, אהבת בכל נפשך ואהבת בכל מאדך. הצדיקים הוא בחי' אהבה בכל נפשך, וכמו\"כ המלאכים והנשמות קודם התלבשותם בגוף ונה\"ב, שהאהבה היא ע\"פ טעם ודעת וכמ\"ש לאהבה את ה' כי הוא חייך שהוא ע\"פ טעם ודעת, אבל אהבת בכל מאדך היא בלי גבול ושיעור כלל, ומגיע לעצמיות אוא\"ס ב\"ה שלמעלה מבחי' החכמה, ובאה מההיפוך דוקא דהיינו מבחי' ההסתר, שזהו ענין התשובה שפי' תשובה הוא אינו על עוונות דוקא כ\"א מי שהוא בעל עסק ועוסק במו\"מ אזי בשעת העסק במו\"מ הוא נפרד מאלקות ואח\"כ כששב מהעסק ומתפלל נעשה אצלו תגבורת יותר ויכול לבוא למס\"נ באחד, וז\"ע אהבת בכל מאדך שהיא אהבה בלי גבול, (ועפי\"ז יובן<sup data-n=\"186\">26</sup> מעלת תפלת המנחה שארז\"ל שאליהו לא נענה אלא בתפלת המנחה דוקא, כי תפלת השחר הוא כאשר האדם קם משנתו שנעשה ברי' חדשה ואין לו דבר המסתיר כ\"כ, אבל מנחה שכל",[["182","22","<b>כי בשם אלקים יש ה' אותיות . . כ\"ד צירופים .ֿ. יניקה לחיצונים</b>: ראה הערות כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ט ע' 187."],["183","23","<b>ושרש הטעמים גבוהים . . טעמים נקודות תגין אותיות</b>: ראה בארוכה לעיל ח\"א ד\"ה ששים המה מלכות. וש\"נ."],["184","24","<b>וזהו מלח בגימ' מזל</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380090\" data-slug=\"likkutei-torah\" data-id=\"4001380090\">לקו\"ת ויקרא ד, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380498\" data-slug=\"likkutei-torah\" data-id=\"4001380498\">שלח מו, ג</a>. [וראה לקמן בהנחת השומעים מהמאמר הערת הרה\"ח הרא\"ח ע\"ה ראזנבוים ע\"ז]."],["185","25","<b>ברית ה' אלקיך ומאן דנטיר ברית אקרי צדיק</b>: ראה לקמן בהנחת השומעים מהמאמר הערת הרה\"ח הרא\"ח ע\"ה ראזנבוים ע\"ז."],["186","26","<b>ועפ\"ז יובן מעלת תפלת המנחה</b>: בהבא לקמן ראה אוה\"ת וישלח רלה, א. רלז, סע\"ב ואילך. נ\"ך ס\"ע עא-ב. וע' עד ואילך. סה\"מ תרכ\"ז ע' נב ואילך. תרל\"ה ח\"א ע' ד ואילך. וע' טו ואילך. עזר\"ת ע' פב ואילך. תרפ\"ח ע' כט ואילך."]]],[2002180109,"היום הוא טרוד בעסקיו שהוא בחי' הסתר, ושב מהעסק ומתפלל מנחה ה\"ז בחי' תשובה, ולכן אלי' לא נענה אלא בתפלת המנחה, שמעלת תפלת מנחה כנגד שארי התפלות הוא כמו מעלת אהבת בכל מאדך נגד בחי' בכל נפשך), כי בכל מאדך היא כמ\"ש אליך ה' נפשי אשא וכמ\"ש בידך אפקיד רוחי ר\"ת באר, כמו שהבאר נובע תמיד כך אהבה זו היא בתמידות, כי אהבת בכל נפשך מחמת שהיא ע\"פ טעם ודעת לכן יכולה לפסוק אחר התפלה אבל אהבת בכל מאדך מפני שהיא למעלה מן הטו\"ד יכולה להיות בתמידות. ובד\"כ ההפרש שבין אהבת בכל נפשך בין אהבת בכל מאדך, שאהבת בכל נפשך היא אהבה בכלי, אבל אהבת בכל מאדך היא אהבה שאינה מתיישבת בכלי, שהיא אהבה שלמעלה מבחי' כלי וגבול, ועי\"ז מגיע לעצמיות אוא\"ס ב\"ה. וזהו עמוד העבודה כי עבודה היא בחי' עבודת הקרבנות שמקריבין הבהמה ע\"ג המזבח ומעלי' אותה כו', ואיתא בזהר שרזא דקורבנא עולה עד רזא דא\"ס, ועכשיו תפלות כנגד תמידין תקנו שע\"י בירור הנה\"ב מגיעים לרוממות עצמותו ית'.\n<b>וזהו</b> בחי' קדוש הא'<sup data-n=\"187\">27</sup>, פי' קדוש הוא ההתבוננות איך שהוא ית' הוא קדוש ומובדל ואינו בגדר עלמין ובי\"ה ה' צור עולמים שבשני אותיות נברא העולם ביו\"ד נברא העוה\"ב ובה' נברא העוה\"ז, ולא כמו שהנשמה מחי' את הגוף כו' אין ערוך לך לעצמותו ית', אשר ע\"י התבוננות זה תכסוף נפשו ליכלל וליבטל לעצמיות אוא\"ס ב\"ה שלמעלה מבחי' חכ', וזהו קדוש הא' אשר עי\"ז ממשיכים בחי' עטרה למלך שהשלום שלו, וזהו ענין הרצוא ליכלל וליבטל אליו ית'.",[["187","27","<b>וזהו בחי' קדוש הא'</b>: בהבא לקמן (עד ספ\"ד) בענין ג\"פ קדוש ראה בארוכה ד\"ה ונקדשתי בתוך בנ\"י ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380210\" data-slug=\"likkutei-torah\" data-id=\"4001380210\">לקו\"ת אמור לא, א</a> ואילך. [וראה אוה\"ת נ\"ך (כרך ב) שם ע' תשסא שמשנ\"ת כאן מד\"ה קדושים תהיו תקס\"ב הוא ע\"ד מ\"ש בד\"ה ונקדשתי בלקו\"ת אמור שם]."]]],[2002180110,"<h3>[על ג\"ד העולם] (ב) והנה איתא בס\"י</h3>\n<b></b><b>בס\"ד. (יום ב' דחה\"ש, בוקר קודם התפלה, ט\"ל).</b>\nיום ב' דחה\"ש\nד) <b>והנה</b> איתא בס\"י אם רץ לבך<sup data-n=\"188\">1</sup> שוב לאחד, וענין השוב הוא בחי' המצות שהוא קדוש הב' דגמ\"ח, כי הנה המצות שרשן גבוה מאד נעלה, וכמו שאנו מברכין אשר קדשנו במצותיו, אשר הוא בחי' תענוג ודבר נפלא כמשארז\"ל במד\"ר ע\"פ הנמצא כזה איש אשר רוח אלקים בו הה\"ד קמו בניה ויאשרוה בעלה ויהללה, וצ\"ל מהו השייכות והסמיכות של פסוק קמו בני' ויאשרוה לפסוק הנמצא כזה, אלא שפ' הנמצא כזה הוא שהוא דבר נפלא שהכל מהללים אותו לכן התחילו לדרוש ע\"פ",[["188","1","<b>והנה איתא בס\"י אם רץ לבך</b>: מאמר זה הוא המשך להמאמר שלפנ\"ז ד\"ה צאינה וראינה. לכללות המאמר ראה בהנסמן בתחילת המאמר. הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה נדפסה לקמן בהוספות ושם מתחיל: על שלשה דברים העולם עומד."]]],[2002180111,"זה מן הפסוק קמו בני' ויאשרוה שלשון ויאשרוה הוא לשון שהכל מהללים אותה מחמת שהוא דבר פלא, וכמו\"כ פי' אשר קדשנו במצותיו אשר הוא דבר פלא כו', וע\"י המצות ממשיכים מבחי' אשר תענוג עליון וכמ\"ש במ\"א<sup data-n=\"189\">2</sup> שע\"י המצות ממשיכים להיות לו ית' דירה בתחתונים.\n<b>וזהו</b> בחי' קדוש הב' להמשיך קדושתו ית' למטה. וזהו שתרגם בקדושא דבי סדרא על קדוש הא' קדיש בשמי מרומא עילאה, ועל קדוש הב' קדיש על ארעא עובד גבורתי', כי קדוש הא' הוא בחי' בכל מאדך שהיא בבחי' העלאה מלמטלמ\"ע, וע\"י העלאה זו נמשך תוס' אור למעלה, והיינו שע\"י העלאה זו נמשך בחי' כתר דאריך שהוא עטרה לו ית'<sup data-n=\"190\">3</sup> שז\"ע במלך שלמה בעטרה שעטרה לו אמו זו כנס\"י ע\"י העבודה כנ\"ל, אבל למטה אינו נמשך מזה כלום, לכן תירגם ע\"ז קדיש בשמי מרומא עילאה בית שכינתי' לפי שההמשכה הבאה ע\"י קדוש זה הוא בשמי מרומא כנ\"ל, אבל על קדוש השני תרגם קדיש על ארעא, לפי שע\"י קדוש הב' היינו קדוש דגמ\"ח שהם המצות ממשיכים דירה בתחתונים שהוא גילוי אלקותו ית' למטה בנבראים לכן תרגם על קדוש זה קדיש על ארעא כו'.\n<b>ועל</b> קדוש הג' תרגם קדיש לעלם ולעלמי עלמיא כי הנה קדוש הג' הוא קדוש דתורה. ולהבין ענין קדוש זה, הנה התורה היא הנותנת כח לההעלאה וכח לההמשכה, כי יכול האדם לומר ולהפיל א\"ע איך אוכל ע\"י עבודתי להגיע לעצמותו ית' רם ונשא שוכן שחקים, וכמו\"כ על המצות אשר אני עושה איך אוכל להמשיך דירה בתחתונים מי אנכי כי באתי עד הלום, לזה הוא ענין הקדוש הג' שהוא קדוש דתורה שהתורה היא הנותנת כח שיוכל להיות בחי' ההעלאה בק\"ש באהבת בכל מאדך והיא גם היא הנותנת כח שיוכל להיות ההמשכה ע\"י קיום המצות כו'. כי בד\"כ יש בלימוד התורה ב' דברים הא' הוא דבור התורה וכמ\"ש בכל התורה ל' וידבר ה' אל משה כו' דבר אל בנ\"י שעיקר מצות התורה היא בדבור, והב' הוא בחי' עיון התורה<sup data-n=\"191\">4</sup> שיעיין ויהגה תמיד בלימוד התורה שזהו ענין המחשבה שבלימוד תורתינו הקדושה (וכמ\"ש ובתורתו יהגה כו' ופרש\"י כל לשון הגה הוא בלב כד\"א והגיון לבי, לבך יהגה אימה כו', וא\"כ מ\"ש והגית יומם ולילה הוא מצות ההגיון בתורה, וענין ההגיון הוא המחשבה בתורה<sup data-n=\"192\">5</sup> כמשפרש\"י הנ\"ל ובמצ\"ד ובלע\"ז שם). והנה בחי' עיון התורה הוא מה שמקשר ומחבר בחי' המחשבה בתורה זהו בחי'",[["189","2","<b>וע\"י המצות ממשיכים מבחי' אשר תענוג עליון וכמ\"ש במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370362\" data-slug=\"torah-or\" data-id=\"3901370362\">תו\"א תצוה פא, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380045\" data-slug=\"likkutei-torah\" data-id=\"4001380045\">לקו\"ת בשלח א, ד</a>. ובכ\"מ."],["190","3","<b>כי קדוש הא' הוא בחי' בכל מאדך . . כתר דאריך שהוא עטרה לו ית'</b>: ראה בכ\"ז גם בסה\"מ תרכ\"ט שם ע' קפג ואילך (ובהנסמן בתחילת המאמר שם. בע' קעח ובע' קפה). סה\"מ תש\"ט שם ע' 193 ואילך."],["191","4","<b>כי בד\"כ יש בלימוד התורה ב' דברים . . דבור התורה . . עיון התורה</b>: ראה גם בס' מאמרי אדה\"ז על ענינים ע' רכד-ה. מאמרי אדהאמ\"צ ויקרא (כרך ב) ע' תקצג. ובכ\"מ."],["192","5","<b>ובתורתו יהגה . . וענין ההגיון הוא המחשבה בתורה</b>: ראה בכ\"ז אוה\"ת נ\"ך (כרך ב) ע' תתקטו."]]],[2002180112,"העלאה שמעלה את מחשבתו ומקשרה לבחי' התורה זהו הכח להשיג בחי' כח ההעלאה שנמצא בתורה שהיא הנותנת כח ועוז להיות בה וע\"י יוכל לבוא לבחי' העלאה באהבת בכל מאדך, ומצות הדבור בתורה עי\"ז הוא כח לבחי' ההמשכה שע\"י המצות, כי ע\"י דבור התורה נעשה ג\"כ בחי' המשכה כמשארז\"ל כל הקורא בתורה הקב\"ה קורא ושונה כנגדו, לכן דבור התורה היא הנותנת כח גם לההמשכה שע\"י המצות.\n<b>ובד\"כ</b> הנה ג\"פ קדוש אלו נמצא גם בק\"ש דהנה בפ' ראשונה של ק\"ש יש בה מ\"ב תיבין מן ואהבת עד ובשעריך, והנה נת' בזהר ששם מ\"ב עולה<sup data-n=\"193\">6</sup> ואינו יורד והרי הוא כדוגמת ענין הקרבן שעולה עד רזא דא\"ס כנ\"ל והוא בחי' ההעלאה בכל מאדך אשר עי\"ז נעשה ונמשך עטרה לו ית', אבל למטה אינו נמשך מזה כלום כו', ופ' שני' של ק\"ש הוא ענין המצות כמ\"ש בה והי' אם שמוע תשמעו אל מצותי, והוא בחי' המשכה מלמעלמ\"ט ע\"י המצות, ופ' שלישית של ק\"ש היא הכח לההעלאה והכח לההמשכה, כי כתיב אני ה' אלקיכם אשר הוצאתי אתכם מאמ\"צ, שהוא בחי' הכח אשר נתתי לכם לצאת ממצרים, וה\"ז כמו בחי' תורה שהיא נותנת כח להעלאת אהבת בכל מאדך והכח לההמשכה ע\"י המצות.\n<b>וזהו</b> ג' בחי' קדוש שהם ג' עטרות, הא' הוא מ\"ש כי קדוש אני הוא בחי' עטרה שנטל לעצמו וה\"ז מ\"ש במלך שלמה בעטרה שעטרה לו אמו זו כנס\"י ע\"י בחי' העבודה באהבת בכל מאדך, וב' עטרות שנתן בראש בניו הם בחי' קדוש דתורה וקדוש דמצות שזהו ב' עטרות שעיטרו לישראל בשעת מ\"ת כמשארז\"ל בשעה כו' ירדו מלאכי השרת וקשרו להם ב' כתרים א' כנגד נעשה ואחד כנגד נשמע.\nה) <b>ומעתה</b> צ\"ל מה שייך ב' עטרות אלו דתומ\"צ לנעשה ונשמע, הנה נעשה הוא בחי' הכלים ונשמע הוא בחי' האורות<sup data-n=\"194\">7</sup>, וגם נעשה הוא בחי' המצות, ונשמע הוא בחי' תורה, ושניהם עולה בקנה א', כי המצות הם כלים והתורה אור כמ\"ש כי נר מצוה ותורה אור שנמשל המצות לנר כמו שהנר מחזיק השמן ופתילה, והשמן ופתילה מחזיק האור, וא\"כ הנר מחזיק השמן ופתילה והאור, ככה המצות שנמשלו לנר הם הכלים להשראת האור דתורה, ולכן צ\"ל תחלה בחי' [הקדמת] נעשה לנשמע כי האור בלא כלי א\"א להיות נאחז כנודע. וזהו שאנו מבקשים קדשנו במצותיך ותן חלקינו בתורתך, שאנו מבקשים תחלה קדשנו במצותיך ואח\"כ ותן חלקינו בתורתך, והיינו מטעם הנ\"ל שהאור בלא כלי אינו נאחז.",[["193","6","<b>בפ' ראשונה . . מ\"ב תיבין . . ששם מ\"ב עולה</b>: ראה בכ\"ז לקו\"ת ואתחנן יב, ד. סה\"מ תרכ\"ז ע' שלא-ב. וע' שמ-מא. וש\"נ. תרכ\"ט ע רג. וש\"נ. וע' רמה-ו. וש\"נ."],["194","7","<b>הנה נעשה הוא בחי' הכלים ונשמע הוא בחי' האורות</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370434\" data-slug=\"torah-or\" data-id=\"3901370434\">תו\"א מג\"א צז, א</a>."]]],[2002180113,"<b>אך</b> הנה לכאורה צ\"ל הלא משמע מדברי רז\"ל בשעה שהקדימו ישראל נעשה לנשמע, שבעבור שהקדימו נעשה לנשמע ניתן להם הב' כתרים, ולא בעבור נעשה ונשמע<sup data-n=\"195\">8</sup>, ומשמע אם לא היו מקדימין נעשה לנשמע לא היו נותנים להם ב' כתרים, וכאן ביארנו שהב' כתרים הם בעבור ענין נעשה ונשמע שז\"ע תומ\"צ.\n<b>אך</b> הענין הוא, דהנה ענין בשעה שהקדימו הוא כמו ענין בכל מאדך שהוא הקדוש הא', והוא הקדמה בכדי שיוכל להיות נמשך אח\"כ ב' כתרים ע\"י תומ\"צ, כי הנה עצמותו ית' רם ונשא אינו בגדר עלמין כלל עד שנאמר שע\"י המצות והתורה ממשיכים אותו ית', כי באמת אין ערוך ענין המצות להיות נמשך בהם וע\"י ענין גילוי אלקותו ית', כי מה ערך המצוה גשמי' שמניחים תפילין להיות נמשך עי\"ז ד' מוחין או ע\"י הצדקה שיהי' נמשך דירה בתחתונים להחיות רוח שפלים כמ\"ש במ\"א<sup data-n=\"196\">9</sup>, רק שכך עלה ברצונו ית' שע\"י תומ\"צ ממשיכים בחי' זו, וא\"כ צריכין לעשות רצון זה שיתלבש בתומ\"צ להיות נמשך בהם וע\"י, וזהו ענין עושין רצוש\"מ, שצריכים לעשות רצון זה.\n<b>והנה</b> עושין רצש\"מ הוא בפ' ראשונה דק\"ש<sup data-n=\"197\">10</sup>, דהנה ארז\"ל ברפ\"ו דברכות דל\"ה ע\"ב אלא בזמן שישראל עושים רצוש\"מ ועמדו זרים ורעו צאנכם, ובזמן שאין ישראל ערש\"מ ואספת דגנך, וע' בתוס' ובחא\"ג של המהרש\"א שהקשו הלא ואספת דגנך נאמר בפ' שני' של ק\"ש דכתיב והא\"ש תשמעו אל מצותי, והתירוץ שמ\"מ אינו נק' עושים רצוש\"מ כ\"כ, והיינו מפני שלא נאמר בה בכל מאדכם<sup data-n=\"198\">11</sup> כמו בפ' ראשונה של ק\"ש דכתיב בה בכל מאדך, וא\"כ בכל מאדך הו\"ע עושין רצוש\"מ, והיינו שע\"י העלאת באהבת בכל מאדך הנה עושין רצונו ית' להיות נמשך ע\"י תומ\"צ, והיינו ע\"י ביטול הרצון במס\"נ בכל מאדך עי\"ז ממשיכים בחי' מאד בלי גבול להיות לו בחי' רצון שיומשך ע\"י תומ\"צ, ואף שהביטול הרצון של האדם אינו תופס מקום כלל לגבי' ית' אעפ\"כ הנה פי' בכל מאדך שהוא במאד שלך, ועי\"ז ממשיכים להיות לו רצון שיומשך אח\"כ ע\"י תומ\"צ. וכמו\"כ הוא ענין מה שהקדימו נעשה לנשמע שזהו מ\"ש כל אשר דיבר ה' נעשה ונשמע שזהו הקדמה שאח\"כ יומשך ע\"י בחי' נעשה ונשמע הם התומ\"צ, וא\"כ ניחא מה שמשמע שבעבור שהקדימו קשרו להם שני כתרים, דבאמת בלא ההקדמה לא הי' נמשך להם ב' כתרים של נעשה ונשמע שהם כתר דז\"א וכתר דמל' כי ע\"י התורה נמשך כתר דז\"א וע\"י המצות נמשך כתר דמל'.",[["195","8","<b>משמע מדברי רז\"ל . . שבעבור שהקדימו . . ניתן להם . . ולא בעבור נעשה ונשמע</b>: ראה בכ\"ז בארוכה סה\"מ תרכ\"ט ע' רב. [ובהנסמן שם בתחילת המאמר]."],["196","9","<b>להחיות רוח שפלים כמ\"ש במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370283\" data-slug=\"torah-or\" data-id=\"3901370283\">תו\"א בשלח סג, ב</a>. סה\"מ תרל\"ג ח\"ב ע' תסה. וש\"נ."],["197","10","<b>והנה עושין רצש\"מ הוא בפ' ראשונה דק\"ש</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380482\" data-slug=\"likkutei-torah\" data-id=\"4001380482\">לקו\"ת שלח מב, ג</a> ואילך. אמ\"ב שער הק\"ש פפ\"ו. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650124\" data-slug=\"or-hatorah-hb\" data-id=\"8316650124\">אוה\"ת נ\"ך (כרך ב) ע' תתנג</a>. סה\"מ תרכ\"ט ע' קצז (ובהנסמן בהמ\"מ שם)."],["198","11","<b>שהקשו הלא ואספת דגנך נאמר בפ' שני' . . והתירוץ . . שלא נאמר בה בכל מאדכם</b>: ראה או\"ת להה\"מ (הוצאת קה\"ת) פ' עקב נג, סע\"ג ואילך. סה\"מ תרכ\"ט ע' קצז שם. [ובהנסמן שם]. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121098\" data-slug=\"likkutei-sichot\" data-id=\"1300121098\">לקו\"ש חי\"ב ע' 98</a> ואילך [ובהנסמן שם]."]]],[2002180114,"וא\"ו) <b>והנה</b> כ\"ז הי' בשעת מ\"ת, אבל אח\"כ כתיב ויתנצלו בנ\"י את עדים מהר חורב שנטלו מהם הכתרים שניתן להם בשעת מ\"ת. אבל הנה ארז\"ל (שבת דפ\"ח ע\"א) ועתיד הקב\"ה להחזירם לנו<sup data-n=\"199\">12</sup> כמ\"ש ופדויי ה' ישובון ובאו ציון ברינה ושמחת עולם על ראשם ששון ושמחה ישיגו ונסו יגון ואנחה, פי' שמחת עולם על ראשם שמחה שמעולם על ראשם היינו הכתרים שהיו במ\"ת שעתיד העולם להזדכך ותחזיר עטרה ליושנה כמו שהי' בשעת מ\"ת, ואדרבה עטרה שתחזור לעתיד יהי' גבוה יותר שזהו משארז\"ל ועתיד הקב\"ה להחזירם לנו שהקב\"ה בעצמו יחזיר לנו העטרה. וענין העטרה שעתיד הקב\"ה להחזירם, ז\"ע משארז\"ל צדיקים יושבים ועטרותיהם בראשיהם שענין העטרה הוא בחי' כתר ונודע שהכתר הוא ממוצע בין א\"ס לע\"ס, שבכדי שיוכלו להאיר הארת א\"ס ב\"ה בע\"ס זהו ע\"י הכתר, שבחי' הכתר הוא הממוצע בין א\"ס לעולמות, כנודע ממ\"ש במ\"א<sup data-n=\"200\">13</sup>, וכמו\"כ בנפש הנה בחי' ח\"י שבנפש הישראלי היא ממוצע בכדי שיוכל להאיר הארת א\"ס בבחי' נר\"נ שבנפש.\n<b>ובזה</b> יובן מ\"ש והי' הנשאר בציון כו' קדוש יאמר לו וארז\"ל עתידים צדיקים שיאמרו לפניהם קדוש כדרך שאומרים לפני הקב\"ה, כי העטרה שיחזיר הקב\"ה לישראל יהי' נמשך מאתו ית' בעצמו ולא ע\"י מלאך, וא\"כ יהי' העטרה גבוה יותר מהמלאכים שהם נבראים, ולכן יאמרו המלאכים קדוש לפני הצדיקים. וע\"פ הקבלה הוא שלע\"ל יהי' עליית המל' ותעלה להיות בחי' כתר, ואז יהי' ההמשכה מבחי' מל' וכמ\"ש ביום ההוא יצאו מים חיים מירושלים חצים אל הים הקדמוני בחי' חכ', ויקבלו המלאכים ג\"כ ההשפעה מן בחי' מל' ולכן יאמרו המלאכים קדוש לפני כנס\"י כי הצדיקים הם כנס\"י הם בחי' מל' כנודע. ואז ששון ושמחה ישיגו וממילא ונסו יגון ואנחה, פי' כי ששון ושמחה הם יסוד ומל' דקדושה, ואת זלע\"ז עשה האלקים הם יגון ואנחה הם יסוד ומל' דקליפה וכשזה קם זה נופל, וא\"כ כשישיגו ששון ושמחה יסוד ומל' דקדושה ממילא ונסו יגון ואנחה יסוד ומל' דקליפה כי כשזה קם זה נופל.\n<b>וזהו</b> צאינה וראינה בנות ציון בעטרה שעטרה לו אמו, פי' כי לע\"ל יהי' גילוי גם בחי' עטרה שעטרה לו אמו ג\"כ, משא\"כ בשעת מ\"ת הי' רק ב' עטרות כנגד נעשה ונשמע, אבל לע\"ל יהי' גילוי גם בחי' העטרה שעטרה לו אמו, וזהו מעלת מה שעתיד הקב\"ה בעצמו להחזירם לנו כו'. וזהו צאינה וראינה שהוא לשון הילוך לצאת ולהיות בבחי' גילוי בחי' עטרה שעטרה לו אמו, שזהו כמשארז\"ל ע\"פ והתהלכתי בתוככם עתיד הקב\"ה לטייל עם צדיקיי' בגנתא דעדן, ולהבין ענין הטיול, הנה ענין טיול זה הוא כמ\"ש והי' מדי חדש בחדשו ומדי שבת בשבתו יבא כל בשר להשתחוות לפני אמר ה', שכמו שעכשיו יש הפרש בין שית יומין דחול ובין שבת<sup data-n=\"201\">14</sup> וחדש, שבשית",[["199","12","<b>ארז\"ל . . ועתיד הקב\"ה להחזירם לנו</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650068\" data-slug=\"or-hatorah-hb\" data-id=\"8316650068\">אוה\"ת נ\"ך (כרך ב) ע' תשצז</a>-ח."],["200","13","<b>שבחי' הכתר הוא הממוצע בין א\"ס לעולמות כנודע ממ\"ש במ\"א</b>: ראה סה\"מ תרל\"ב ח\"א ע' קלו-ז [ובהנסמן שם בתחילת המאמר]. ועוד."],["201","14","<b>שעכשיו יש הפרש בין שית יומין דחול ובין שבת</b>: בהבא לקמן ראה בארוכה לעיל ח\"א ד\"ה כרמי כו' האלף לך שלמה והמאמרים שלאחריו."]]],[2002180115,"יומין דחול מאיר בח\"ל מבחי' ו\"ק דעשי' ויצי' ובא\"י מו\"ק דבריאה, אבל בשבת הוא זמן עליית העולמות ומתעלים ו\"ק דעשי' בו\"ק דיצי', וו\"ק דיצי' מתעלים בו\"ק דבריאה, ובחי' ו\"ק דבריאה מתעלים בו\"ק דאצי', ככה לע\"ל יהי' ג\"כ עלי' אחר עלי' שזהו יבא כל בשר בבחי' עלי' אחר עלי' כמו בשבת וחדש עכשיו, וכמו\"כ הוא הטיול בג\"ע שזהו ענין והתהלכתי בתוככם, וכמו\"כ הו\"ע צאינה וראינה שהוא ל' הילוך ולהשיג בחי' עטרה שעטרה לו אמו. וזהו מ\"ש ולאמר לציון עמי אתה א\"ת עמי אלא עמי בחיריק<sup data-n=\"202\">15</sup>, והיינו שע\"י בחי' ציון בחי' התורה תבואו לבחי' עמי היינו כביכול עמי בשוה, והוא בחי' העטרה שנטל לעצמו בחי' בעטרה שעטרה לו אמו.\nז) <b>(וזהו</b> על ג' דברים העולם עומד על התורה כו', שג\"ד אלו זהו מ\"ש ואשים דברי בפיך זהו עמוד התורה, ובצל ידי כסיתיך זהו עמוד הגמ\"ח, לנטוע שמים וליסוד ארץ זהו עמוד העבודה<sup data-n=\"203\">16</sup> שהם הקרבנות שריחן עולה לשמים, וכמ\"ש סולם מוצב ארצה דא כבש המזבח, וע\"י ג' דברים אלו עי\"ז ולאמר לציון היינו למי שנשאר בציון הוא בחי' תורה כמ\"ש כי מציון תצא תורה ובירושלים הוא בחי' המצות, עמי אתה כביכול עמי בחיריק היינו בבחי' כתר אחד שהיא העטרה שעטרה לו אמו כנ\"ל, ולכן יאמרו המלאכים קדוש לפני הצדיקים המקיימים תומ\"צ שז\"ע ציון וירושלים כנ\"ל כדרך שאומרים עכשיו לפני הקב\"ה, מפני כי עמי אתה כבי' עמי בחיריק כו'. וזהו ג\"כ כמ\"ש ואנשי קדש תהיון לי, קדש הוא למעלה מבחי' קדוש, ולכן יאמרו לפניהם קדוש שהוא בחי' קדוש בוא\"ו מפני כי יתעלו להיות בבחי' קדש כו'.\n<b>ועוי\"ל</b> דהנה ענין בעטרה שעטרה לו אמו זו כנס\"י, הנה אמו מעטר העטרה למלך שהשלום שלו, אבל העטרה היא למעלה מבחי' אמו, ולע\"ל כתיב אשת חיל עטרת בעלה, שאשת חיל הוא כנס\"י תהי' לע\"ל העטרה עצמה והיינו שבחי' המל' תהי' במקום הכתר, והיינו בחי' כתר דאו\"ח, ולכן יצאו מ\"ח מירושלים דוקא אל* הים הקדמוני בחי' חכ', ומאחר שכנס\"י תהי' העטרה עצמה, א\"כ מובן ענין מה שעתידים המלאכים שיאמרו קדוש לפני כנס\"י כדרך שאומרים לפני הקב\"ה מלך שהשלום שלו להיותם בחי' העטרה שנטל לעצמו כו').\n\n*)אל הים הקדמונה בחי' חכ': בשולי הגליון נרשם בגוכי\"ק: (וגם י\"ל ים הקדמוני הוא בחי' ח\"ס חכ' בחי' חכ' שבכתר כי הת\"א מתרגם על בראשית ברא בקדמין, ועכ\"ז בקדמין הוא פירושו של בראשית שהוא בחי' ראשית חכ' וא\"כ הוא בחי' חכ' דא\"א, ולע\"ל יצאו מ\"ח מירושלים בחי' מל' אל הים הקדמוני בחי' ח\"ס חכ' שבכתר).",[["202","15","<b>עמי אתה . . עמי בחיריק</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380333\" data-slug=\"likkutei-torah\" data-id=\"4001380333\">לקו\"ת במדבר ו, ב</a> (ומציין לת\"ז תי\"ח לה, ב)."],["203","16","<b>זהו מ\"ש ואשים דברי בפיך . . עמוד התורה . . הגמ\"ח . . העבודה</b>: ראה בכ\"ז בארוכה אוה\"ת ויצא ריג, ב ואילך. דברים ע' לו ואילך. שם (כרך ו) ע' ב'תקצז ואילך. נ\"ך (כרך ג) ע' א'קפז ואילך. סה\"מ תרל\"א ח\"א ס\"ע יב-יג. ועוד."]]],[2002180116,"<h3>וידבר כו' בהעלותך כו' (א)</h3>\n<b></b><b>בס\"ד. (ש\"פ בהעלותך, ט\"ל).</b>\n<b></b>זה כה כו' אהרן אברהם מלמעלמ\"ט מלמטלמ\"ע - (פרק: א-ה)\nבהעלותך\n<b>וידבר</b> כו' דבר אל אהרן<sup data-n=\"204\">1</sup> ואמרת אליו בהעלותך כו' אל מול פני המנורה יאירו שבעת הנרות, וצ\"ל כפל הלשון דבר ואמרת. וגם צ\"ל לפי פי' רש\"י שפי' מול פני המנורה הוא נר האמצעי שהוא מגופו של מנורה, הל\"ל יאירו ששת הנרות. ועוד צ\"ל מה שפי' רש\"י למה נסמכה פרשת המנורה לחנוכת הנשיאים, שכשראה אהרן חנוכת הנשיאים חלשה דעתו שלא הי' עמם בחנוכה לא הוא ולא שבטו, א\"ל הקב\"ה חייך שלך גדולה משלהם שאתה מדליק ומטיב את הנרות, והוא מהמד\"ר במקומו פט\"ו, ומסיים ברבות שם הקרבנות כ\"ז שבהמק\"ד קיים הם נוהגים, אבל הנרות לעולם אל מול פני המנורה יאירו. ולכאורה אינו מובן כלל שהרי נרות המנורה הם ג\"כ רק בזמן שבהמק\"ד קיים לבד, ומהו\"ע שלך גדולה משלהם. והרמב\"ן בפי' החומש הקשה על פי' רש\"י, והביא מד\"ר הנ\"ל, ותירץ שהכוונה היא לרמז על נרות דחנוכה<sup data-n=\"205\">2</sup> שהי' הנס ע\"י הכהנים, שזהו גם בזמן שאין בהמק\"ד קיים. וזהו דוחק, ורבינו ז\"ל תירץ בא\"א<sup data-n=\"206\">3</sup>.\n<b>ויובן</b> בהקדם ענין נרות דזכרי' שא' ראיתי והנה מנורת זהב כו' ואומר מה אלה אדוני, ויאמר אלי זה דבר ה' אל זרובבל, ולכאורה אינו מובן מהו ענין זה דבר ה' לענין המנורה שראה. אלא שפירש לו שענין המנורה הוא המשכת בחי' זה בבחי' דבר ה', להיות כי פעם מצינו שנק' דבר ה' בשם זה, ופעם מצינו שנק' בשם",[["204","1","<b>וידבר כו' דבר אל אהרן</b>: מאמר זה מיוסד על ד\"ה זה מש\"פ בהעלותך תרי\"ח. הנחת המאמר מתרי\"ח נמצא בכת\"י 466 מט, ב [וכאן בס' תרל\"ט — כל המאמר הוא בגוכי\"ק אדמו\"ר מהר\"ש בשינויים והוספות רבות]. המאמר דתרי\"ח מיוסד על ד\"ה זה ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380428\" data-slug=\"likkutei-torah\" data-id=\"4001380428\">לקו\"ת בהעלותך כט, ג</a> ואילך. [ונו\"א בס' מאמרי אדה\"ז תקס\"ב ח\"א ע' רטו ואילך. ח\"ב ע' תנה ואילך. ובאריכות בס' מאמרי אדהאמ\"צ במדבר ח\"ג ע' תתפא ואילך.] חלק מהמאמר דתרי\"ח נמצא בשינויים באוה\"ת בהעלותך ע' שלו ואילך [שם הוא בלשון כ\"ק אדמו\"ר הצ\"צ בעצמו]. ונוסח נוסף מהנחת המאמר דתרי\"ח נמצא בכת\"י 1230 קלט, א (וקטעים מנוסח זה הובאו ונתבארו בד\"ה דבר גו' בהעלותך בסה\"מ תשי\"ג ע' 337 ואילך. ובהתוועדות ש\"פ מקץ תשי\"ג — תורת מנחם ח\"ז ע' 248 ואילך).\nחלק מהמאמר (מלקמן ריש ס\"ו עד סיום המאמר), נדפס ג\"כ באוה\"ת בהעלותך (הוצאת תשנ\"ז) בהוספות ע' 3 ואילך. [ולאח\"ז נתברר שהוא מכ\"ק אדמו\"ר מהר\"ש].\nלקמן בהוספות נמצא ג\"כ הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע ממאמר זה."],["205","2","<b>והרמב\"ן . . הקשה . . ותירץ שהכוונה . . על נרות דחנוכה</b>: הובא ונת' באוה\"ת בהעלותך ע' שכה. וע' שנד. שם בהוספות (הוצאת תשנ\"ז) ע' 2. לקו\"ש ח\"כ ע 509. סה\"ש תשמ\"ט ח\"ב ע' 523. תש\"נ ח\"א ע' 205. תנש\"א ח\"א ע' 196 ואילך. שערי המועדים חנוכה ע' רמב ואילך. ועוד."],["206","3","<b>וזהו דוחק ורבינו ז\"ל תירץ בא\"א</b>: ראה ד\"ה בהעלותך בס' מאמרי אדה\"ז תקס\"ג ח\"ב ע' תקסא: ויתורץ ג\"כ בזה קושיות הר\"נ שהביא הרמב\"ן בפי' החומש. עיי\"ש. ועד\"ז בס' מאמרי אדהאמ\"צ במדבר ח\"ג ר\"ע תתקז. [וראה שם ע' תתקל]. וב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830022\" data-slug=\"or-hatorah-hb\" data-id=\"8158830022\">אוה\"ת בהעלותך</a> בהוספות (הוצאת תשנ\"ז) ע' 22. וראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830024\" data-slug=\"or-hatorah-hb\" data-id=\"8158830024\">אוה\"ת בהעלותך שם ע' 24</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830007\" data-slug=\"or-hatorah-hb\" data-id=\"8158830007\">ושם בע' 35</a> מציין ע\"ז למ\"ש במ\"א בענין שלך גדולה משלהם שהכוונה לד\"ה בהעלותך תקס\"ג שם ונו\"א ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380438\" data-slug=\"likkutei-torah\" data-id=\"4001380438\">לקו\"ת בהעלותך לב, א</a>. עיי\"ש. — וראה הביאור בזה (באו\"א) לקמן פ\"ח."]]],[2002180117,"כה, וכמארז\"ל כל הנביאים נתנבאו בכה שדבר ה' שהי' מתגלה לנביאים נק' בשם כה, נוסף עליהם משה שנתנבא בזה כמ\"ש זה הדבר אשר ציוה ה', וענין בחי' המנורה הוא המשכת בחי' זה בבחי' דבר ה' שהי' נק' בזמן זכרי' בשם כה. וזהו זה דבר ה' שענין מראה הנבואה שראה זכרי' מנורת זהב כו' זהו המשכת בחי' זה בבחי' דבר ה' שנק' בשם כה כו' בימים ההם ובזמן ההוא כו'.\n<span data-k=\"ks\"><b>קיצור.</b> רש\"י פי' פני המנורה נר האמצעי, וצ\"ל דהל\"ל יאירו ששת הנרות, ובמד\"ר הנרות לעולם, ותי' הרמב\"ן שזהו נרות דחנוכה וזהו דוחק. ויובן בהקדם נרות דזכרי' שהם בחי' המשכת בחי' זה בבחי' דבר הוי' שנק' בשם כה כמארז\"ל כל הנביאים נתנבאו בכה.</span>\nב) <b>והנה</b> שרש ההפרש בין בחי' זה לבחי' כה, ז\"ע ההפרש שבין צלם לדמות<sup data-n=\"207\">4</sup> וכמ\"ש נעשה אדם בצלמנו כדמותינו, שענין בחי' הדמות הוא אינו עצם הדבר, כ\"א דמות הדבר ההוא לבד, וכמו דמות הנראה במראה שמצטייר דמות הדבר שעומד נגד המראה בכל פרטי ציורו שיש בדבר, אבל מ\"מ אינו עצם הדבר כלל כ\"א מה שנראה במראה לבד בבחי' או\"ח כמ\"ש במ\"א<sup data-n=\"208\">5</sup>, ואמנם בצלמנו הוא בחי' עצם צלם דבר ההוא. וכמ\"כ ענין בחי' כה אינו עצם הדבר כ\"א בחי' דמות דבר ההוא לבד, וכמ\"ש וביד הנביאים אדמה שהוא בחי' כה בחי' כדמותינו שהוא כמשל דמות הנראה במראה, וכמ\"ש במראה אליו אתודע, משא\"כ משה נתנבא בזה דכתיב בו ומראה ולא בחידות ותמונת ה' יביט באספקלריא המאירה שהוא כמו הרואה דרך זכוכית בהירה שרואה עצם מהות דבר הנראה כו' ולא דמותו לבד שמצטייר במראה (הנק' שפיגל בל\"א) שאינו עצם הדבר כלל כ\"א דמותו לבד כו'.\n<b>(ואמנם</b> עדיין צ\"ל ההפרש בין אסה\"מ לאשא\"מ, שהרי נת' בד\"ה וככה תאכלו פנ\"ז ופע\"ג<sup data-n=\"209\">6</sup>, שענין ראיית העין זהו לפי שגלגל שבעין שהוא בהיר מאד הנה מאחוריו הוא חשוך, וכשמביט באיזה דבר מצטייר דבר ההוא בכלי העין מפני החשכות שיש באחורי גלגל העין שאינו מניח לעבור יותר, כמו שציפוי כסף דק שמצפים הזכוכית שע\"י נעשה או\"ח מדבר שמראין בה, כ\"ה בכלי העין עצמו ג\"כ. וא\"כ לפ\"ז גם דבר שרואים בכלי העין עצמו ה\"ה ג\"כ ע\"ד הנראה באספקלרי' שאינה מאירה, ומהו ההבדל ביניהם. אמנם באמת אינם דומים כלל, שהרי כשמעמידים איזה דבר נגד המראה אז כשרואה אותה במראה ה\"ה רואה ציור דמות דבר שנראה במראה ע\"י כלי העין שלו שהוא ג\"כ כדוגמת מראה והיינו שדמות",[["207","4","<b>והנה שרש ההפרש בין בחי' זה לבחי' כה . . צלם לדמות</b>: בהבא לקמן בפיסקא זו ראה בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370153\" data-slug=\"torah-or\" data-id=\"3901370153\">תו\"א מקץ לג, א</a>-ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380909\" data-slug=\"likkutei-torah\" data-id=\"4001380909\">לקו\"ת נצבים מז, ג</a>. דרושים לשמע\"צ צב, סע\"ב. שה\"ש כח, ב. סה\"מ תרל\"ב ח\"א ע' פא. וע' צט. [ובהנסמן בהע' שלאח\"ז]."],["208","5","<b>כ\"א מה שנראה במראה לבד בבחי' או\"ח כמ\"ש במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381211\" data-slug=\"likkutei-torah\" data-id=\"4001381211\">לקו\"ת שה\"ש כ, ג</a>. סה\"מ תקע\"א ע' כד ואילך. [ובהנסמן בהע' שלפנ\"ז]."],["209","6","<b>שהרי נת' בד\"ה וככה תאכלו פנ\"ז ופע\"ג</b>: המשך וככה תרל\"ז ע' פז וע' קטז ואילך. וראה סה\"מ תר\"ם ח\"א ע' שמג. וש\"נ."]]],[2002180118,"שבמראה מצטייר בכלי עיניו, ולא עצם הדבר, אבל כשרואה בעיניו אם היות שכלי עיניו הם כדוגמת מראה עכ\"ז הציור שמצטייר בכלי העיניים הוא מחמת שעצם הדבר עומד לנגדו ונמצא מצטייר העצם אצלו, משא\"כ הדמות שרואה במראה אינו עצם הדבר כלל כ\"א דמות הדבר. ועד\"ז יובן בנמשל שענין הדמות מה שביד הנביאים אדמה עם היות שהדמות נעשה מעצם הדבר, אבל המתגלה להנביא אינו העצם כלל כ\"א מה שנדמה מהעצם, כמו הרואה במראה שאינו רואה עצם הדבר כלל כ\"א דמות הדבר לבד כו', משא\"כ משה שראה באספקלרי' המאירה ראה דרך אור ישר עצם הדבר, ואם היות שכלי העין הם עצמם עד\"מ הם כמו מראה (הנק' ש‘יגל) מ\"מ בכלי העין מצטייר עצם הדבר ולא דמותו כו', וע' בד\"ה וככה בפרקים הנ\"ל והסמוך להם שדמיון הנבואה הוא עד\"מ ענין הראי'<sup data-n=\"210\">7</sup> ולא כמו השגת השכל, שנת' שם שזהו ההפרש בין ראי' לשמיעה שאינו דומה ראי' לשמיעה כו' ובנבואה נא' ואראה כו').\n<b>ושרש</b> ענין בחי' זה למעלה ז\"ע בחי' יחו\"ע ויחו\"ת, שבצלמנו הוא בחי' יחו\"ע בחי' זה, וכדמותינו הוא בחי' יחו\"ת שנק' כה כו', שענין בחי' יחו\"ע הוא בחי' ביטול בעצם, משא\"כ בחי' יחו\"ת עם היות שגם בחי' יחו\"ת הוא בחי' ביטול אבל זהו רק בחי' ביטול היש לבד. ועד\"מ ביטול השמים וארץ וכל צבאם לבחי' האין המהוה ומחי' אותם, אם היות שהם בטלים עכ\"ז אין זה רק בחי' ביטול היש לאין לבד שזהו בחי' יחו\"ת, משא\"כ שרש בחי' שו\"א כמו שהם בשרש שרשן באצילות העליון שהם בחי' ז' מדות עליונות ה\"ה בטילים בתכלית הביטול בבחי' יחו\"ע כמ\"ש לך ה' הגדולה כו' לך ה' הממלכה שהם בטלים לך בתכלית הביטול דיחו\"ע כו'.\n<b>(ולכאורה</b> צ\"ל כפל לשון לך שא' לך ה' הממלכה, ולא כלל יחוד בחי' הממלכה בלך הראשון שא' לך ה' הגדולה, ולמה אמר עוד פעם לך ה'. אך הענין יובן ע\"פ משנ\"ת במ\"א<sup data-n=\"211\">8</sup> בד\"ה בקר ויודע ה' בהפרש שבין מדת המל' לכל הששה מדות דז\"א שכולם הם בבחי' קירוב, משא\"כ המל' יש ג\"כ מה שהוא בבחי' התנשאות דוקא ע\"ש. ולכאורה ענין ההתנשאות הוא היפך בחי' הביטול, לזה אמר שגם ההתנשאות דבחי' ממלכה הוא ג\"כ בטל לך, כי ענין ההתנשאות זהו שהוא מנושא ממה שלמטה הימנו, אך בבחי' לך הנה גם בחי' ההתנשאות דבחי' ממלכה ג\"כ בטל ע\"ד בחי' מדת הגדולה שבטל לך (כי ענין קריאת שם גדולה זהו ג\"כ כשהוא בעיר אלקינו דוקא, אבל בלא מטרוניתא לאו גדול איקרי כמ\"ש בזח\"ג ויקרא ד\"ה ע\"א, ועכ\"ז לך ה' הגדולה). וענין אומרו ממלכה ולא מלוכה<sup data-n=\"212\">9</sup>, זהו שגם בחי' הנק' ממלכה ג\"כ בטל לך כו' וכמ\"ש ואתם תהיו לי ממלכת כהנים ופי' בזח\"ג פ' צו",[["210","7","<b>וע' בד\"ה וככה בפרקים הנ\"ל והסמוך להם שדמיון הנבואה הוא עד\"מ ענין הראי'</b>: ראה המשך וככה שם ע' פד ואילך."],["211","8","<b>ע\"פ משנ\"ת במ\"א בד\"ה בקר וידע ה'</b>: סה\"מ תר\"ל ע' קעו ואילך. קפב ואילך."],["212","9","<b>וענין אומרו ממלכה ולא מלוכה</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600717\" data-slug=\"or-hatorah-hb\" data-id=\"8316600717\">אוה\"ת נ\"ך (כרך א) ע' תשיז</a>."]]],[2002180119,"דל\"ד סע\"ב דכד אתברכו כנס\"י ע\"י דכהני כדין אתקרי על שמיהון הה\"ד ממלכת כהנים, דענין שמתברכת ע\"י הכהן ז\"ע בחי' שושבינא דמטרוניתא, ועי\"ז נעשה בחי' מלוכה שז\"ע מדת ההתנשאות שבבחי' המל', וע' בפי' רש\"י בדה\"א סי' ך\"ט שפי' על תי' ממלכה<sup data-n=\"213\">10</sup>, דהנה בשר ודם כשממליך מלך, הנה המלך נעשה מלך אבל הממליכים אותו אינם מלכים, וכמו שפי' ר\"ש ממלכת כהנים דכהנים ממליכים לה ומחברא לה במלכא אבל מלכות כהנים לא אקרו, והיינו שהכהנים עצמם אינם מלכים כ\"א שממליכים את בחי' המל' על כל גינזי מלכא, אבל הקב\"ה אינו כן דעם היות שהוא ממליך מלכים עכ\"ז לו היא המלוכה כו', ולכן אמר ממלכה דאם היות שממליך כו' ומ\"מ לו היא המלוכה שהיא התנשאות דבחי' המל', ומ\"מ גם בחי' זו היא לך כו').\n<b>ועד\"ז</b> יובן בבחי' דבר ה' דנבואה, שכל הנביאים נתנבאו בכה ז\"ע שלא הי' מאיר אצלם בחי' הדבור דדבר ה' כמו שהוא באצי' בבחי' לך ה' הממלכה שהוא בחי' מל' בחי' דבר ה' כמו שהוא באצי' בבחי' יחו\"ע כנ\"ל, כ\"א בבחי' דמות לבד וכמ\"ש וביד הנביאים אדמה בחי' כדמותנו הנק' כה, אסשא\"מ כו'.\n<b>וז\"ע</b> מ\"ש זה דבר ה' אל זרובבל, שזהו מה שפירש לו דבר הנבואה שראה את המנורה במראות הנבואה. והענין הוא שישראל היו נקראים בזמן ההוא בשם זרובבל<sup data-n=\"214\">11</sup> ע\"ש וזרעתי' לי בארץ, וכמארז\"ל ברפ\"ח דפסחים, ולהיות כי נזרעו אז בבבל לכן נק' זרובבל שזהו ב' תיבות זרו בבל שנזרעו בארץ בבל, וע\"ש זה קראו הנשיא בשם זרובבל ע\"ש המאורע בימים ההם ובזמן ההוא, והצמיחה שנעשה ע\"י הזריעה שנזרעו בבבל זהו מה שנראה לזכרי' הנביא שהי' מן הנביאים שנתנבאו בכה, מראות מנורת זהב, ופירש לו שזהו ענין זה דבר ה' פי' שבבחי' דבר ה' יאיר בחי' זה בחי' אספה\"מ שנק' זה, והיינו בחי' דבר ה' כמו שהוא למעלה באצי' ששם הוא בבחי' דבר ה' היינו בבחי' המל' ג\"כ בחי' זה וכמ\"ש לך ה' הממלכה שגם בחי' דבר ה' הוא ג\"כ בבחי' לך ע\"ד כמו מדות הגדולה והגבורה והת\"ת שהם לך כו'. וע\"ד כמו שיהי' לע\"ל דכתיב ונגלה כבוד הוי' וראו כו' כי פי הוי' דבר שקאי על בחי' דבר ה' כמו שהוא מיוחד באצי' בבחי' הביטול דיחו\"ע כו'. ולכן ארז\"ל בירושלמי פ\"ק דמגילה הנביאים והכתובים עתידים להבטל, והיינו מפני כי לע\"ל יהי' גילוי בחי' זה כמ\"ש ואמר ביום ההוא הנה אלקינו זה, לכן הכתובים שהם מבחי' מל' שנק' כה וכן הנביאים שנתנבאו בכה עתידים להבטל, פי' שלגבי עוצם הגילוי שיהי' לע\"ל לא יהיו נחשבים כלל, כמ\"ש בת\"א בד\"ה יביאו לבוש מל' ובהביאור<sup data-n=\"215\">12</sup>, וע\"ד שרגא בטיהרא כו',",[["213","10","<b>וע' בפי' רש\"י בדה\"א סי' ך\"ט שפי' על תי' ממלכה</b>: ז\"ל רש\"י שם (כט, יא): מלך אם נתן לעבדו אחד שררה וממשלה במלכות אחר, השר הוא עבדו בכל מקום שהוא, אבל המלכות אינו של מלך, ומי שהמלכות שלו אין העבד המושל שלו, אבל הקב\"ה שלו הוא העבד הממונה למושל וגם המלכות שלו, אקטוריא בלע\"ז, ולפיכך כתיב לך ה' הממלכה והמתנשא עליהם."],["214","11","<b>וז\"ע מ\"ש זה דבר ה' אל זרובבל . . שישראל היו נקראים בזמן ההוא בשם זרובבל</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380428\" data-slug=\"likkutei-torah\" data-id=\"4001380428\">לקו\"ת בהעלותך שם כט, ג</a>."],["215","12","<b>בת\"א בד\"ה יביאו לבוש מל' ובהביאור</b>: דף צ, ד ואילך. צב, א ואילך."]]],[2002180120,"אבל חמשה חומשי תורה לא תבטל להיותם בחי' זה דבר ה' כמ\"ש זה הדבר אשר ציוה ה' וכמארז\"ל משה נתנבא בזה. ונודע כי ענין הגילוי שיהי' לע\"ל זהו ע\"י הזיכוך, וכנודע מארז\"ל שאברהם בחר שיעבוד מל' תחת הזיכוך דגיהנם, לכן הראו לזכרי' במראות הנבואה זה דבר ה' ע\"י בחי' זרובבל כנ\"ל.\n<span data-k=\"ks\"><b>קיצור.</b> זה וכה, בצלמינו וכדמותינו יחו\"ע ויחו\"ת, ופי' זה דבר שבבחי' דבר ה' יאיר בחי' זה ע\"י הזריעה שבבבל כו' ע\"ד כמו לע\"ל אלקינו זה, ולכן הנביאים שנתנבאו בכה יבטלו לע\"ל נגד גילוי בחי' זה אבל חמשה חומשי תורה לא יבטלו להיותם מבחי' זה כמ\"ש זה הדבר כו'.</span>\nג) <b>והנה</b> להיות המשכת בחי' זה בבחי' דבר, זהו ע\"י הכהן כמ\"ש ואתה כהן לעולם על דברתי, שבכדי שיומשך בחי' גילוי הדבור כמו שהוא למעלה שז\"ע דברתי ביו\"ד, פי' שיומשך מבחי' יו\"ד שרומז על החכמה כנודע בבחי' דבור זהו ע\"י הכהן כו', ולכן בכהנים כתיב וזה הדבר (בפ' תצוה ר\"פ ך\"ט) להיותם ממשיכים בחי' דבר כמו שהוא בבחי' זה, והיינו כמו שהוא באצילות דכתיב לך ה' הממלכה, שגם בבחי' דבר מאיר בחי' יחו\"ע שנק' זה, והו\"ע דברתי ביו\"ד כנ\"ל, וכנודע שאבא מקננא באצי' שז\"ע שבכלליות האצי' הוא בחי' הביטול דיחו\"ע כמו\"ש בבחי' מ\"ה דחכמה כו', וע\"י מה ממשיכים הכהנים בחי' זו זהו ע\"י המנורה.\n<b>כי</b> הנה נודע שהנשמה<sup data-n=\"216\">13</sup> קרויה נר, כמ\"ש נר הוי' נשמת אדם, וא\"כ כלליות הנשמות נק' בשם מנורה כו'. וענין ז' נרות המנורה זהו ענין ז' מדריגות שיש בעבודת ה' בכלליות הנשמות שנחלקים לז' מדריגות, יש מי שהוא עובד מאהבה, וכמו שיסד זכור אב<sup data-n=\"217\">14</sup> נמשך אחריך כמים שקאי על אברהם שעבודתו הי' בבחי' אהבה כמ\"ש אברהם אוהבי. ויש מי שעבודתו היא בבחי' האהבה ברשפי אש. ויש מארי תורה שהיא בבחי' קו האמצעי דת\"ת, ולכן ניתנה בחדש השלישי ובאלף השלישי, כמ\"ש בד\"ה מי זאת הנשקפה<sup data-n=\"218\">15</sup> שרומז לת\"ת, וכמארז\"ל והת\"ת זו מ\"ת. ויש מי שעבודתו הוא בבחי' נצחון שמתגבר בנצחונו בעבודת ה' להיות סור מרע ועשה טוב בפו\"מ, וזהו עבודת סתם אדם כל היום כו' כמ\"ש במ\"א<sup data-n=\"219\">16</sup>. ויש שעבודתו הוא בבחי' הודאה והיינו מי שמוחו קטן מלהתבונן ולבוא לבחי' הולדת אהוי\"ר מבחי' ההתבוננות, ולכן הרי הוא מודה שצ\"ל אהוי\"ר כו'. ויש מי שעבודתו הוא בבחי' התקשרות וכמ\"ש",[["216","13","<b>כי הנה נודע שהנשמה קרוי' נר</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380428\" data-slug=\"likkutei-torah\" data-id=\"4001380428\">לקו\"ת בהעלותך שם כט, ג</a> ואילך (ובהנסמן בהמ\"מ שם)."],["217","14","<b>וכמו שיסד זכור אב</b>: אוצ\"ל: שיסד הפייט (בתפילת גשם במוסף לשמע\"צ)."],["218","15","<b>בד\"ה מי זאת הנשקפה</b>: תרל\"ט נדפס לעיל לפני מאמר זה, ע\"ש באות ה'."],["219","16","<b>בבחי' נצחון . . וזהו עבודת סתם אדם כל היום כו' כמ\"ש במ\"א</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380165\" data-slug=\"likkutei-torah\" data-id=\"4001380165\">לקו\"ת תזריע כא, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380686\" data-slug=\"likkutei-torah\" data-id=\"4001380686\">מסעי צ, ג</a> ואילך. ועוד."]]],[2002180121,"והקשורים ליעקב שזהו מעלת ומדריגת הצדיקים שהוא עובד בבחי' חלק ה' שבו להיות יעקב חבל נחלתו שכמו החבל כשקשור ראשו א' למעלה והשני למטה כשמנענע בראש התחתון ינענע קצה העליון, והיינו שע\"י התקשרותו מגיע לשרש ומקור הנשמה כמו שהיא דבוקה וקשורה למעלה כו'<sup data-n=\"220\">17</sup>. ויש שעבודתו הוא ע\"י מדת ההתנשאות, וכמ\"ש ויגבה לבו בדרכי ה', וכמארז\"ל בס\"פ י\"ד דשבת כל ישראל בני מלכים הם, שזהו ז' נרות המנורה בחי' ז' מדריגות שיש בנשמות בעבודת ה'. ואהרן* הוא המדליק ומעלה את הנרות דנש\"י להיותו מבחי' ז' רועים שרועים ומפרנסים את נש\"י ע\"י המשכתם שממשיכים חיות אלקי לכלליות נש\"י, והוא הוא הממשיך אהבה עזה לה' להגדיל מדורת האהבה ברשפי אש שלהבת מתלהטת מקרב איש ולב עמוק כו'.\n<span data-k=\"ks\"><b>קיצור.</b> שלהיות המשכת בחי' זה בבחי' דבר זהו ע\"י הכהן כמ\"ש כהן כו' דברתי ביו\"ד, והיינו כמ\"ש באצי' לך ה' הממלכה, והמשכת הכהנים זהו העבודה במנורה שרומזת לכלליות כנס\"י וז' נרותי' זה\"ע ז' מדריגות בעבודת ה', ואהרן הוא המדליק ומעלה הנרות דנש\"י להגדיל מדורת האהבה מקרב ולב עמוק.</span>\nד) <b>ולהבין</b> שרש ענין פעולת אהרן כה\"ג בנש\"י<sup data-n=\"221\">18</sup>, יובן בהקדם ענין ההפרש מעלת מדריגת אהרן על מעלת ומדריגת אברהם, ששניהם הם בחי' אהבה, אך מדריגת בחי' אהבה דאהרן גבהה מעלתה על בחי' האהבה דאברהם כידוע. ולכאורה יפלא הלא באברהם נאמר אחד הי' אברהם (יחזקאל ל\"ג ך\"ד) וכן כתיב בו והי' ברכה\n\n*)ואהרן . . להיותו מבחי' ז' רועים: בשולי הגליון נרשם בגוכי\"ק: בענין מ\"ש בלק\"ת בד\"ה בהעלותך הראשון שאהרן הי' מז' רועים<sup data-n=\"1227\">19</sup> צ\"ל שבגמ' סוכה דנ\"ב ע\"ב וכן במד\"ר שה\"ש פ' ח' ע\"פ אם חומה (דל\"ח ע\"ב), לא חשב אהרן, שא' שם דוד באמצע אדם שת משתולח מימינו אברהם יעקב משה משמאלו. ואולי י\"ל לפי שמשה ואהרן הם ב' הבחי' שבהממוצע כמ\"ש מזה באורך<sup data-n=\"1228\">20</sup> בד\"ה ענין קי\"ס ובד\"ה ויצום<sup data-n=\"1229\">21</sup> אל בנ\"י, ובד\"ה הוא משה ואהרן<sup data-n=\"1230\">22</sup>, ולכן מאחר שחושב משה גם אהרן בכלל. ודוחק.",[["220","17","<b>ויש מי שעבודתו הוא בבחי' התקשרות . . דבוקה וקשורה למעלה כו'</b>: תיבות אלו (אודות בחי' ההתקשרות מדת היסוד) נוספו בגוכי\"ק לאחר זמן כהגה\"ה מן הצד. ולהעיר שגם ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380428\" data-slug=\"likkutei-torah\" data-id=\"4001380428\">לקו\"ת בהעלותך שם כט, ג</a> לא נזכר אודות מדת היסוד, וראה ד\"ה בהעלותך תשכ\"ח ותשמ\"ח (סה\"מ תשמ\"ח (הוצאת תשס\"ב) ע' 411). סה\"ש תשמ\"ח ח\"ב ע' 483 הע' 56."],["221","18","<b>ד) ולהבין שרש ענין פעולת אהרן כה\"ג בנש\"י</b>: בהבא לקמן (עד סוס\"ה) ראה לקו\"ת בהעלותך שם ס\"ב ואילך."],["1227","19","בלק\"ת בד\"ה בהעלותך הראשון שאהרן הי' מז' רועים: שם דף כט, ג. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201655\" data-slug=\"likkutei-sichot\" data-id=\"1300201655\">לקו\"ש ח\"כ ע' 643</a>."],["1228","20","כמ\"ש מזה באורך בד\"ה ענין קי\"ס: ראה אוה\"ת בשלח ע' תקע. וראה גם ביאוה\"ז לאדהאמ\"צ קמב, ג. ולהצ\"צ (כרך א') ע' תמא. סה\"מ תרל\"ב ח\"א ע' קלד."],["1229","21","ובד\"ה ויצום אל בנ\"י: אוה\"ת וארא ע' רה ואילך. [וראה גם בהמ\"מ בסה\"מ תרל\"ח ע' א]."],["1230","22","ובד\"ה הוא אהרן ומשה: סה\"מ תקס\"ג ח\"א ע' קכב ואילך."]]],[2002180122,"ופי' רש\"י יכול יהיו חותמין בכולם ת\"ל והי' ברכה בך חותמין<sup data-n=\"222\">23</sup> כו' והוא מהגמ' פסחים דקי\"ז, ואיך אנו אומרים שמעלת אהבת אהרן גדלה על מעלת אברהם אוהבי כו'.\n<b>אך</b> הענין דכתיב ואהבת את ה' אלקיך, ונודע כי שרש תיבת אהבה היא אבה שפירושה לשון רצון, וא\"כ פי' ואהבת שהרצון יהי' לאלקות כי העיקר הוא הרצון שהוא בחי' פנימיות המדות וקיומם, וכמו שאנו רואים בחוש שהכל תלוי ברצון והרצון מנהיג מדות האדם, כמו עד\"מ כשיש לפניו דבר שיש בו תענוג לפי טבע המדות, מ\"מ אם מסלק רצונו מדבר ההוא מפני איזה טעם שיש לו בזה, אינו מקבל תענוג כלל מדבר ההוא, הרי כי הרצון מהפך טבע המדה שמצד עצמה כו', וכן להיפך כשיש לו לאדם איזה צער ח\"ו והוא ממלא רצונו בצער ויסורים שעושה בעצמו אינו מרגיש כ\"כ את הצער שמצטער כו'. וע\"ד שמצינו בר' יהודה חסיד שהי' מתענה בכל יום גם בשבת, שלכאורה השבת מצוה לענגו, אלא מפני שהי' אצלו הרצון חזק להתענות דוקא, והעדר התענית לצער הי' נחשב אצלו לכן התענה גם בשבת למלאות רצונו שהי' מתענג מזה, וזה עצמו הי' אצלו ענג שבת כו'. וע\"ד שהתירו להתענות תענית חלום בשבת אם נפשו עגומה עליו, והיינו מפני שהתענית אם כי בעצם מצער גוף האדם, מ\"מ כשיש לו רצון חזק בזה, הנה הוא מקבל ענג מזה. ונמצא כי הרצון מהפך טבע המדה שמצד עצמה. וזהו ואהבת את כו' שכל הרצון יהי' לאלקות שלא יהי' בחי' רצון וחפץ אחר זולתו ית' וכמ\"ש מי לי בשמים ועמך לא חפצתי בארץ, וכתיב כלה שארי ולבבי.\n<b>והאיך</b> יהי' הדרך לאהבה זו, הקדים הכתוב פסוק שמע ישראל כו', והיינו להתבונן היטיב ולשום על לבו איך שהוא ית' אחד בשמים ובארץ וד' רוחות העולם, שע\"ז רומז תי' אחד החי\"ת רומז לז\"ר וארץ, והד' רומז לד' רוחות העולם שהם בטלים להאל\"ף שרומז לאוא\"ס ב\"ה אלופו של עולם, ולכן נאמר אחד ולא יחיד<sup data-n=\"223\">24</sup> לפי שבתיבת אחד דוקא מרומז איך שבחי' המקום דו\"ק מעלה ומטה וד\"ר העולם בטלים לאלופו של עולם. ושרש ו\"ק אלו הם ששה מדות עליונות שיש בהם מעלה ומטה, מעלה הוא בחי' השגה היותר עליונה מבחי' שלמטה הימנה, וכן ימין ושמאל כמ\"ש צפון וימין אתה בראת, ומזרח ומערב הם קדם ואחור כמ\"ש קדמה מזרחה וא\"כ המערב הוא אחור, וכולם בטלים לאוא\"ס אלופו של עולם כמ\"ש לך ה' הגדולה והגבורה כו'. וכן בחי' ו\"ק גשמים, והיינו כלליות בחי' מקום, וכדכתיב הנה מקום אתי, שהמקום בטל אליו ית', והיינו להיותו בחי' סוכ\"ע שלפניו ית' אינו שייך כלל בחי' מקום וזמן שהם נבראים מאין ליש, והם בבחי' גבול. ויותר אנו רואים זה בזמן<sup data-n=\"224\">25</sup> איך שהזמן הוא מוגבל שהרי אם תתחיל למנות הזמן מעתה ולעתיד א\"א שיהי' בלי",[["222","23","<b>וכן כתיב בו והי' ברכה . . בך חותמין</b>: ראה בארוכה לעיל ח\"א ד\"ה והי' ברכה."],["223","24","<b>ולכן נאמר אחד ולא יחיד</b>: בהבא לקמן ראה בארוכה לעיל ח\"א ע' מב. וש\"נ. וע' קסו-ז. וש\"נ."],["224","25","<b>ויותר אנו רואים זה בזמן</b>: לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב מעיר ע\"ז: צ\"ע מה ראי' מזמן יותר ממקום."]]],[2002180123,"גבול, כ\"א יכול לספור ולמנות מספר מרובה כמו נו\"ן אלפים יובלות שהם מספר גדול וזמן מרובה אבל איננו בלי גבול כ\"א הוא גבול רק שהוא מספר גדול, וכן מעתה ולעבר הוא ג\"כ בבחי' גבול, אבל גבול לגבי בלי גבול ה\"ה אין ערוך כלל, שיום אחד לגבי אלף שנים ה\"ה בבחי' ערך, אבל גבול היותר גדול כמו נו\"ן אלפים יובלות לגבי בלי גבול אינו בערך כלל. ושרש בחי' זמן ומקום נמשך מבחי' מלכותו ית'<sup data-n=\"225\">26</sup> כמ\"ש מלכותך כל עולמים וממשלתך בכל דור ודור, עולמים הוא בחי' מקום, ודור דור הוא בחי' זמן, ושניהם הם מבחי' מל' שהוא מה שמלך שמו נק' עליהם בחי' התפשטות זיו והארה להיות שמו נק' עליו. ושרש הזמן הם מבחי' ששה מדות דז\"א שנק' בשם סדר זמנים, וכמארז\"ל ברבות מלמד שהי' סדר זמנים קודם לכן, ועמ\"ש מזה בד\"ה מי זאת הנשקפה<sup data-n=\"226\">27</sup> בענין המן שהי' דבר יום ביומו.\n<b>וכאשר</b> יתבונן היטב בזה ויהיו נקבעים בלבו באמת אזי לא יחפוץ כלל חפץ אחר זולתו ית', כמ\"ש מי לי בשמים תענוגים רוחני', ועמך לא חפצתי בארץ הם תענוגים גשמיים<sup data-n=\"227\">28</sup> שהם הכל בבחי' זמן ומקום שהם מוגבל, שהרי אפי' השגות שמשיגים בג\"ע ה\"ה בבחי' הגבלה כי מאחר שהוא השגה ה\"ה מוגבל, וכן אפי' עוה\"ב שהרי ארז\"ל כל אחד נכוה מחופתו של חבירו<sup data-n=\"228\">29</sup>, שזהו מדריגות מחולקות א\"כ ה\"ה בבחי' הגבלה כו', ואי לזאת כלה שארי ולבבי, להיות בבחי' צור לבבי וחלקי אלקים לעולם בבחי' נצחית לדבקה בו ית' לבדו שבחי' מקום אתי היינו בחי' שלמעלה מזמן ומקום, שבחי' זמן ומקום אין ערוך לך כלל.\n<b>וזהו</b> דכתיב באברהם הלוך ונסוע הנגבה, ופי' בזח\"א פ' לך דפ\"ד ע\"א נגבה הוא שירותא דעלמא עילאה, סתימא עמיקא לעילא עד אין סוף, והיינו כי נגבה הוא בחי' חסד, ושרש התהוות העולמות הוא מבחי' חסד כמ\"ש כי אמרתי עולם חסד יבנה, פי' יבנה יש בו ב' פירושים<sup data-n=\"229\">30</sup> הא' כפשוטו שבנין העולם הוא מהחסד כנ\"ל, שהוא ראשית המדות, וגם פי' יבנה ששרש בחי' החסד הוא מבחי' יבנה אותיות בינה, אשר בחי' בינה היא למעלה מבחי' עולם, וכמארז\"ל תשובה קדמה לעולם, והוא מפני כי תשובה הוא בחי' תשוב ה' עילאה לגבי יו\"ד, לכן התשובה קדמה למעלת העולם כו', והיינו כי בינה היא למעלה מבחי' מקום וזמן, וכמ\"ש בד\"ה מי זאת הנ\"ל בפי' הראשון, ולכן מי ברא אלה שמבחי' מי בינה נברא בחי' אלה הוא בחי' ו\"ק דז\"א, וע\"ש שז\"ע מי שברא יומו ברא פרנסתו, שמבחי' מי שהוא למעלה מבחי' זמן בא ונמשך בבחי' זמן רק שבא דבר יום ביומו כו'.",[["225","26","<b>ושרש בחי' זמן ומקום נמשך מבחי' מלכותו ית'</b>: ראה שעהיוה\"א פ\"ז. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381119\" data-slug=\"likkutei-torah\" data-id=\"4001381119\">לקו\"ת ברכה צח, א</a>. ובכ\"מ."],["226","27","<b>ועמ\"ש מזה בד\"ה מי זאת הנשקפה</b>: תרל\"ט, לעיל ע' שצו-ז. וש\"נ."],["227","28","<b>בארץ הם תענוגים גשמיים</b>: ראה מ\"ש ע\"ז לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב. וש\"נ."],["228","29","<b>השגות שמשיגים בג\"ע . . הגבלה . . כל אחד נכוה מחופתו של חבירו</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370152\" data-slug=\"torah-or\" data-id=\"3901370152\">תו\"א מקץ לב, ד</a>."],["229","30","<b>עולם חסד יבנה . . יש בו ב' פירושים</b>: ראה יהל אור להצ\"צ ע' שיד. סה\"מ תרכ\"ז ע' קמ. תרכ\"ט ע' עג. תרל\"ד ע' נד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381028\" data-slug=\"likkutei-torah\" data-id=\"4001381028\">לקו\"ת האזינו עו, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381176\" data-slug=\"likkutei-torah\" data-id=\"4001381176\">שה\"ש יא, ד</a>. ועוד."]]],[2002180124,"<b>והנה</b> כמו שמלמעלמ\"ט היינו מבחי' בינה, שקדמה לעולם בחי' מקום וכן קדמה גם לסדר זמנים, בא ונמשך לבחי' זמן ע\"י בחי' החסד, כן בחי' ההעלאה מבחי' זמן ומקום לבחי' שלמעלה מזמן ומקום הוא ג\"כ ע\"י בחי' החסד, וזהו שהי' אברהם הלוך ונסוע הנגבה להיות כי כל תשוקתו הי' ליכלל וליבטל באוא\"ס שלמעלה מזמן ומקום, ולכן הי' הליכתו הנגבה בחי' חסד שהוא שירותא דעלמא עילאה הוא הבינה, שבחי' החסד מקבל מבינה הן מלמעלמ\"ט והן מלמטלמ\"ע, ולכן כל הליכתו הי' הנגבה שע\"י החסד יבוא לדבקה בו באוא\"ס שלמעלה מזמן ומקום שזהו בבחי' עלמא עילאה שבה גילוי אוא\"ס כנ\"ל בשם הזח\"א דפ\"ד ע\"א הנ\"ל.\n<span data-k=\"ks\"><b>קיצור.</b> ואהבת ל' אבה שיהי' רצון לאלקות, והמדות תלוי' ברצון שהוא פנימיות המדות, והדרך לבוא לרצון זה זהו ע\"י ההתבוננות בפסוק שמע כו' אחד ז\"ר וארץ ד' רוחות העולם בטלים לאלופו ש\"ע, והיינו איך שמקום אתי, שהמקום וזמן בטלים, כי אין ערוך כלל בחי' גבול לגבי בחי' בבע\"ג, ואי לזאת כלה שארי ולבבי להיות צור לבבי וחלקי אלקים, לעולם בבחי' הנצחיות, וז\"ע הלוך ונסוע הנגבה חסד שירותא דעלמא עילאה בינה שקדמה לעולם שלמעלה גם מבחי' סדר זמנים כו'.</span>\nה) <b>והנה</b> כ\"ז הוא מעלת בחי' אאע\"ה<sup data-n=\"230\">31</sup>, שאהבה זו נק' בשם אהבת עולם פי' שנלקחה מבחי' ההתבוננות איך שהעולם הוא בחי' זמן ומקום הנם בטלים אליו ית', ובחי' זו היא מלמטלמ\"ע שהוא בחי' הלוך ונסוע מלמטלמ\"ע כו'.\n<b>ואמנם</b> בחי' ומדריגת אהרן הוא מלמעלמ\"ט שאהרן הי' שושבינא דמטרוניתא בבחי' מלמעלה למטה, והיינו שכל חפצו ורצונו הי' להיות נגלה כבוד ה' לעיני כל בשר, והיינו שיומשך ויתגלה בחי' שלמעלה מזמן ומקום למטה בבחי' זמן ומקום, וע\"ד כמו שהי' בבהמק\"ד שראו בחי' ביטול המקום, שהרי מקום הארון אינו מן המדה, והגם שהארון הי' מחזיק אמתים וחצי עכ\"ז עשרים אמה דקדש הקדשים היו עשר אמות מכאן ועשר אמות מכאן, ולא הי' ב' אמות וחצי של הארון תופסים מקום כלל בדופן קה\"ק, והיינו מפני שהאיר שם מבחי' שלמעלה ממקום<sup data-n=\"231\">32</sup>, ולכן הי' המקום בטל כמ\"ש הנה מקום אתי. ועד\"ז יובן בבחי' הזמן ע\"ד שארז\"ל שהראה הקב\"ה לאדה\"ר דור דור ודורשיו, דור כו', שהראה לו כל אריכות הזמן דשית אלפי שני בזמן קצר, שזהו ג\"כ בחי' הארת מלמעלה מן הזמן בבחי' זמן, והי' הזמן בטל. וע\"ד בחי' ביטול שר של אש ושר של מים כמ\"ש המשל ופחד עמו עושה שלום שאם היות שמיכאל שר של מים וגבריאל שר של אש עכ\"ז כשמאיר עליהם הארה היותר",[["230","31","<b>והנה כ\"ז הוא מעלת בחי' אאע\"ה</b>: בהבא לקמן בפרק זה ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380430\" data-slug=\"likkutei-torah\" data-id=\"4001380430\">לקו\"ת בהעלותך שם ל, א</a>."],["231","32","<b>מקום הארון אינו מן המדה . . הי' מחזיק אמתים וחצי . . מבחי' שלמעלה ממקום</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830257\" data-slug=\"or-hatorah-hb\" data-id=\"8158830257\">אוה\"ת נשא ע' רנז</a>-ח. סה\"מ תרמ\"ו-נו\"ן ע' עדר. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111326\" data-slug=\"likkutei-sichot\" data-id=\"1300111326\">לקו\"ש חי\"א ע' 319</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151186\" data-slug=\"likkutei-sichot\" data-id=\"1300151186\">חט\"ו ע' 186</a>. ועוד."]]],[2002180125,"גבוה<sup data-n=\"232\">33</sup> מהם הם בטלים בתכלית ואינם מכבים זא\"ז כאילו אינם הפכים כלל. ועד\"ז יובן בזמן ומקום כשמאיר בהם הארה מבחי' שלמעלה מזמן ומקום, אז הזמן ומקום בטלים כו'. ועד\"ז מצינו בתורה דכתיב ולא קם עוד נביא כמשה, שלכאורה הי' צ\"ל ולא יקום לשון להבא ולמה אמר ולא קם שמשמעו לשון עבר, שהכוונה הוא שלא יקום להבא ג\"כ, אלא מפני שבתורה מאיר בחי' שלמעלה מן הזמן ששם הוא עבר ועתיד שניהם כאחד. ועד\"ז יובן ענין בחי' אהרן להמשיך בחי' שלמעלה מן הזמן ומקום בזמן ומקום להיות כי אהרן הי' בחי' רב חסד, וכנודע דאית חסד ואית חסד<sup data-n=\"233\">34</sup>, אית חסד דאקרי חסד עולם שהוא בחי' חסד דלבר, ואית חסד דאקרי רב חסד שהוא בחי' חסד דלגאו, ולהיותו מבחי' רב חסד לכן הי' יכול להמשיך מבחי' שלמעלה מזמן ומקום שיומשך בבחי' זמן ומקום כו', כי כל הגבוה ביותר יוכל להשפיל יותר. וזהו דכתיב אשר עין בעין נראה כו' שיש ב' בחי' עין והיינו בחי' עין דיחו\"ע ועין דיחו\"ת, ועין בעין היינו בחי' עין דיחו\"ע בעין דיחו\"ת, והיינו כשם שלמעלה הוא בחי' כולא קמי' כלא, שזהו בחי' ד\"ע ויחו\"ע כן גם למטה בבחי' ד\"ת ויחו\"ת יהי' ג\"כ מושג איך שבאמת כלא חשיב, וזהו נראה אתה, נראה הוא אהרן שאהרן ממשיך זו כו'.\n<b>ואהבה</b> זו באה ע\"י אותו ההתבוננות עצמה דאהבה דאברהם, רק שישים מרירות בנפשו על בחי' החשך וההסתר שמעלים ומסתיר על אור קדושת האלקות שלא יהי' נראה לעיני בשר כ\"א בבחי' ההתלבשות דזמן ומקום שהם רחוקים מאור פניו ית' דלית מח' תפיסא בי' כלל, ובחי' זמן ומקום אינו שייך אלא בבחי' מלכותו ית' לבד, אבל מאוא\"ס ב\"ה עצומ\"ה ה\"ה רחוקים בתכלית, ואי לזאת יתמרמר נפשו מאד כאשר ישים אל לבו ריחוקו והירידה שירדה נפשו פלאים בשפל המדריגות רחוק מה' בתכלית, מוגבל ברצונות הזמן כו', ועי\"ז יצעק אל ה' בצר לו, להיות גם כי אשב בחשך ה' אור לו שיאיר החשך והמסך מבדיל. וזהו שארז\"ל אין מוסרין רזי תורה אלא למי שלבו דואג בקרבו, והיינו שלבו דואג על ריחוקו והמסך והחשך שבבחי' זמן ומקום, וע\"י שלבו דואג על הנ\"ל עי\"ז מוסרין לו רזי תורה שהוא בחי' גילוי אוא\"ס שבתורה, וכנ\"ל בענין לא קם שבתורה הוא למעלה מן הזמן כו', וכן הוא למעלה מן המקום ולכן כל העוסק בתורת עולה<sup data-n=\"234\">35</sup> כאילו הקריב עולה הגם שאינו במקום המקדש, להיות יש בתורה בחי' שלמעלה מזמן ומקום כו'.\n<span data-k=\"ks\"><b>קיצור.</b> מעלת אהרן היא מלמעלמ\"ט, היינו מלמעלה מזמן ומקום בזמן ומקום, ע\"ד מקום הארון אינו מן המדה, וע\"ד שבזמן קצר הראה הקב\"ה לאדה\"ר</span>",[["232","33","<b>עושה שלום . . שמיכאל שר של מים . . של אש . . הארה היותר גבוה</b>: ראה אגה\"ק סי\"ב (קיז, א). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380174\" data-slug=\"likkutei-torah\" data-id=\"4001380174\">לקו\"ת תזריע כג, רע\"ג</a>. סה\"מ תרל\"ג ח\"ב תקלה [ובהנסמן שם]."],["233","34","<b>וכנודע דאית חסד ואית חסד</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370366\" data-slug=\"torah-or\" data-id=\"3901370366\">תו\"א תצוה פב, סע\"א</a> ואילך. וראה גם אגה\"ק ס\"י (קיד, ב ואילך). סה\"מ תרכ\"ז ע' קצח ואילך. [ובהנסמן שם בתחילת המאמר]."],["234","35","<b>שבתורה הוא למעלה מן הזמן . . כל העוסק בתורת עולה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380360\" data-slug=\"likkutei-torah\" data-id=\"4001380360\">לקו\"ת במדבר יג, א</a>. סה\"מ תרכ\"ז ע' שלו. ובכ\"מ."]]],[2002180126,"<b></b><span data-k=\"ks\">הנהגת הזמן דשית אלפי שני, וע\"ד ולא קם דכתיב בתורה, ואהרן רב חסד חסד דלגאו ביכולתו להמשיך להיות עין דיחו\"ע בעין דיחו\"ת, נראה אותיות אהרן, ואהבה היא ע\"י התבוננות אהבה דאברהם רק שיהי' לבו דואג בקרבו על החשך והריחוק ועי\"ז מוסרין לו רזי תורה אור תורה היינו בחי' שלמעלה מזמן ומקום, ולכן העוסק בתורת עולה, וענין ולא קם להיות יש בה מלמעלה מזמן ומקום כו'.</span>"],[2002180127,"<h3>ולהבין שרש ענין ההפרש כו' (ב)</h3>\n<b></b><b>בס\"ד. (ש\"פ שלח, ט\"ל).</b>\n<b></b>ראי' ושמיעה כו' התחלת יחוד העליון כו' תקון חצות כו' גביעים, כפתורים, פרחים - (וא\"ו-יו\"ד)\n[שלח]\nוא\"ו) <b>ולהבין</b> שרש ענין ההפרש למה אהבה דאברהם<sup data-n=\"235\">1</sup> הוא מלמטלמ\"ע להיות עולה ונכלל מבחי' זמן ומקום לבחי' שלמעלה מזמן ומקום, ואהבה דאהרן היא מלמעלמ\"ט, והיינו שיומשך בחי' שלמעלה מזמן ומקום בבחי' זמן ומקום. הענין הוא כנודע שאברהם הי' מרכבה לבחי' חסד דז\"א, והנה בבחי' חסד דז\"א אינו מאיר כ\"א מבחי' מוחין דאימא לבד, וענין ההפרש בין בחי' מוחין דאימא לבחי' מוחין דאבא, זהו ע\"ד ההפרש שבין ראי' לשמיעה שנודע מארז\"ל שאינו דומה שמיעה לראי'<sup data-n=\"236\">2</sup>, והוא מפני ששמיעה היא רק בחי' השגה והבנה מה שמבין בשכלו ומציור הדבר מדברי המספר אבל מהות הדבר לא ראה כלל, ואמנם ענין הראי' הוא שרואה עצם הדבר כמו שהוא, שמה שמצטייר בעיניו הוא מחמת שעצם הדבר מצטייר בבבת עיניו כנ\"ל פ\"ב, ועד\"ז יובן ענין ההפרש שבין מוחין דאימא לבחי' מוחין דאבא, שמוחין דאימא זה\"ע השגה שמשיג את הדבר שזהו כענין שמיעה לבד, אבל מוחין דאבא זהו כדוגמת בחי' ראיית המהות, וכמארז\"ל איזהו חכם הרואה, ולכן נק' החכמים בשם עיני העדה, וכתיב וירא ראשית לו שראשית חכמה הוא בחי' ראי'. ושניהם הם בבחי' המהות, רק שמוחין דאבא זהו בחי' ראיית המהות, ומוחין דאימא זהו רק השגת המהות לבד ולא ראיי' כו'. וענין מה שבחסד דז\"א מאיר בחי' מוחין דאימא זהו מה שמושג בחסד דז\"א בבחי' השגה שיש בחי' אוא\"ס שהוא למעלה מן הזמן ומקום וכדכתיב הנה מקום אתי, וכן בחי' הזמן ששניהם מחודשים מבחי' המל' כנ\"ל פ\"ב ושרש שרשן בחי' סדר זמנים הוא במדות דז\"א, רק שבמוחין דז\"א מושג שיש בחי' באוא\"ס שלמעלה מזמן ומקום ומבחי' סדר זמנים, ואי לזאת חפצו ותשוקתו לעלות וליכלל בבחי' זו שלמעלה מזמן ומקום שז\"ע הלוך ונסוע, עד",[["235","1","<b>וא\"ו) להבין שרש ענין ההפרש למה אהבה דאברהם</b>: מאמר זה הוא המשך להמאמר שלפנ\"ז ד\"ה בהעלותך. לכללות המאמר ראה בהנסמן שם בתחילת המאמר. מאמר זה נדפס ג\"כ ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830003\" data-slug=\"or-hatorah-hb\" data-id=\"8158830003\">אוה\"ת בהעלותך</a> (הוצאת תשנ\"ז) בהוספות ע' 3 ואילך."],["236","2","<b>ע\"ד ההפרש שבין ראי' לשמיעה . . שאינו דומה שמיעה לראי'</b>: בהבא לקמן ראה בארוכה סה\"מ תרכ\"ח ע' יב ואילך. תרכ\"ט ע' רסט. וש\"נ. המשך וככה תרל\"ז פל\"ג (ע' מד-ה). ופנ\"ז (ע' פו-ז). ועוד."]]],[2002180128,"שיעלה ויבא לבחי' עלמא עילאה שהיא בינה ששם מושג מהות האור א\"ס שלמעלה מזמן ומקום, וה\"ז עלייה גדולה שהרי במוחין דז\"א שנמשכין ממוחין דאימא הוא רק מושג שיש בחי' אוא\"ס שלמעלה מזמן ומקום, והרי השגה זו היא רק כמו ע\"ד ידיעת המציאות, והעלייה היא שבא להשיג מהות אוא\"ס שלמעלה מהזמן ומקום, או י\"ל לפי שבינה הוא תרדל\"מ עם החכמה לכן יכול לבוא לבחי' ראי' דחכמה ג\"כ כו'.\n<b>ובחי'</b> עלייה זו דאהבה דאברהם זהו מלמטלמ\"ע מפני שמדרגתו בעצם הוא למטה מבחי' עלמא עילאה וכל חפצו ותשוקתו שהי' הלוך ונסוע מדרגה לדרגא הוא שע\"י בחי' נגבה בחי' חסד דז\"א שהוא שירותא דעלמא עילאה פי' ששם מאירים מוחין דאימא שעי\"ז מושג שיש בחי' אוא\"ס שלמעלה מזמן ומקום, יעלה ויבא לבחי' עלמא עילאה היינו להשיג מהות האוא\"ס שלמעלה מזמן ומקום או גם לבחי' ראי' כנ\"ל. ואמנם אהרן הי' בחי' ורב חסד, ולכן אהרן אותיות נראה שהוא בחי' ראיית המהות דמוחין דאבא שז\"ע בחי' ראיית המהות בבחי' אוא\"ס שלמעלה מזמן ומקום, ולכן אינו שייך כלל בבחי' ומדריגת בחי' אהרן שיהי' לו תשוקה לבוא לבחי' זו שהרי בחי' ומדריגה זו הי' אצלו בבחי' ראיית המהות ממש, וזהו מדריגתו עצמו ששמו מוכח עליו אהרן אותיות נראה, וכמ\"ש במ\"א שהשם מוכרח לומר ששייך להנקרא בשם<sup data-n=\"237\">3</sup> דאל\"כ שהוא רק הסכם לבד מהו גודל החכמה דאדה\"ר שארז\"ל שא' הקב\"ה למלאכים חכמתו גדולה משלכם, וא\"כ שם אהרן מוכרח שהי' אצלו בבחי' ראי', ולכן תשוקתו הי' שיומשך גם למטה בבחי' זמן ומקום בחי' אוא\"ס שלמעלה מזמן ומקום כו'.\n<span data-k=\"ks\"><b>קיצור.</b> שרש ההפרש בין אהבה דאברהם ובין אהבה דאהרן שאברהם הי' מרכבה לחסד דז\"א שמקבל ממוחין דאימא ששם מושג שיש בחי' אוא\"ס שלמעלה מזמן ומקום לכן הי' תשוקתו שיעלה ויבוא לבחי' השגת או ראיית בחי' זו, אבל אהרן אותיות נראה שהי' עצמו בבחי' זו, לכן הי' חפצו שגם בבחי' זמן ומקום יומשך בחי' שלמעלה מזמן ומקום כו'.</span>\nז) <b>אך</b> לכאורה אינו מובן הלא כתיב אחד הי' אברהם, ואיך נת' שמעלת ומדריגת אהרן הוא למעלה מבחי' ומדריגת אברהם. אמנם באמת זהו לפי שאהרן הי' אחר מ\"ת<sup data-n=\"238\">4</sup>, שע\"י מ\"ת נתגלה מה שלא נתגלה לאאע\"ה, והגם שקיים אברהם כה\"ת כולה עד שלא ניתנה, מ\"מ הנה ארז\"ל במד\"ר ע\"פ לריח שמניך טובים כל המצות",[["237","3","<b>וכמ\"ש במ\"א שהשם מוכרח לומר ששייך להנקרא בשם</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380254\" data-slug=\"likkutei-torah\" data-id=\"4001380254\">לקו\"ת בהר מא, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380416\" data-slug=\"likkutei-torah\" data-id=\"4001380416\">נשא כז, א</a>. סה\"מ תרכ\"ט ע' קלו ואילך. וש\"נ."],["238","4","<b>אך לכאורה אינו מובן הלא כתיב אחד הי' אברהם . . זהו לפי שאהרן הי' אחר מ\"ת</b>: בהבא לקמן בפיסקא זו ראה אוה\"ת בהעלותך שם ע' שלח: והמשכיל יבין שלא ומה שאברהם לא הגיע למדריגת אה\"ר דאהרן ח\"ו, כי אדרבה אחד הי' אברהם, אלא זהו כמו שבמ\"ת נמשך הכח לישראל כו' מה שלא זכה לזה אברהם, עיי\"ש עוד. וראה גם שם ע' שנ. ד\"ה בהעלותך בסה\"מ תשמ\"ח ע' 431."]]],[2002180129,"שעשו לפניך האבות ריחות היו, אבל אנו שמן תורק רמ\"ח מ\"ע ושס\"ה ל\"ת, והיינו כי הריח הוא רק הארת הדבר<sup data-n=\"239\">5</sup> ולא עצם אבל ענין שמן תורק הוא עצם הדבר כמו שמריקים מכלי אל כלי שז\"ע המשכה עצמיות שנמשך ע\"י מ\"ת, וזהו דכתיב באברהם וארא אל אברהם כו' באל שדי ושמי הוי' לא נודעתי להם, וידוע ששם הוי' נק' שם העצם אשר בחי' גילוי שם הוי' בבחי' יחוד לא נתגלה להאבות<sup data-n=\"240\">6</sup>, כי נודעתי הוא מל' והאדם ידע המשכה עצמיות, אמנם במ\"ת הי' גילוי שם הוי' כמ\"ש לכן אמור לבנ\"י אני הוי' שע\"י מצרים יזכו למ\"ת שיומשך שם הוי' בבחי' יחוד אלקות בנש\"י, שלכן נק' מ\"ת ביום חתונתו כמ\"ש רז\"ל במשנה סוף תענית, ונק' מתן תורה ל' מתנה שבחי' זו ניתן לנו במתנה כו', ולכן מפני שאהרן הי' אחר מ\"ת והי' כה\"ג ע\"פ מצות התורה הי' יכול להמשיך למעלה מאברהם וא\"כ פי' אחד הי' אברהם קודם מ\"ת, וזהו הי' קודם מ\"ת. או מעלתו גם עכשיו שאחד הי' כפשוטו שהמשיך ע\"י עבודתו בעצמו במס\"נ שהי' הלוך ונסוע, משא\"כ אהרן אם היות שממשיך בחי' הגבוה יותר אך הנה זהו ע\"י מ\"ת שניתן לנו במתנה כו'.\n<b>וביאור</b> הענין יובן ע\"פ משארז\"ל במד\"ר בחקתי<sup data-n=\"241\">7</sup> פל\"ו ע\"פ וזכרתי את בריתי יעקב שאברהם לא ניצול מכבשן האש אלא בשביל יעקב, משל לאחד שהי' עומד ונידון לפני השלטון ויצא דינו לישרף, צפה השלטון באצטרולוגיס שלו וראה שעתיד להוליד בת שתהא נשאת למלך אמר כדאי להנצל בזכות בתו, כך אברהם יצא דינו מלפני נמרוד לישרף, וצפה הקב\"ה שיעקב עתיד לצאת ממנו אמר כדאי הוא להנצל בזכות יעקב, הה\"ד (ישעי' ך\"ט ך\"ב) כה אמר ה' לבית יעקב אשר פדה את אברהם. ולכאורה אינו מובן למה הי' צריך אברהם להנצל בזכות יעקב דוקא, ומהו יתרון מעלת יעקב על אברהם, וגם מהו המשל שעתיד להוליד בת שתהא נשאת למלך. אך הענין הוא דהנה אנו אומרים לפני כל מצוה לשם יחוד קוב\"ה ושכינתי'<sup data-n=\"242\">8</sup>, וצ\"ל מהו ענין ופי' יחוד קובהו\"ש. הענין הוא דהנה שכינתי' הוא מלשון ושכנתי בתוכם, שהוא בחי' מל' שמחיה את העולמות בבחי' התלבשות, וע\"ד כמו שהנשמה מחי' את הגוף כך הקב\"ה מחיה את העולם, והעולם נעשה יש ודבר נפרד, כי ענין המלוכה אינו שייך כ\"א על עם שהוא מל' עוממות שז\"ע נפרדים דוקא, ולכן על בנים להיות כי",[["239","5","<b>לריח שמניך . . המצות שעשו לפניך האבות .ֿ. הריח . . הארת הדבר</b>: בהבא לקמן ראה בארוכה סה\"מ תרכ\"ט ע' רכא. וש\"נ. תרל\"א ע' קסג. וש\"נ."],["240","6","<b>וארא אל אברהם כו' באל שדי . . גילוי שם הוי' בבחי' יחוד לא נתגלה להאבות</b>: ראה בכ\"ז בארוכה לעיל ד\"ה ששים המה מלכות. [ובהנסמן שם]."],["241","7","<b>וביאור הענין יובן ע\"פ משארז\"ל במד\"ר בחקתי</b>: בהבא להלן (עד סוס\"ח) ראה אוה\"ת בהעלותך ע' שלז ואילך."],["242","8","<b>אנו אומרים לפני כל מצוה לשם יחוד קוב\"ה ושכינתי'</b>: כ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380748\" data-slug=\"likkutei-torah\" data-id=\"4001380748\">לקו\"ת ואתחנן ט, סע\"א</a>. דרושים לר\"ה נה, ג. ובהמשך תרס\"ו ע' ג. סה\"מ תרפ\"ד ע' פג. תש\"ב ע27. תש\"י ר\"ע 12. [ובהנסמן ע\"ז במאמרי אדה\"ז פרשיות ח\"ב לע' תקצב]. ועוד. וראה בסוף המפתח ענינים ללקו\"ת מכ\"ק אדמו\"ר זי\"ע אודות ”ביאור מנהגים שאין נוהגים בחב\"ד\". [ובהנסמן שם]. — מנהג חב\"ד בזה נת' בסה\"מ תרנ\"ז ע' קצח. עטר\"ת ע' תקיח. סה\"מ מלוקט ח\"ב ע' פב. לקו\"ש חל\"ט ע' 46. סה\"ש תשנ\"ב ח\"ב ע' 454. ועוד."]]],[2002180130,"הבן נמשך מעצמיות בחי' האב אינו שייך מלוכה, כ\"א על נפרדים דוקא שייך בחי' מלוכה, ובחי' זו המחי' עולמות הנפרדים נק' בשם שכינתי' שהוא בחי' מל' המחי' עולמות הנפרדים בבחי' ממכ\"ע, אמנם פי' וענין קוב\"ה זהו מצד היותו קדוש ומובדל מגדר עולמות וזהו בחי' סוכ\"ע, וענין יחוד קוב\"ה ושכינתי' זהו שיומשך המשכת בחי' סוכ\"ע בבחי' ממכ\"ע, ופי' יחוד ז\"ע המשכת הדעת מלשון והאדם ידע. ושרש הענין הוא דכתיב כי אל דיעות ה', שיש ב' דיעות היינו ב' בחי' דעת ד\"ע וד\"ת<sup data-n=\"243\">9</sup>, ד\"ת הוא שנברא מאין ליש, שלמטה הוא היש ונברא מאין, וד\"ע הוא מלמעלמ\"ט, שלמעלה הוא היש, ולמטה הוא אין שכולא קמי' כלא ממש חשיב, ובחי' היחוד הוא בחי' המשכת הדעת מבחי' ד\"ע בבחי' ד\"ת, שגם בבחי' ד\"ת יומשך להיות מושג כמו שהוא בד\"ע איך שקמי' כלא ממש חשיב, וז\"ע יחוד קוב\"ה ושכינתי' שגם בבחי' שכינתי' ד\"ת יומשך הגילוי מבחי' ד\"ע בחי' סוכ\"ע.\n<b>והנה</b> בחי' יחוד זה התחיל מיעקב<sup data-n=\"244\">10</sup>, דכתיב שמאלו תחת לראשי וימינו תחבקני, שאברהם הי' בחי' ימינו תחבקני, ויצחק הי' בבחי' שמאלו תחת לראשו, שכ\"ז הוא בחי' מקיף שזהו רק הכנת היחוד, אבל כדי שיומשך למטה בבחי' פנימיות ממש שנק' בשם יחוד, יחוד זה התחיל מיעקב, לפי שיעקב הוא אותיות יבקע וכמ\"ש אז יבקע כשחר אורך, שיעקב התחיל לבקוע החשך כמו שאור השחר בוקע חושך הלילה, כי יעקב הוא בחי' קו האמצעי, והגם שאברהם התחיל ג\"כ להאיר למטה והי' משגר שם שמים בפי כל הבריות, וכמ\"ש ויקרא בשם ה' אל עולם, וכתיב וארא אל אברהם, שהאיר גילוי אלקות להאבות, והם שגרו בפי הבריות כנ\"ל, עכ\"ז הנה הגילוי הי' ע\"י בחי' שם שדי, אבל שמי הוי' לא נודעתי להם, ומ\"מ מיעקב התחיל להיות התגלות שם הוי' ולכן העמיד י\"ב שבטים, שי\"ב שבטים הם בחי' י\"ב בקר דבריאה, שהם בחי' שבט וענף מן עצם האילן שהוא בחי' יעקב, והיינו להורות שהם ממשיכים המשכה זו בבי\"ע. ועכ\"ז מ\"ש ושמי הוי' לא נודעתי קאי גם על יעקב שלמטה בעוה\"ז לא נודעתי כ\"א ע\"י שעבוד מצרים שנזדככו ע\"י שמררו את חייהם בחמר ובלבנים, וע\"י המרירות וגם שהיו ס' ריבוא ביחד שזהו כמנין שם הוי', כשתחשוב יו\"ד פעמים וא\"ו בכפל חמשה פעמים עולה ת\"ר אלף<sup data-n=\"245\">11</sup> שהם ששים ריבוא, ואז נתגלה שם הוי' במ\"ת שא' אנכי הוי' אלקיך, שלכן נק' מ\"ת ביום חתונתו כמארז\"ל בסוף תענית, שאז הי' גמר היחוד שנמשך יחוד קוב\"ה ושכינתי' שנמשך גילוי שם הוי' למטה במשכן ונודעתי לך שם כו'. והתחלת גילוי שם הוי' בעולמות הרוחנים הי' ע\"י יעקב שהוא התחלת היחוד, וז\"ע יתרון מעלת הנמצא ביעקב לגבי אברהם, שמיעקב התחיל להיות התחלת היחוד דקוב\"ה ושכינתי' שהו\"ע המשכת שם הוי', משא\"כ אברהם ויצחק זהו רק הכנה לבד (ונמצא שאינו סותר למ\"ש",[["243","9","<b>דכתיב כי אל דיעות ה' . . ב' בחי' דעות ד\"ע וד\"ת</b>: ראה בארוכה לעיל ד\"ה מזמור לתודה. וש\"נ."],["244","10","<b>והנה בחי' יחוד זה התחיל מיעקב</b>: בהבא לקמן ראה אוה\"ת בהעלותך שם ע' שלז-ח."],["245","11","<b>כשתחשוב יו\"ד פעמים וא\"ו . . עולה ת\"ר אלף</b>: ראה בפרטיות סה\"מ תרכ\"ו ע' קיב. תרל\"ג ח\"ב ע' שפז-ח. וש\"נ."]]],[2002180131,"בלק\"ת מהאריז\"ל פ' לך לך שהיחוד עליון התחיל מהאבות<sup data-n=\"246\">12</sup>, היינו שאברהם ויצחק עשו הכנה כנ\"ל בפי' שמאלו תחת לראשי וימינו תחבקני, והתחלת היחוד התחיל מיעקב שהתחיל להמשיך שם הוי' ברוחניות העולמות בי\"ע ע\"י שהעמיד י\"ב שבטים שהם כהמשכת השבט מן האילן שיומשך מאצי' לבי\"ע, ועיקר היחוד עליון זהו במ\"ת שאז נתגלה שם הוי' כמ\"ש וירד ה' על ה\"ס, ואמר אנכי ה' אלקיך, ועכ\"פ התחלת היחוד התחיל מיעקב). וזהו המשל שאמר במדרש, שעתיד להוליד בת שתהא נשאת למלך, שקאי על יעקב שע\"י יעקב התחיל להיות בחי' יחוד קוב\"ה ושכינתי' ברוחניות בי\"ע, ולכן אמר לבית יעקב הכוונה על יעקב עם ביתו היינו י\"ב שבטים שהם ההמשכה בבי\"ע כנ\"ל שעי\"ז פדה את אברהם, להיות כי ע\"י יעקב ובניו נמשך התחלת הנשואין שתהא נשאת למלך. וגם י\"ל שמ\"ת נק' ג\"כ ע\"ש יעקב כמ\"ש ויקם עדות ביעקב ותורה שם בישראל, שאז הוא עיקר היחוד.\n<b>ובכ\"ז</b> יובן מה שאהרן ממשיך בחי' עליונה יותר מאברהם הגם שאחד הי' אברהם, מ\"מ הנה אהרן הי' אחר מ\"ת ומצות כהונה היא מצוה ע\"פ התורה. ולכן הוא המשכה היותר גבוה, וגם היא מלמעלה למטה כמו כלליות התורה שהיא בחי' המשכה מלמעלמ\"ט כן אהרן ממשיך בנש\"י מלמעלמ\"ט כו'.\n<span data-k=\"ks\"><b>קיצור.</b> הגם שאברהם קיים כה\"ת מ\"מ ריחות היו, אבל ע\"י מ\"ת ש' הוי' ש' העצם ולכן הגם כי אחד הי', מ\"מ מעלת אהרן שהי' לאחר מ\"ת, וביאור הענין יובן ממ\"ש במד\"ר משל בת שנשאת למלך, כך מיעקב התחיל התחלת הנשואין בחי' המשכת ש' הוי' בעולמות הרוחנים דבי\"ע ולכן בית יעקב אשר פדה את אברהם, ועד\"ז יובן מעלת אהרן שהוא לאחר ביום חתונתו דמ\"ת כו'.</span>\nח) <b>ואמנם</b> הנה כ\"ז הי' בזמן שבהמק\"ד הי' קיים, אבל על חורבן בהמק\"ד כתיב ונהר יחרב ויבש, יחרב בב\"ר ויבש בב\"ש, ולזה תקנו ענין תיקון חצות, שלא די במה שלבו דואג בקרבו שנת' לעיל פ\"ה, כ\"א לקבוע עת מיוחד בחצות<sup data-n=\"247\">13</sup> לעורר מרירות בנפשו, וזהו שאה\"כ על נהרות כו' גם בכינו בזכרינו את ציון, הוא פנימיות ירושלים, שהיא פנימיות נקודת המל' שנק' בצלמנו כנ\"ל בפי' לך ה' הממלכה, ובבהמק\"ד היינו בבית קהק\"ד שם האיר מלמעלה מן המקום, והי' המקום בטל כנ\"ל בענין מקום הארון אינו מן המדה כו', ולכן צריך לבכות על בחי' זו שנחסר מאתנו. וזהו דכתיב היתה לי דמעתי<sup data-n=\"248\">14</sup> לחם יומם ולילה (י\"ל יומם ולילה זהו",[["246","12","<b>בלק\"ת מהאריז\"ל . . שהיחוד עליון התחיל מהאבות</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830016\" data-slug=\"or-hatorah-hb\" data-id=\"8158830016\">אוה\"ת</a> בראשית קכו, א. בהעלותך ס\"ע טז ואילך. שם בהוספות (הוצאת תשנ\"ז) ע' 5 ואילך. פינחס ע' א'קנב. סה\"מ תר\"ל ע' קא. תרל\"ב ח\"ב ע' שנד."],["247","13","<b>ולזה תקנו תיקון חצות . . לקבוע עת מיוחד בחצות</b>: ראה סידור אדה\"ז בהערה לתיקון חצות. (סידור עם דא\"ח קנב, ב. ובשאר סידורים שבהוצאת קה\"ת)."],["248","14","<b>וזהו דכתיב היתה לי דמעתי</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380431\" data-slug=\"likkutei-torah\" data-id=\"4001380431\">לקו\"ת בהעלותך שם ל, ב</a>."]]],[2002180132,"רגע חצות לילה שמחבר יום ולילה, שמחצות הלילה ואילך זהו בחי' חסד ששייך לבחי' חסד אל שמאיר בכל היום כו' ועד חצות לילה זהו גבורה, וזמן חיבורם בחצות לילה זהו יומם ולילה, ולכן אז זמן תיקון חצות לבכות על חורבן בהמק\"ד שאז זמן להוריד דמעות על שאלקיך סליק לעילא ולעילא בבחי' אי\"ה ג\"ר כו') באמור כו' איה אלקיך פי' שהבכי' הוא מפני שאלקיך הוא בבחי' איה, האלף רומז לבחי' כתר, והיו\"ד ה\"א רומז לחו\"ב, והיינו שבחורבן בהמק\"ד קוב\"ה סליק לעילא ולעילא היינו בג\"ר כח\"ב, דכשמאיר אוא\"ס בבחי' מדות אז ממילא נמשך שיהי' למטה ג\"כ בחי' גילוי, אבל כשסליק לעילא ולעילא בבחי' ג\"ר, אז למטה הוא בחי' העלם והסתר. אך הנה העצה לזה הוא בחי' לחמה של תורה, להיות כי ע\"י התורה ממשיכין גם עכשיו גילוי אלקות.\n<b>וז\"ע</b> שאמר במד\"ר שהנרות קיימים לעולם<sup data-n=\"249\">15</sup> גם לאחר החורבן, שהתומ\"צ קרוים נר כמ\"ש כי נר מצוה ותורה אור, ומשחרב בהמק\"ד אין להקב\"ה בעולמו אלא ד' אמות של הלכה, וזה\"ע שהנרות קיימים לעולם, וכמו שע\"י נרות המנורה הי' אהרן ממשיך גילוי אלקות, וכן ענין מראה הנבואה דזכרי' שראה מנורת זהב שנת\"ל פ\"ב שז\"ע בחי' זה דבר ה' שיאיר בחי' זה בבחי' דבר שנק' כה, כן ע\"י התומ\"צ ממשיכים גילוי אלקות להיות בחי' זה הדבר בבחי' דבר ה' זו הלכה.\n<b>וביאור</b> הענין דכתיב כשמן הטוב<sup data-n=\"250\">16</sup> על הראש יורד על הזקן זקן אהרן שיורד ע\"פ מדותיו, פי' זקן אהרן הוא בחי' דקנא דכהנא רבא שבחי' שערות אלו הן הן הלכות שבתורה שנמשלו לשערות כמ\"ש קווצותיו תלתלים שהם תילי תילים של הלכות, שענין בחי' ההילוך של הלכות הן המשכת אלקות שהולך ונמשך מלמעלה למטה ע\"י בחי' הלכות שבתורה שהם כמשל השערות, והשמן הטוב שיורד על השערות הוא בחי' ח\"ע, ועל בחי' שמן הטוב זה נאמר שמן משחת קדש משיחותא דקדש עילאה, והיינו שיש בחי' קדש בלא וא\"ו, ויש בחי' קדוש שהוא בוא\"ו, והנה בבחי' סדר ההשתלשלות א\"א שיומשך מבחי' קדש בלא וא\"ו, כי קדש מילה בגרמי' ואפי' כל ההמשכות שבעולמות עליונים הוא רק מבחי' קדוש בוא\"ו, וג\"ז פי' קדוש הוא מובדל וכנ\"ל בענין הקב\"ה בחי' סוכ\"ע, אמנם בחי' שמן הטוב שיורד על זקן אהרן, ועכשיו זקן אהרן הוא בעבודה הלכות שבתורה, הנה השמן הוא משיחותא דקדש עילאה ממש, והיינו כי בתורה יורד ונמשך מבחי' חכים ולא בחכמה ידיעה שבסדר ההשתלשלות דאצי', שזהו בחי' קדש בלא וא\"ו, והוא היורד ונמשך על השערות הם ההלכות שבתורה, וסיפא דקרא שיורד ע\"פ מדותיו, היינו בחי' מדותיו של הקב\"ה להיות בחי' ואהבת מלמעלמ\"ט ולא כמדת בו\"ד שהם בבחי' צמאון",[["249","15","<b>וז\"ע שאמר במד\"ר שהנרות קיימים לעולם</b>: ראה בהנסמן לעיל רפ\"א הערה ד\"ה: וזהו דוחק ורבינו ז\"ל פי' בא\"א."],["250","16","<b>וביאור הענין דכתיב כשמן הטוב</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380432\" data-slug=\"likkutei-torah\" data-id=\"4001380432\">לקו\"ת בהעלותך שם ל, ג</a> ואילך. וראה גם סה\"מ תרכ\"ז ע' כד. וע' כו. תרל\"ד ע' רד ואילך. [ובהנסמן שם]."]]],[2002180133,"מלמטלמ\"ע כ\"א גילוי אהבה העליונה בחי' אהבתי אתכם אמר ה', ושיהי' נמשך גילוי אלקותו למטה כמו למעלה ע\"י התומ\"צ שהן הן המשכת מדותיו יג\"מ שהתורה נדרשת שהם בחי' יגמה\"ר י\"ג תיקוני דיקנא, ועל בחי' חכ' התורה נאמר ושמן ימינו יקרא שמלביש חסד דא\"א כו'.\n<b>וז\"ע</b> שלך גדולה משלהם שהנרות קיימין לעולם, והיינו שגם בזמן שאין בהמ\"ק קיים, הנה ע\"י התומ\"צ שנק' נר ממשיכים מלמעלה מן הזמן ומקום בבחי' זמן ומקום וכנ\"ל בפי' ולא קם, וכן כל העוסק בתורת עולה כאילו הקריב עולה הגם שאינו במקום המקדש, וגם כשעוסק בתורת סוכה כאילו קיים מצות סוכה גם שלא בזמן הסוכות כו', והיינו מפני שיש בתורה מה שלמעלה מזמן ומקום כו'.\n<span data-k=\"ks\"><b>קיצור.</b> שבזמן שאין בהמק\"ד קיים תיקנו תיקון חצות לקבוע מרירות בנפשו על שנהר יחרב ויבש, להוריד דמעות על מה שאלקיך נסתלק לעילא ולעילא בבחי' אי\"ה ג\"ר כח\"ב, והעצה לזה לחמה של תורה שנק' נר מצוה ותו\"א, וע\"י התומ\"צ נמשך מלמעלה מן הזמן ומקום בבחי' זמן ומקום וזהו שהנרות קיימין לעולם.</span>\nט) <b>והנה</b> במנורה הי' ך\"ב גביעים<sup data-n=\"251\">17</sup>, י\"א כפתורים, ט' פרחים שהם מ\"ב, ועם ז' קני המנורה הם מ\"ט, וכללות המנורה הם נו\"ן, והיינו שרומז לבחי' נשע\"ב. והענין הוא דהנה ידוע ענין הגביעים שיש בחי' כוס ויש בחי' גביע<sup data-n=\"252\">18</sup> וכמ\"ש ביוסף ואת גביעי גביע הכסף, וההפרש שבין כוס לגביע, שהכוס הוא קטן שמקבל מהגביע, שמהגביע מוזגין לתוך הכוס. והענין הוא דכתיב כוס ישועות אשא, כוס הוא בגימ' אלקים, והיין שבתוך הכוס ז\"ע מ\"ש יין המשמח אלקים, כי נכנס יין יצא סוד, שז\"ע בחי' סוד ה' ליריאיו ששם הוי' משמח את שם אלקים, וזהו שא' דוד כוס ישועות אשא שהעלה והגביה את בחי' הכוס דשם אלקים להיות נמשך בו הישועות משם הוי' ע\"ד דכתיב ויושע הוי' שבחי' הישועה נמשך משם הוי' וכדכתיב אנא ה' הושיעה נא, וכן נא' פעמים רבות ה' הושיעה, לה' הישועה, וזהו שסיים ובשם ה' אקרא. אך ביוסף נא' גביע הכסף והיינו שענין הגביע רומז לבחי' תוס' אורות שהוא בחי' המשכת אלקות מלמעלמ\"ט בבחי' כוס שהוא ש' אלקים, וז\"ע שמהגביע מוזגין את הכוס. ועד\"ז יובן ענין הגביעים שבמנורה, שמספר ך\"ב זהו נגד ך\"ב אותיות התורה שהם למעלה מאתווין זעירין דבהבראם בה' זעירא בראם, משא\"כ כל התורה הם אתווין בינונים, וגם יש בחי' אתווין רברבין ולכן נמשלו לגביעים שלמעלה מבחי'",[["251","17","<b>ט) והנה במנורה היה ך\"ב גביעים</b>: בהבא להלן ראה גם אוה\"ת תרומה ס\"ע א'תפה ואילך. א'תצ ואילך. ובאוה\"ת שבהערה הבאה."],["252","18","<b>ידוע ענין הגביעים שיש בחי' כוס ויש בחי' גביע</b>: בהבא לקמן בפיסקא זו ראה בארוכה מאמרי אדה\"ז על פרשיות התורה ח\"א (הוצאת תשמ\"ט) בהוספות ע' 18 ואילך. מאמרי אדהאמ\"צ בראשית ע' רעט ואילך. אוה\"ת בראשית שמא, א ואילך. שמה, סע\"א ואילך. שמז, ב ואילך."]]],[2002180134,"כוס, והיינו שאותיות התורה הם בחי' המשכת אלקות, וע' בד\"ה מי זאת הנשקפה<sup data-n=\"253\">19</sup> שברה\"ע הוא מבחי' את עשית את השמים חסר ה', וע\"י התורה נמשך מבחי' אתה ה' לבדיך, וזהו דכתיב נגילה ונשמחה בך, בך הוא ך\"ב אותיות התורה, וגם בך הוא באוא\"ס עצומ\"ה, והיינו שע\"י התורה נמשך המשכה מעצמיות אוא\"ס.\n<b>וענין</b> י\"א כפתורים דכתיב וכפתור תחת שני הקנים, לפי שבמקום שמתחברים ב' דברים יחד נעשה במקום התחברותן עב יותר, וכמו במקום הקשר שקושרין ב' דברים יחד הוא ג\"כ עב יותר, וז\"ע הכפתור שתחת שני הקנים. וענין התחברות ב' דברים יחד ז\"ע העלאת מ\"ן והמשכת מ\"ד שעי\"ז נעשה יחוד קוב\"ה ושכינתי' שז\"ע התחברות והתקשרות ב' דברים יחד וז\"ע הכפתורים. ומה שמספרם י\"א יובן ע\"פ מה דאיתא בס\"י כרת לו ברית בין עשר אצבעות ידיו ועשר אצבעות רגליו, וברית יחיד מכוון באמצע, והיינו כי עשר אצבעות רומז לע\"ס, וברית יחיד ז\"ע מה שלפני אחד מה אתה סופר שהוא בחי' מה שאנת הוא חד ולא בחושבן, והיינו שע\"י בחי' הכפתורים שהם בחי' העלאת מ\"ן והמשכת מ\"ד ממשיכים מבחי' חד ולא בחושבן שיומשך בבחי' ע\"ס כו'. ט' פרחים ז\"ע בחי' צדיק כתמר יפרח, וכתיב יציץ ופרח ישראל, שז\"ע בחי' התגלות אלקות שיהי' לע\"ל.\n<b>וענין</b> מספר מ\"ב שבין כולם יובן, ע\"פ מה שנודע ממ\"ש במ\"א<sup data-n=\"254\">20</sup> שש' מ\"ב הוא כנגד ך\"ב אותיות התורה, ועשה\"ד וע\"מ, וכתיב עשרה עשרה הכף, שעה\"ד מכוונים כנגד עש\"מ, והיינו שצריכים להמשיך מעשה\"ד בעש\"מ, וז\"ע ב' יודי\"ן שבתמונת אלף שע\"מ הם מש' אלקים של\"ב אלקים נז' בע\"מ שע\"י נברה\"ע שעולם הוא מל' העלם והסתר, וזהו מבחי' יו\"ד התחתון שבאלף היינו בחי' ח\"ת, אמנם עשה\"ד הם מבחי' גבוה מאד, ולכן עשה\"ד מתחיל באלף שהוא אותיות פלא כתר, וע\"ז רומז יו\"ד העליון שבאלף עם קוצו, וצריכים לחבר ב' בחי' אלו והיינו ע\"י ך\"ב אותיות התורה שעי\"ז מחברים הב' יודי\"ן עשרה עשרה שיומשך מעשה\"ד בעש\"מ כו' וזהו שכללותן הם מ\"ב. וזהו שא' דבר ואמרת במנורה לפי שדבר הוא עשה\"ד, ואמרת הוא עש\"מ שע\"י מ\"ב דברים שבמנורה מתחברים יחד<sup data-n=\"255\">21</sup>.\n<span data-k=\"ks\"><b>קיצור.</b> ך\"ב גביעים רומזים לבחי' ההמשכה ע\"י ך\"ב אותיות, י\"א כפתורים ענין הכפתור חיבור מ\"ן ומ\"ד ומספר י\"א שע\"י מ\"ן ומ\"ד ממשיכים מבחי' חד ולא בחושבן בע\"ס, ט' פרחים מה שלע\"ל יציץ ופרח ישראל, ובין כולם מ\"ב ז\"ע</span>",[["253","19","<b>וע' בד\"ה מי זאת הנשקפה</b>: תרל\"ט, נדפס לעיל (ע\"ש בתחילתו)."],["254","20","<b>שנודע ממ\"ש במ\"א ששם מ\"ב הוא כנגד כ\"ב אותיות התורה ועשה\"ד וע\"מ</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830010\" data-slug=\"or-hatorah-hb\" data-id=\"8158830010\">אוה\"ת תרומה ע' א'תפו</a>. א'תצ. מסעי ע' א'שמט ואילך. סה\"מ תרכ\"ז ריש ע' שעג."],["255","21","<b>וזהו שא' דבר ואמרת . . עשה\"ד . . עש\"מ . . מתחברים יחד</b>: ראה לקו\"ת חוקת נז, סע\"ג (בשם הה\"מ). <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460058\" data-slug=\"or-hatorah-hb\" data-id=\"8316460058\">אוה\"ת יתרו ע' תתעג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081002\" data-slug=\"likkutei-sichot\" data-id=\"1300081002\">שם (כרך ח) ע' ב'תתקפד</a>. לקו\"ש ח\"א ע' 148. שיחת ש\"פ מקץ תשי\"ג שם."]]],[2002180135,"<b></b><span data-k=\"ks\">עשה\"ד וע\"מ שמתחברים ע\"י ך\"ב אותיות התורה, ולכן כפל לאמר דבר נגד עשה\"ד ואמרת ע\"מ.</span>\nיו\"ד) <b>אל</b> מול פני המנורה יאירו שבעת הנרות, והענין דהנה ארז\"ל במד\"ר נשא תוך פי\"ב שכל מה שהי' בעולם הי' במשכן<sup data-n=\"256\">22</sup>, בראשית ברא כו' את השמים ובמשכן יריעות המשכן דכתיב נוטה שמים כיריעה, בשני יהי רקיע ויהי מבדיל במשכן והבדילה הפרוכת, בשלישי יקוו המים במשכן הכיור, ברביעי יהי מאורות במשכן המנורה, שהמנורה הי' נגד המאורות, ונמצא פי' מול פני המנורה היינו מאמר יהי מאורות, וא\"כ צ\"ל מהו ענין מה שיאירו ז' נרות המנורה בבחי' מאמר דמאורות שהוא מול בחי' המנורה. אך הענין הוא דהנה בז' ימי בראשית האיר בחי' אור שנברא ביום ראשון שהי' אדם מביט בו מסוף העולם ועד סופו, והקשו מדוע לא אמרו מתחילת העולם<sup data-n=\"257\">23</sup> ועד סופו, אלא שהכוונה במ\"ש מסוף העולם ועד סופו מסוף עלמא דאתכסיא מלמטלמ\"ע שהוא תחילת עלמא דאתכסיא מלמעלמ\"ט, ועד סופו עלמא דאתגלי', ונמצא שהי' אדם מביט בו בשני עולמות עלמא דאתכסיא ועלמא דאתגלי', ראה שאין העולם כדאי להשתמש בו עמד וגנזו, והיכן גנזו גנזו בתורה, ונת' לעיל שמה שהנרות קיימים לעולם ז\"ע נר מצוה ותורה אור שהתומ\"צ נק' נר, וא\"כ ז' קני המנורה ז\"ע בחי' ז' ספרי תורה שספר במדבר נחלק לג' ספרים עד ויהי בנסוע הארון, וב' פסוקים של ויהי בנסוע הוא ספר בפ\"ע, ומן ויהי העם הוא ג\"כ ספר בפ\"ע וזהו ז' ספרי תורה בחי' חצבה עמודי' שבעה שהם נגד ז' נרות המנורה, וע\"י נרות המנורה יאירו ז' הנרות את בחי' מול פני המנורה היינו בחי' מאמר דיהי מאורות, ע\"ד שארז\"ל גבי שרה שהוסיפה על המאורות, ועד\"ז יובן כאן היינו שיאירו ז' נרות המנורה את בחי' מול פני המנורה היינו בחי' המאמר דיהי מאורות שיומשך בו האור מבחי' אור שנברא ביום ראשון שהי' אדם מביט כו' שזהו הוספה על המאורות דעכשיו שהראי' אינה בערך כלל נגד הראי' שהי' ע\"י הנברא ביום ראשון, וזהו שא' יאירו שבעת הנרות, כי מול פני המנורה זהו מאמר יהי מאורות כנ\"ל.\n<span data-k=\"ks\"><b>קיצור.</b> מול פני המנורה הוא מאמר יהי מאורות, ומול מאמר זה יאירו שבעת נרות המנורה בחי' ז' ספרי תורה שיאיר בחי' אור שנברא ביום ראשון שגנזו בתורה במאורות, וע\"ד שרה שהוסיפה על המאורות במד\"ר פנ\"ג.</span>",[["256","22","<b>אל מול פני המנורה . . שכל מה שהי' בעולם הי' במשכן</b>: בהבא לקמן בפרק זה ראה בארוכה סה\"מ תר\"ל ע' קסז ואילך. תרל\"ד ע' רכו ואילך [ובהנסמן שם]. תרס\"ד ע' רכ ואילך. עטר\"ת ע' תעג ואילך. ה'ש\"ת ס\"ע 126 ואילך. סה\"מ מלוקט ח\"ג ע' קפה."],["257","23","<b>אור שנברא ביום ראשון . . מסוף העולם . . והקשו מדוע לא אמרו מתחילת העולם</b>: ראה בכ\"ז סה\"מ תרכ\"ו ע' צו. תר\"ל ס\"ע קמא-ב. ועוד."]]],[2002180136,"<h3>ובראשי חדשיכים כו' (א)</h3>\n<b></b><b>בס\"ד. (ש\"פ קרח, ט\"ל).</b>\n<b></b>עולות וחטאות כו' אין לך עשב כו' כהן חלב ודם - (פרק: א-ג)\nקרח, א' דר\"ח תמוז\n<b>ובראשי</b> חדשיכם<sup data-n=\"258\">1</sup> תקריבו עולה כו' כבשים בני שנה כו', ושעיר עזים אחד לחטאת לה', וארז\"ל (חולין פא\"ט ד\"ס ע\"ב) מה נשתנה שעיר ר\"ח שנאמר לחטאת לה', משא\"כ בשאר החטאות שאינו נאמר לה' כ\"א לחטאת סתם, אמר הקב\"ה שעיר זה יהי' עלי כפרה על שמיעטתי את הירח, וצ\"ל מהו שייך למעלה לשון וענין חטא עד שאומר שעיר זה יהי' עלי כפרה. הנה בקרבנות הי' שני בחי' עולות וחטאות, והנה בד\"כ העולות היו מכבשים כמו תמידין שהיו עולות וכמ\"ש עולת תמיד כו' היו מכבשים וכמ\"ש את הכבש אחד תעשה בבקר כו' וכן בשבת הקריבו ב' כבשים והיו ג\"כ עולות, וקרבן חטאת הי' ע\"פ רוב מעזים כמ\"ש ושעירי עזים לחטאת רק שחטאת כהן המשוח הי' פר וכן פר יוהכ\"פ, וחטאת יחיד לפעמים הי' כבשה אחת כו'.\n<b>ולהבין</b> כ\"ז נקדים תחלה ענין הקרבן, הנה כתיב את קרבני לחמי לאשי שהקרבנות שמקריבים חלב ודם ע\"ג המזבח נק' בחי' לחם למעלה<sup data-n=\"259\">2</sup>, לבחי' האישים עליונים, שהם השרפים שנק' אש ע\"ש הרשפי אש, ונק' שרפים ע\"ש שנתוקדו כבר ע\"י הרשפי אש כו', וכמו\"כ הם נק' אישים ג\"כ ע\"ש זה כו'. וע' מזה בד\"ה אם כסף תלוה את עמי<sup data-n=\"260\">3</sup>, וזהו שארז\"ל רעייתי פרנסתי ישראל מפרנסין לאביהם שבשמים, ולכאורה אינו מובן איך שייך לומר שע\"י הקרבנות יהי' בחי' לחם למעלה, וגם מה צריכים ללחם הלא משה כשהי' בהר ארבעים יום כתי' בי' לחם לא אכלתי ומים לא שתיתי, כי אזלת לקרתא עבדית כנמוסיה (מד\"ר תשא פמ\"ז), וכ\"ש המלאכים אישים עליונים, וכ\"ש שאינו מובן ענין רעייתי פרנסתי ישראל מפרנסין לאביהם שבשמים.\n<b>ויובן</b> בהקדם שורש ומקור בחי' הצומח, דהנה ארז\"ל אין לך עשב מלמטה שאין לו מזל מלמעלה המכה בו ואומר גדל, שכל עשב פרטי יש לו שרש ומקור",[["258","1","<b>ובראשי חדשיכם</b>: תוכן המאמר נמצא ג\"כ בסה\"מ תרכ\"ט ע' קה ואילך [ד\"ה שה תמים]. וכאן המאמר הוא עם הוספות. וראה גם תוכן המאמר בתוס' ביאור בד\"ה ובראשי חדשיכם, איזהו גבור — תרצ\"ה. ד\"ה ע\"כ יאמרו המושלים, איזהו גבור — תרצ\"ו [סה\"מ תרצ\"ו ע' 116 ואילך]. ד\"ה החודש הזה — תשכ\"ט. וראה בארוכה ד\"ה וזאת תורת זבח השלמים, בסה\"מ תרכ\"ט ע' קכט.\nתוכן המאמר נמצא ג\"כ בס' הנחות ממאמרי כ\"ק אדמו\"ר הצ\"צ מס' 466 קעב, א. המאמר נמצא ג\"כ לקמן בהנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע."],["259","2","<b>ולהבין כ\"ז . . הנה כתיב את קרבני לחמי . . בחי' לחם למעלה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380624\" data-slug=\"likkutei-torah\" data-id=\"4001380624\">לקו\"ת פינחס עו, א</a>. סידור עם דא\"ח לו, א. אוה\"ת פינחס ע' א'עב ואילך. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121018\" data-slug=\"likkutei-sichot\" data-id=\"1300121018\">לקו\"ש חי\"ב ע' 18</a> [ובהמ\"מ שם]."],["260","3","<b>וע' מזה בד\"ה אם כסף תלוה את עמי</b>: סה\"מ תרכ\"ז ע' קלה. תרכ\"ט ע' סט ואילך. וש\"נ."]]],[2002180137,"למעלה השופע בו חיות להחיותו ולהצמיחו, וכנודע ממ\"ש בזהר בראשית די\"ח ע\"פ מצמיח חציר לבהמה ועשב לעבודת האדם שחציר ועשב הם שני בחי' מלאכים<sup data-n=\"261\">4</sup> שיש מלאכים שהם עומדים משי\"ב ואומרים שירה וכמו מיכאל וגבריאל שמחנה מיכאל באהבה משי\"ב, ומחנה גבריאל ביראה<sup data-n=\"262\">5</sup> ג\"כ משי\"ב הם חיים וקיימים באהוי\"ר, והם הנק' בשם עשב, ויש מלאכים שנק' בשם חציר, והיינו שכמו החציר קוצרים אותה ומצמחת עוד הפעם, כמו\"כ מלאכים אלו נבראים בכ\"י ואומרים שירה ונכללים בבחי' הביטול, וחוזרים ונבראים מלאכים ואומרים ג\"כ שירה ונכללים בבחי' הביטול וכמ\"ש חדשים לבקרים, וה\"ז כמשל החציר שצומח במהירות ונקצר וחוזר וצומח. וזהו שאנו אומרים בברכת יוצר אור, יוצר משרתים ואשר משרתיו, יוצר משרתים הם המלאכים שנבראים בכ\"י ואומרים שירה ונכללים בבחי' הביטול כנ\"ל, ואשר משרתיו הם המלאכים שנק' בשם עשב שעומדים ברום עולם משי\"ב, ואומרים שירה באהוי\"ר.\n<b>וזהו</b> ועשב לעבודת האדם שהם מלאכים שמעלים תפלות ישראל, וכמ\"ש בזהר הנ\"ל שעשב הם המלאכים שנק' אופנים חיות וכרובים, ופי' המק\"מ בשם האריז\"ל אופנים בעשי' חיות ביצי' וכרובים בבריאה, כי מט\"ט וסנד\"ל הם זו\"נ דבריאה עכ\"ל. ונודע ממארז\"ל שמט\"ט (סנדל) קושר כתרים לקונו<sup data-n=\"263\">6</sup> מתפלותיהם של ישראל, וזהו ועשב לעבודת האדם שהם מעלים התפלות וכמ\"ש בת\"א בד\"ה מזוזה מימין<sup data-n=\"264\">7</sup> שבכדי להיות כתרים לקונו מתפלותיהם של ישראל שהם גשמי' זהו ע\"י המלאכים שמזככי' האותיות כי הדבור שלהם הוא בערך דקות המחשבה שלנו<sup data-n=\"265\">8</sup> וגבוה מעל גבוה עד משכן מלאך מט\"ט (או סנדל) שקושר כתרים לקונו מתפלותיהם של ישראל, כי כשעוברים על ידם מזדככים האותיות, וכמ\"ש בזהר דגפיף להון ומנשק להון ועי\"ז מזדככי' האותיות מגשמיותם להיות יכול להיות מהם כתרים לקונו כו' היינו בחי' יהי רצון<sup data-n=\"266\">9</sup> שיומשך רצון חדש לרפאות החולה ולברך השנים להיות בחי' ברכה בתוס' וריבוי וכמ\"ש ביצחק ויזרע יצחק כו' וימצא מאה שערים שזהו יותר מכמו שצומח ע\"פ דרכי הטבע שנמשך מבחי' הצמצומים דשם אלקים, כמ\"ש מזה בד\"ה זאת חקת התורה (ך\"ט)<sup data-n=\"267\">10</sup>, וע\"ז נאמר ויברכהו הוי' שזהו הנק' ברכה להיות בבחי' תוס' וריבוי כו' וידוע שתוספתו של הקב\"ה מרובה על העיקר כו', ובחי' ברכה",[["261","4","<b>ויובן בהקדם שורש ומקור בחי' הצומח . . שני בחי' מלאכים</b>: בהבא לקמן (עד פיסקא: ”וכמו שהוא בצומח\") ראה אוה\"ת בראשית לג, סע\"ב ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370129\" data-slug=\"torah-or\" data-id=\"3901370129\">תו\"א וישב כז, סע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380230\" data-slug=\"likkutei-torah\" data-id=\"4001380230\">לקו\"ת אמור לו, א</a>. פינחס עט, סע\"ב ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560364\" data-slug=\"or-hatorah-hb\" data-id=\"8316560364\">האזינו עו, ד</a>. סידור עם דא\"ח סב, ב. פט, ד. רכז, ד. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450607\" data-slug=\"or-hatorah-hb\" data-id=\"8316450607\">אוה\"ת נח (כרך ג</a>) תרמח, ב ואילך. ביאוה\"ז להצ\"צ (כרך ב) ע' תרז. סה\"מ תרס\"א ע' רו ואילך."],["262","5","<b>שמחנה מיכאל באהבה . . ומחנה גבריאל ביראה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380353\" data-slug=\"likkutei-torah\" data-id=\"4001380353\">לקו\"ת במדבר יא, ב</a>. ובכ\"מ."],["263","6","<b>ונודע ממארז\"ל שמט\"ט (סנד\"ל) קושר כתרים לקונו</b>: ראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 202."],["264","7","<b>וכמ\"ש בת\"א בד\"ה מזוזה מימין</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">תו\"א מב, ב</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940108\" data-slug=\"or-hatorah-hb\" data-id=\"8159940108\">אוה\"ת תזריע (כרך ב) ס\"ע תקכד</a>-ה. סה\"מ תרל\"ה ח\"א ע' רז ואילך."],["265","8","<b>כי הדבור שלהם הוא כערך דקות המחשבה שלנו</b>: ראה לקו\"ת הוספות לס' ויקרא נג, ריש ע\"ב. סידור עם דא\"ח רעו, א. ובכ\"מ."],["266","9","<b>היינו בחי' יהי רצון</b>: בסה\"מ תרצ\"ו שם ע' 123 נוסף: דהנה כתר הוא בחי' רצון."],["267","10","<b>כמ\"ש מזה בד\"ה זאת חוקת התורה (ך\"ט)</b>: סה\"מ תרכ\"ט ע' צג ואילך."]]],[2002180138,"זו נמשך מבחי' שם הוי' שלמעלה מבחי' ש' אלקים כמ\"ש מזה ג\"כ בד\"ה זאת חקת הנ\"ל יעו\"ש, וכדי שיומשך הברכה זהו ע\"י העלאת המלאכים שמעלים התפלה שלנו שאנו מתפללים ומבקשים בברכת ברך עלינו כו' ותן ברכה, וברך שנתינו כו', וע\"י העלאה זו נמשך הברכה, ולכן נאמר ועשב לעבודת האדם.\n<b>ועל</b> בחי' דשא ועשב אלו ארז\"ל אין לך עשב מלמטה<sup data-n=\"268\">11</sup> שאין לו מזל מלמעלה המכה בו ואומר לו גדל, דאם היות שלמעלה בחי' דשא ועשב הם בחי' ומדרגות גבוהות עכ\"ז ברבבות מדרגות השתלשלות נעשו למטה חיות צומח של הדשא והעשב הגשמי להיות בחי' נפש הצומחת של בחי' הדשאים ועשבים אלו הגשמי' (שגופם הגשמי נעשה בדרך בריאה יש מאין מבחי' אוא\"ס הסוכ\"ע כמ\"ש במ\"א בד\"ה ביום השמע\"צ שלא נדפס<sup data-n=\"269\">12</sup>), ובזה יובן מארז\"ל נשאו דשאים ק\"ו בעצמם שלכאורה איך שייך בהם ענין הדבור כו' אלא שקאי על שרשן בבחי' המלאכים שנק' דשא כו' ועכ\"ז הם מקור לנפש הצומח לבד מפני שהעיקר בהם הוא הצמיחה מקטנות לגדלות כמ\"ש מזה במ\"א<sup data-n=\"270\">13</sup>.\n<b>והנה</b> כמו שהוא בצומח כמו\"כ הוא בדומם וחי ומדבר, דהנה ארז\"ל שלשה שותפים באדם<sup data-n=\"271\">14</sup> אב מזריע לובן כו' ואם אודם כו' והקב\"ה נותן בו נשמה<sup data-n=\"272\">15</sup> כמ\"ש כי חלק הוי' עמו, שיש בכאו\"א חלק הוי' ממש, ונמצא שכמו חיות הדשא והעשב הוא מבחי' המזל השופע לו שהם בחי' המלאכים שנק' בשם דשא ועשב, כמו\"כ חלק הוי' עמו שיש בנש\"י בכאו\"א חלק מבחי' שם הוי' כו', וכמו\"כ בבע\"ח הנה גם הבהמה יש לה נפש רק שנפשה נשתלשלה מבחי' פני שור שבמרכבה, וכנודע שד' חיות המרכבה הם שרשי כל הבע\"ח שהארי' הוא מקור וחיות לכל החיות ופני שור הוא מקור וחיות לכל הבהמה ופני נשר מקור חיות כל העופות, והאדם הוא מפני אדם שבמרכבה או בחי' האדם העליון שעל הכסא כמ\"ש מזה במ\"א<sup data-n=\"273\">16</sup>, ולהיות כי נפש הבהמה היא מבחי' פני שור שבמרכבה<sup data-n=\"274\">17</sup> לכן ע\"י שמקריבין הבהמה ע\"ג המזבח והיתה נכללת באש שלמעלה הי' עולה נפשה לשורשה ומקורה",[["268","11","<b>ועל בחי' דשא ועשב אלו ארז\"ל אין לך עשב מלמטה</b>: פיסקא זו (עד: והנה כמו שהוא בצומח) היא בשינויים בסה\"מ תרכ\"ט שם ע' קח-קט (ושם באו ענינים נוספים באריכות הביאור)."],["269","12","<b>כמ\"ש במ\"א בד\"ה ביום השמע\"צ שלא נדפס</b>: ראה אוה\"ת שמע\"צ ע' א'תשעט ואילך."],["270","13","<b>מארז\"ל נשאו דשאים . . שקאי על . . המלאכים . . הצמיחה . . כמ\"ש מזה במ\"א</b>: סה\"מ תרכ\"ט ע' קנח. תרל\"ב ח\"א ע' רעג."],["271","14","<b>והנה כמו שהוא בצומח . . דהנה ארז\"ל שלש שותפים באדם</b>: בכל הבא להלן, ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381243\" data-slug=\"likkutei-torah\" data-id=\"4001381243\">לקו\"ת שה\"ש כח, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381251\" data-slug=\"likkutei-torah\" data-id=\"4001381251\">ל, ג</a> ואילך. אוה\"ת משפטים (כרך ח) ע' ג'יח ואילך."],["272","15","<b>והקב\"ה נותן בו נשמה</b>: בסה\"מ תרצ\"ו שם ע' 125 נוסף: וחלק הקב\"ה הוא חלק משולש וענינו בפנימיות הוא כמ\"ש כי חלק ה' עמו."],["273","16","<b>וכנודע שד' חיות המרכבה הם שרשי כל הבע\"ח . . בחי' אדם העליון שעל הכסא כמ\"ש מזה במ\"א</b>: ראה תניא אגה\"ק סכ\"ח (קמז, ב). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380422\" data-slug=\"likkutei-torah\" data-id=\"4001380422\">לקו\"ת נשא כח, ג</a>. אוה\"ת משפטים שם."],["274","17","<b>ולהיות כי נפש הבהמה היא מבחי' פני שור שבמרכבה</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370316\" data-slug=\"torah-or\" data-id=\"3901370316\">תו\"א יתרו עא, סע\"א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381269\" data-slug=\"likkutei-torah\" data-id=\"4001381269\">לקו\"ת שה\"ש לה, סע\"א</a> ואילך. ובכ\"מ."]]],[2002180139,"הוא בחי' פני שור שבמרכבה, ועי\"ז גרמו להיות החיות נושאות את הכסא עם בחי' אדם שעל הכסא לבחי' כי לא אדם הוא, כי הנה נודע שבחי' אדם הוא בחי' התיקון והבהמות והחיות שרשן מבחי' התהו שקדם לתיקון וע\"י שמעלים הבהמה ששרשה מבחי' התהו עי\"ז עולה ונכללת בבחי' פני שור שבמרכבה ששרשו ג\"כ מבחי' התהו רק הוא ממה שכבר נתברר, ולהיותם מבחי' התהו לכן ביכולת חיות המרכבה להגביה את בחי' האדם דתיקון שעל הכסא לבחי' כי לא אדם הוא כו'.\n<b>והנה</b> ההקרבה הי' ע\"י הכהן איש החסד<sup data-n=\"275\">18</sup> דוקא כי ימין מקרבת כו', לכן כדי לקרב הניצוץ זהו ע\"י הכהן איש החסד כו', וסדר עלייתן הוא שע\"י שנכלל הבהמה באש של מעלה שהו\"ע ארי' דאכיל קרבנין<sup data-n=\"276\">19</sup> שבחי' הארי' ג\"כ בחי' ימין כמ\"ש פני ארי' אל הימין ובחי' ארי' הזה הי' מגביה ניצוץ הבהמה לבחי' פני שור שבמרכבה שזהו במרכבה דיצי' כנודע שהחיות הם ביצי', וכמ\"ש לעיל בשם האריז\"ל, ושרשם הוא בחי' המרכבה דבריאה ששם הם מיכאל וגבריאל כמו ארי' ושור דיצי' ולכן מיכאל הוא ג\"כ כהן כמ\"ש בזהר יתרו דפ\"ז<sup data-n=\"277\">20</sup> אית מלך לתתא ותחותי' אית כהן כו' מיכאל כהנא רבא, והיינו בבחי' בריאה (וע' בביאור מאה\"ז אית מלך לעילא כו' הנ\"ל בספר תקס\"ה<sup data-n=\"278\">21</sup> שמפרש מיכאל כה\"ג על חסד דמל' דאצי' יעו\"ש), ועי\"ז מתעורר גם המרכבה דאצי' כי כמו שיש חיון תתאין כמו\"כ יש חיון עילאין<sup data-n=\"279\">22</sup> והיינו בחי' המדות דאצי' שנק' בשם חיון עילאין והכסא זהו בחי' בינה, וע\"י עליית החיות דבי\"ע עם בחי' הכסא והאדם שעל הכסא דבי\"ע מעוררים עי\"ז עליית חיון עילאין עם הכסא שלהם הוא בחי' בינה שכינתא עילאה ועד\"ז עד רום המעלות וכמ\"ש בזהר שרזא דקורבנא עולה עד רזא דא\"ס, וכמו שהמעלה הבהמה הגשמי הוא הכהן איש החסד כנ\"ל, כמו\"כ למעלה העליות הוא ג\"כ ע\"י הכהן וכנודע ממ\"ש בזהר אית חסד ואית חסד<sup data-n=\"280\">23</sup>, אית חסד דאקרי חסד זוטא ואית חסד דאקרי רב חסד הוא בחי' חסד דא\"א, ועד\"ז יובן בענין הכהנים שלמעלה שבכל בחי' ומדריגה שגבוה יש בחי' כהן, וכמ\"ש בזהר יתרו דפ\"ז אית מלך לעילא וכהן משמש תחותי' ברזא דקה\"ק ואית מלך לתתא וכהן משמש תחותי' רזא דאור קדמאה כו', וע\"י הכהן שמשמש בקה\"ק ע\"י הוא העלי' עד רזא דא\"ס, וכנודע שקדש הוא בחי' חכ' וקה\"ק",[["275","18","<b>והנה ההקרבה הי' ע\"י הכהן איש החסד</b>: בסה\"מ תרכ\"ט שם ניתוספה כאן פיסקא: ובזה יובן ג\"כ איך יתוקן חטא האדם ע\"י הקרבת הבהמה כו'. להבא להלן ראה גם ביאוה\"ז להצ\"צ ח\"א ע' רמב ואילך."],["276","19","<b>שנכלל הבהמה באש של מעלה שהו\"ע ארי' דאכיל קרבנין</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380355\" data-slug=\"likkutei-torah\" data-id=\"4001380355\">לקו\"ת במדבר יא, ד</a>."],["277","20","<b>בזהר יתרו דפ\"ז</b>: צ\"ל דס\"ז."],["278","21","<b>וע' בביאור מאה\"ז </b> [ מאמר הזוהר]<b> אית מלך .ֿ. בספר תקס\"ה</b>: נדפס ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550045\" data-slug=\"torat-chaim\" data-id=\"2300550045\">תו\"ח יתרו</a> (הוצאת תשס\"ג) ח\"ב רעג, ג ואילך. ובארוכה שם רסט, א ואילך. ביאוה\"ז לאדהצ\"צ ח\"א ס\"ע רלח ואילך. ח\"ב ע' תשפג ואילך. המשך תער\"ב ח\"ב ע' תתקעט ואילך. ד\"ה כי תבואו גו' ושבתה תשי\"ג."],["279","22","<b>כי כמו שיש חיון תתאין כמו\"כ יש חיון עילאין</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380171\" data-slug=\"likkutei-torah\" data-id=\"4001380171\">לקו\"ת תזריע כב, ד</a>. ביאוה\"ז לאדהאמ\"צ מב, ב. סב, ב. סידור עם דא\"ח סד, א."],["280","23","<b>וכנודע ממ\"ש בזהר אית חסד ואית חסד</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370366\" data-slug=\"torah-or\" data-id=\"3901370366\">תו\"א תצוה פב, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380509\" data-slug=\"likkutei-torah\" data-id=\"4001380509\">לקו\"ת שלח מט, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380537\" data-slug=\"likkutei-torah\" data-id=\"4001380537\">קרח נה, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381252\" data-slug=\"likkutei-torah\" data-id=\"4001381252\">שה\"ש ל, ד</a>."]]],[2002180140,"הוא כתר<sup data-n=\"281\">24</sup> כו'. וזהו מ\"ש בקרבנות ריח ניחוח להוי', פי' ריח הוא בחי' העלאה, וכמארז\"ל נח\"ר לפני שאמרתי ונעשה רצוני, וע\"י עשי' זו הוא בחי' העלאה לבעל הרצון ועי\"ז נעשה נחוח ל' המשכה מל' נחות דרגא להוי' שיומשך בחי' שם הוי' שהיו\"ד הוא צמצום, והיינו שכדי להיות בחי' שם הוי' זהו ע\"י צמצום בחי' היו\"ד ואח\"כ בחי' ה\"א הוא התפשטות שאחר הצמצום ואח\"כ ו\"ה להיות נמשך הגילוי למטה כו', שגם למטה יומשך המשכת אוא\"ס ב\"ה.\n<b>ועפ\"ז</b> יובן מה שנק' הקרבנות בשם לחם<sup data-n=\"282\">25</sup>, פי' כמו הלחם אנו רואים את פעולתו שכאשר האדם אוכל לחם הנה פעולת הלחם שסועד לבב אנוש שלא יסתלק הנפש מן הגוף, כי אם לא יאכל יחלש מעט מעט עד שיכול ליפרד הנפש מן הגוף וימות ברעב, ועד\"ז יובן למעלה שבחי' כלי המדות עליונות נק' בשם גופין כמ\"ש בת\"ז וכמה גופין תקינת לון, שנק' המדות בשם גופין, וההוא נביעא איהי כנשמתא לגופא דאיהי חיים לגופא, והיינו שכמו שהגוף חי מהנשמה המחי' את הגוף כמו\"כ המדות עליונות הם חיים מהאור של ההיא נביעו דאיהו חיים לבחי' הגופא שלהם, וכד אנת תסתלק מינייהו אשתארו כולא שמהן כגופא בלא נשמתא, וכדי להיות חיבור האורות בכלים זהו ע\"י הקרבנות שלכן נק' בשם לחם, פרנסתי ישראל מפרנסין לאביהם שבשמים<sup data-n=\"283\">26</sup> פי' שמים הם בחי' אש ומים מדות עליונות, ואביהם שבשמים היינו בחי' המוחין שבמדות דז\"א, והיינו שזהו משל כמו הלחם הגשמי מפרנס את האדם להיות חיבור נשמתו בגופו כמו\"כ הלחם דקרבנות הם הפרנסה שישראל מפרנסין לאביהם שבשמים שיהי' חיבור אורות וכלים, וכמ\"ש במד\"ר הן שירעו אותי בשני תמידין כמ\"ש את הכבש אחד תעשה בבקר שלשון מרעה ופרנסה ענינם אחד הוא כו', וזהו ג\"כ מה שהקרבת הבהמה נעשה לחם לבחי' האישים שהם השרפים שנק' אישים ג\"כ כי ע\"י העלאת הקרבן שע\"י החיות המרכבה עי\"ז נעשה נחוח להוי' וממילא נמשך תוס' אור וחיות גם לבחי' בי\"ע כו', וגם עלייתם שהם מעלים הניצוץ זהו ג\"כ חיות שלהם שזה\"ע הרצוא שנעשה להם שעי\"ז הם מעלים את הכסא, והיינו ע\"י שמקבלים לחם הוא בחי' הניצוץ שגורם להם העלי', ונמצא שזהו ג\"כ משל שכמו הלחם מחבר הנשמה עם הגוף כמו\"כ הניצוץ שמתעלה מנפש הבהמה נעשה בחי' לחם להשרפים שיוכלו להיות בבחי' רצוא שזהו החיות שלהם ואח\"כ נעשה שוב הוא כשנמשך בחי' נחוח להוי' נמשך גם בהם השוב שהוא בחי' ההמשכה בכלים מכלים שונים כו'.\n<span data-k=\"ks\"><b>קיצור.</b> הקרבנות נמשלו ללחם לחמי לאשי, כי כמו באדם ג' שותפים, כן בבהמה שרש נפשה מבחי' פני שור שבמרכבה, ע\"ד שכל עשב יש לו מזל למעלה,</span>",[["281","24","<b>וכנודע שקדש הוא בחי' חכ' וקה\"ק הוא כתר</b>: ראה ביאוה\"ז שם ע' רלט."],["282","25","<b>וזהו מ\"ש בקרבנות ריח ניחוח להוי' . . שנק' הקרבנות בשם לחם</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380624\" data-slug=\"likkutei-torah\" data-id=\"4001380624\">לקו\"ת פינחס עו, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380859\" data-slug=\"likkutei-torah\" data-id=\"4001380859\">תצא לה, ג</a>. דרושים לשמע\"צ צב, ד."],["283","26","<b>פרנסתי ישראל מפרנסין לאביהם שבשמים</b>: בסה\"מ תרצ\"ו שם (ע' 128) נוסף: דשמים אש ומים, חסד וגבורה עיקר המדות, ואביהם שבשמים הוא המשכת המוחין."]]],[2002180141,"<b></b><span data-k=\"ks\">והכהן איש החסד מעלה אותה לשרשה פני שור, ועי\"ז החיות נושאות את הכסא עם דמות כמראה אדם לבחי' כי לא אדם דבריאה, ועי\"ז מתעורר בחיון עילאין דז\"א דאצי' והכסא בחי' בינה עם בחי' כמראה אדם חכמה דאצי' שיתעלו ע\"י הכהן דרב חסד להתעלות עד רזא דא\"ס, ועי\"ז נמשך נחוח להוי' שיהי' הצמצום דיו\"ד בחי' אנת הוא חכים, ושיומשך למטה, וזהו כמשל הלחם שכמו הלחם בגשמיות מחבר הנשמה עם הגוף כן הלחם דקרבנות מחבר בחי' אנת הוא נשמתא לגופין דאצי'.</span>\nב) <b>והנה</b> העיקר בהקרבן הי' הקרבת חלב ודם<sup data-n=\"284\">27</sup>, ופי' בזהר חלב ודם בחי' חיור וסומק שהחלב שרשו מחסד והדם שרשו מגבורה וע\"י הכהן שהי' מעלה חלב ודם הגשמי' בחי' חו\"ג עי\"ז הי' מעורר ההעלאה עד רום המעלות עד חו\"ג היותר עליונים, והעלאה זה גורם המשכה במדות עליונות וכמ\"ש במ\"א בענין הללו את ה' מן השמים<sup data-n=\"285\">28</sup> עי\"ז נמשך הללוהו במרומים ומלאכיו וצבאיו, כי ע\"י העלאת וביטול המדות לאוא\"ס דלאו מכל אינון מדות שז\"ע לך ה' הגדולה כו' עי\"ז נמשך כי כל בשמים ובארץ כל הוא בחי' כלליות מל' אמרו אליו כל תשא עון כתר הכללי<sup data-n=\"286\">29</sup> שיומשך בשמים ובארץ<sup data-n=\"287\">30</sup>, והיינו שיומשך במדות עליוני' מבחי' אוא\"ס שלאו מכל אינון מדות כו', וזהו ענין הקרבן בכלל, הקרבת חלב ודם חו\"ג ורזא דקורבנא עולה עד רזא דא\"ס ומשם הוא בחי' אוא\"ס דלאו מכל אינון [כו'] אשר שם אם צדקת כו' שאינו תופס מקום כלל נמשך לכפר על נפש החוטא כו'.\n<b>ועכשיו</b> שאין לנו קרבנות תיקנו לנו התפלה כנגד תמידים, שתפלה וק\"ש שבכ\"י הם בחי' עולת תמיד, שלכן ארז\"ל כל הקורא ק\"ש בלא תפילין כאלו הקריב עולה בלא מנחה וזבח בלא נסכים נמצא שנק' הק\"ש בשם עולה, שע\"י התבוננות בק\"ש בפסוק ראשון עי\"ז הוא זובח את יצרו להיות ואהבת כו' בכל לבבך וארז\"ל בשני יצריך שגם היצה\"ר ישוב לאהבה את ה' כו', והיינו בחי' הנה\"ב שהיא בחי' רוח הבהמה היורדת למטה בארץ בתענוגים ותאוות גשמיות יהפך להיות רוח האדם עולה למעלה מעלה לה' כעולה וכקרבן שגם נה\"ב שרשה מפני שור רק שזהו",[["284","27","<b>והנה העיקר בהקרבן הי' הקרבת חלב ודם</b>: בהבא לקמן (עד סוף המאמר) ראה בארוכה גם ד\"ה וזאת תורת זבח השלמים, בסה\"מ תרכ\"ט ע' קכב ואילך. וראה גם ד\"ה מלכא ומלכתא שבסה\"מ תר\"ל ע' שנא ואילך. ובסה\"מ תרס\"ד ע' רחצ ואילך. תרצ\"ז ע' 209 ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370138\" data-slug=\"torah-or\" data-id=\"3901370138\">תו\"א וישב כט, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380632\" data-slug=\"likkutei-torah\" data-id=\"4001380632\">לקו\"ת פינחס עח, א</a>-<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381178\" data-slug=\"likkutei-torah\" data-id=\"4001381178\">ב. שה\"ש יב, ב</a>. שערי אורה שער החנוכה יד, ב ואילך. אוה\"ת פינחס ע' א'עא ואילך. שם ע' א'קלב. ביאוה\"ז להצ\"צ (כרך ב) ע' תקצח."],["285","28","<b>וכמ\"ש במ\"א בענין הללו את ה' מן השמים</b>: ראה ד\"ה זה לעיל. וראה גם סה\"מ תרכ\"ט ע' ל. וש\"נ."],["286","29","<b>אמרו אליו כל תשא עון כתר הכללי</b>: בסה\"מ תרכ\"ט שם ע' קכו: ע\"ד שפי' המגיד נ\"ע ע\"פ אמרו אליו כל תשא עון שהוא בחי' מקיף הכללי שכולל ומקיף כל הד' עולמות בשוה. וכן הובא (בשם הה\"מ) לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב מהמאמר. וראה גם לקו\"ת דרושים לש\"ש סז, ד. סה\"מ תרכ\"ז ע' קעג. תרכ\"ט ע' לד. תרל\"ג ח\"ב ע' תקעא. ע' תקעה. ובהמ\"מ בסה\"מ תרכ\"ט ע' קכו שם."],["287","30","<b>כתר הכללי שיומשך בשמים ובארץ</b>: בסה\"מ תרצ\"ו שם נוסף: שנמשך על שמים וארץ בשוה, וכמאמר והקדוש בשמים ובארץ שהוא קדוש ומובדל משמים וארץ ששניהם שוים."]]],[2002180142,"מבחי' פני אדם שבפני שור אבל מ\"מ זהו מבחי' פני שור, ולכן עלייתה שוה ממש לבחי' עליית הקרבן.\n<b>ובאמת</b> י\"ל שגדלה מעלת עליות נה\"ב שבאדם ששרשה מפני אדם שבפני שור, וא\"כ בענין שרשה בתהו הוא ג\"כ מבחי' הגבוה יותר, והגם כי אפ\"ל שנפש הבהמה מאחר שנשפלה להיות נפש לבהמה ולא נה\"ב באדם הרי שרשה מבחי' הגבוה יותר כי כל הגבוה יותר נופל לבחי' נמוכה ביותר<sup data-n=\"288\">31</sup>, כמשל האבנים הגבוהים מן החומה כשנופל הכותל הנה האבנים הגבוהים והעליונים שבראש הכותל נופלים למרחוק יותר, אינו כן שהרי כשאדם ממלא תאוות לבו אפי' בתאוות היתר ה\"ה כבהמה ממש, ועוד גרוע יותר שהרי הבהמה אין לה שכל להבין והאדם יש לו שכל ועכ\"ז עושה מעשה בהמה, ה\"ה גרוע יותר מבהמה, וכ\"ש באיזהו דבר תאוות איסור ח\"ו הרי הוא גרוע הרבה מהבהמה וכמארז\"ל אין אדם עובר עבירה אא\"כ נכנס בו רוח שטות, וע' מזה בד\"ה וידבר משה אל ראשי המטות שלא נדפס<sup data-n=\"289\">32</sup>, וא\"כ כשמעלים נה\"ב שבאדם עלייתו ג\"כ גבוה יותר מנפש הבהמה שהי' מעלים ע\"ג המזבח כו'.\n<b>וכמו</b> שבקרבן הבהמה עיקר ההקרבה הי' חלב ודם כמו\"כ בהקרבת וזביחת הנה\"ב שבאדם עיקר ההקרבה הוא בחי' החלב והדם, כי הנה כתי' כמו חלב ודשן תשבע נפשי, כי החלב באדם שאינו יושב על מקום אחד הנה עיקר גידולו הוא מן התענוג, וצריך להיות התענוג מאלקות והיינו להיות בבחי' אהבה בתענוגים מבחי' ההתבוננות בק\"ש בבחי' אני הוי' לא שניתי ואתה הוא קודם<sup data-n=\"290\">33</sup> שנבה\"ע ואתה הוא לאחר שנבה\"ע בלי שום שינוי כלל וכלל כי כולא קמי' כלא חשיב, וע' בד\"ה זאת חקת (ך\"ט<sup data-n=\"291\">34</sup>) שהגם שהעולם הוא בחי' מציאות מ\"מ הוא כלא חשיב כו' ואין עוד מלבדו, וע' בד\"ה מי כמוכה באלים בענין אין עוד כו'<sup data-n=\"292\">35</sup>, ועי\"ז לא יחפוץ בשום תענוג גשמי כלל ואפי' תענוג רוחני לא יחפוץ כמ\"ש מי לי בשמים ועמך לא חפצתי שלא",[["288","31","<b>כל הגבוה יותר נופל לבחי' נמוכה ביותר</b>: ראה בארוכה אוה\"ת וארא ע' קסב ואילך (ושם ה' משלים לענין זה). שם ע' ריד. וראה גם סה\"מ תרכ\"ט ע' צט. וש\"נ."],["289","32","<b>וע' מזה בד\"ה וידבר אל ראשי המטות שלא נדפס</b>: ראה ד\"ה זה בס' מאמרי אדה\"ז תקס\"ב ח\"א ע' רלח וע' רמג. שם ח\"ב ע' תקא. סה\"מ תקס\"ד ע' קצב. תקס\"ו ע' רצא ואילך. אוה\"ת מטות ע' א'רסג וע' א'שכב ואילך. שם כרך ה' ע' א'תרפב. שם כרך ו' ע' א'תתקנ."],["290","33","<b>וכמו שבקרבן בהמה . . הנה\"ב שבאדם עיקר ההקרבה הוא בחי' החלב ודם</b>: בהבא להלן (עד סוף הפיסקא) ראה מאמרי אדה\"ז הקצרים ע' צב ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370137\" data-slug=\"torah-or\" data-id=\"3901370137\">תו\"א וישב כט, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381178\" data-slug=\"likkutei-torah\" data-id=\"4001381178\">לקו\"ת שה\"ש יב, ב</a>. המשך תרס\"ו ס\"ע קמא-ב. תער\"ב ח\"א ע' תמא. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380633\" data-slug=\"likkutei-torah\" data-id=\"4001380633\">לקו\"ת פינחס עח, ב</a>. סה\"מ תרכ\"ט ע' קיד (ושם ג\"כ הל': כי החלב באדם שאינו יושב על מקום אחד כו'). שם ע' קכט (ושם: כי גידול החלב באדם שאינו מייגע א\"ע בעבודת הגוף)."],["291","34","<b>וע' בד\"ה זאת חקת (ך\"ט)</b>: ראה סה\"מ תרכ\"ט ע' צח ואילך."],["292","35","<b>וע' בד\"ה מי כמוכה באלים בענין אין עוד כו'</b>: סה\"מ תרכ\"ט שם ע' קנה ואילך."]]],[2002180143,"יחפוץ בג\"ע ובעוה\"ב<sup data-n=\"293\">36</sup> כל שהוא עמך היינו אפי' בחי' מקור החיים מקור התענוגים כמ\"ש כי עמך מקו\"ח ג\"כ לא יחפוץ, וזהו כוונת מ\"ש ועמך לא חפצתי אפי' מה שהוא עמך לא חפצתי ג\"כ. כי הנה יש ברצון שני בחי' חפץ ורצון<sup data-n=\"294\">37</sup>, חפץ הוא פנימיות הרצון, ורצון סתם הוא בחי' חיצוניות הרצון, וכמארז\"ל כופין אותו עד שיאמר רוצה אני שזהו ג\"כ רצון הגם כי אינו חפץ בפנימיותו כך מ\"מ זה נק' רצון כו'. והנה הנהגת האדם צ\"ל כל חפצו האמיתי יהי' רק בבחי' א\"ס עצמותו ומהותו ב\"ה, ולא יחפוץ בשום תענוג גשמי, וההנהגה בדברים ההכרחי' לא יהי' בתאוה למלאות נפשו הטבעי' והבהמית כ\"א בדרך כפי' והכרח, וכמארז\"ל כאלו כפאו כו'<sup data-n=\"295\">38</sup>, ואפי' בתענוגים רוחני' לא יהי' ג\"כ פנימיות רצונו בזה כי כל שהוא עמך היינו אפי' בחי' עמך מקו\"ח לא חפצתי וכנ\"ל, ועיקר פנימיות הרצון היא החפץ יהי' בבחי' אוא\"ס בתענוג נפלא וחייו הגשמי' יהי' אצלו בבחי' בע\"כ אתה חי כמו שבע\"כ אתה מת כו' ועיקר חפצו האמיתי' יהי' בבחי' ביטול אמיתי בבחי' אהבה בתענוגים לאלקות כו', וז\"ע הקרבת החלב שבחי' התענוג שלו יקריב להיות רק תענוג בבחי' אוא\"ס ב\"ה כו'. ועד\"ז יובן ענין הקרבת הדם ג\"כ, כי הנה הדם הוא הנפש, והיינו שכל החמימות שבנפשו ובחי' רתיחות הדמים בהבלי עולם ובחי' רשפי אש שבנפשו הבהמית בחמדת עוה\"ז יהפך להיות רשפי אש שלהבת י\"ה בכל יום ע\"י ההתבוננות בק\"ש ותפלה שז\"ע רוח האדם עולה למעלה מעלה כעולת התמיד וזבח דקרבנות כו'.\n<b>וז\"ע</b> ההעלאה שבתפלה, ועי\"ז נעשה אח\"כ המשכה, וכמו בקרבנות הוא בחי' ריח ניחוח להוי' שע\"י העלאת הריח נמשך בחי' נחוח להוי' כמו\"כ ע\"י ההעלאות בחי' חלב ודם שבאדם בק\"ש עי\"ז נמשך בחי' המשכת אלקות הוי' אלקינו שיהי' בבחי' אלקי' שלנו, וכמ\"ש בלק\"ת בסד\"ה כי כארץ תוציא צמחה<sup data-n=\"296\">39</sup> שבש' אלקים אומרים אלקינו שע\"י הצמצום הוא נעשה אלקי' שלנו, וכמו\"כ ע\"י הביטול דק\"ש יהי' נמשך בחי' נחוח להיות שם הוי' ג\"כ אלקינו וכמ\"ש אנכי הוי' אלקיך שנמשך מבחי' אנכי מי שאנכי שהוי' יהי' בבחי' אלקיך אלקים שלך, וכמ\"ש רז\"ל עתידים צדיקים שיקראו על שמו של הקב\"ה<sup data-n=\"297\">40</sup> ופי' רש\"י ז\"ל שיהי' שמם הוי', והיינו ע\"י העבודה בהיום לעשותם כו', ובחי' שם הוי' זה היינו בחי' שם הוי' שהוא בבחי' סוכ\"ע, כי בק\"ש כתיב שני שמות הוי', ה' אלקינו ה' אחד, סוכ\"ע וממכ\"ע<sup data-n=\"298\">41</sup>, פי' ממכ\"ע הוא בחי' סדרי ההשתלשלות שראשית הגילוי הוא בע\"ס דאצי' ואח\"כ נמשך",[["293","36","<b>כמ\"ש מי לי בשמים ועמך לא חפצתי שלא יחפוץ בג\"ע ובעוה\"ב</b>: ראה גם דרמ\"צ שרש מצות התפילה פ\"מ (קלח, א). ובכ\"מ."],["294","37","<b>כי הנה ברצון יש שני בחי' חפץ ורצון</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381244\" data-slug=\"likkutei-torah\" data-id=\"4001381244\">לקו\"ת שה\"ש כח, רע\"ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381264\" data-slug=\"likkutei-torah\" data-id=\"4001381264\">לג, רע\"ד</a>."],["295","38","<b>כ\"א בדרך כפי' והכרח וכמארז\"ל כאלו כפאו כו'</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370417\" data-slug=\"torah-or\" data-id=\"3901370417\">תו\"א מג\"א צב, סע\"ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370420\" data-slug=\"torah-or\" data-id=\"3901370420\">צג, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380493\" data-slug=\"likkutei-torah\" data-id=\"4001380493\">לקו\"ת שלח מה, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380616\" data-slug=\"likkutei-torah\" data-id=\"4001380616\">בלק עד, ג</a>. פינחס עה, ד."],["296","39","<b>וכמ\"ש בלק\"ת בסד\"ה כי כארץ תוציא צמחה</b>: נצבים נג, סע\"ב. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380611\" data-slug=\"likkutei-torah\" data-id=\"4001380611\">לקו\"ת בלק עג, ב</a>. אוה\"ת וארא ע' ריג. דברים (כרך ו) ע' ב'רסג."],["297","40","<b>וכמ\"ש רז\"ל עתידים צדיקים שיקראו על שמו של הקב\"ה</b>: ראה גם סה\"מ תרכ\"ט ע' קג. תר\"ל ע' עא. תרל\"ב ח\"א ע' רב. ח\"ב ע' שנב. שסה. תקנג. תקעז. תר. המשך תער\"ב ח\"ב ע' תתקיא. תש\"ב ס\"ע 74 ואילך. ועוד."],["298","41","<b>כי בק\"ש כתיב שני שמות הוי', ה' אלקינו ה' אחד, סוכ\"ע וממכ\"ע</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381245\" data-slug=\"likkutei-torah\" data-id=\"4001381245\">לקו\"ת שה\"ש שם כט, סע\"א</a>. ובדרושים לר\"ה נט, סע\"א ואילך."]]],[2002180144,"בעולם הנשמות ואח\"כ במלאכים עד שע\"י המזלות נמשך בעוה\"ז הגשמי, שע\"ז ארז\"ל מה הנשמה ממלא את כל הגוף כך הקב\"ה ממלא את כל העולם, פי' שכמו הנשמה שמחי' את הגוף הנה היא מחי' לכל אבר לפי ערכו שאינו דומה החיות שבראש לחיות שברגל, ועד\"ז יובן בענין שהקב\"ה ממלא את כל העולם הוא ג\"כ בכל חד לפום שיעורא דילי' בכל עולם לפי ערכו וזהו בחי' ממכ\"ע, אבל בחי' סוכ\"ע הוא מובדל מגדרי ההשתלשלות ומעלה ומטה שוין לפניו ית' וכמ\"ש השוה ומשוה קטן וגדול, ועל בחי' זו ארז\"ל אל תהי ברכת הדיוט קלה בעיניך<sup data-n=\"299\">42</sup> כי באוא\"ס הסוכ\"ע שוה קטן וגדול ולכן בבחי' זו גם ההדיוט יכול לברך, וכמ\"ש במ\"א בענין לבי ובשרי ירננו אל אל חי<sup data-n=\"300\">43</sup> שגם הלב הגשמי יוכל לרנן בבחי' אל חי כו', היינו להתפעל מבחי' א\"ס ב\"ה עצמותו ומהותו, וב' בחי' אלו ממכ\"ע וסוכ\"ע זהו ב' שמות שבק\"ש ה' אלקינו בחי' סוכ\"ע וה' אחד הוא בחי' ממכ\"ע כי אחד הח' רומז לז\"ר וארץ וד\"ר העולם<sup data-n=\"301\">44</sup> והיינו בחי' ממכ\"ע שאפי' לאחר שנעשה ז\"ר וארץ וד' רוחות מ\"מ הם בטלים לאחד א\"כ זהו ממכ\"ע רק שזהו בחי' הארת סוכ\"ע בממכ\"ע כו', אבל ה' אלקינו הוא בחי' סוכ\"ע הארת אוא\"ס עצמותו ומהותו שלמעלה מגדר עלמין ומשם נמשך להיות אלקינו, וכמ\"ש היכל הוי' המה, שכמו ההיכל הוא דירת המלך כמו\"כ אנחנו בנ\"י הם היכל ה' כו' גילוי בחי' אוא\"ס כמו ניחוח דקרבנות, וכמ\"ש במ\"א בענין ונקדשתי בתוך בנ\"י, ובענין ושכנתי בתוכם<sup data-n=\"302\">45</sup>, בתוך תוך פנימיות נקודת לבב נש\"י כו'. וע\"ז כתיב עולת תמיד העשוי' בהר סיני<sup data-n=\"303\">46</sup>, שהכח לזה להיות יכולים להמשיך בחי' אוא\"ס ב\"ה הסוכ\"ע, היינו שיהי' ביכולת להעלאת מ\"ן ושיומשך בחי' המשכת מ\"ד כזה, זהו מהר סיני שהכח לזה ניתן מהר סיני בשעת מ\"ת שעל כל דבור פרחה נשמתן כמ\"ש נפשי יצאה בדברו ומזה נמשך הכח על בחי' העלאת מ\"ן אח\"כ בק\"ש, והמשכת מ\"ד הוא מבחי' אנכי שאמר במ\"ת שמבחי' אנכי נמשך להיות ה' אלקיך אלקי' שלך כו'.\n<span data-k=\"ks\"><b>קיצור.</b> בקרבן עיקר ההקרבה הוא חלב ודם חו\"ג, וע\"י העלאת חו\"ג לך ה' הגדולה והגבורה, עי\"ז נמשך להיות כל בחי' כלליות בשו\"א, ועכשיו תפילה במקום קרבנות להקריב נה\"ב ששרשה מפני אדם שבפני שור, שכשנמשך אחר תאוות גשמי' ה\"ה גרוע מבהמה שאין לה לב להבין, ולכן עלייתו עוד גבוה יותר, וההקרבה הוא חלב ודם, חלב תענוג להיות בבחי' אהבה בתענוגים, ודם הוא בחי' אהבה ברשפי אש, ועי\"ז נחוח להוי', שהוי' יהי' אלקינו אלקים שלנו, והיינו בחי'</span>",[["299","42","<b>ועל בחי' זו ארז\"ל אל תהי ברכת הדיוט קלה בעיניך</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381244\" data-slug=\"likkutei-torah\" data-id=\"4001381244\">לקו\"ת שה\"ש שם כח, ד</a>. עקב טז, ב."],["300","43","<b>וכמ\"ש במ\"א בענין לבי ובשרי ירננו אל אל חי</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380342\" data-slug=\"likkutei-torah\" data-id=\"4001380342\">לקו\"ת במדבר ח, ג</a> ואילך."],["301","44","<b>כי אחד הח' רומז לז\"ר </b> [ לז' רקיעים]<b> וארץ וד\"ר </b> [ וד' רוחות]<b> העולם</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380173\" data-slug=\"likkutei-torah\" data-id=\"4001380173\">לקו\"ת תזריע כג, ב</a>. סה\"מ תרכ\"ז ע' רכג. תרכ\"ט ע' קנז. קסד. ובכ\"מ."],["302","45","<b>וכמ\"ש במ\"א בענין ונקדשתי בתוך בנ\"י ובענין ושכנתי בתוכם</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380216\" data-slug=\"likkutei-torah\" data-id=\"4001380216\">לקו\"ת אמור לב, ג</a>. פינחס עט, ד. מאמרי אדה\"ז תקס\"ד ע' סה ואילך. תו\"ח שמות תמד, ב. אוה\"ת ויקהל ע' ב'קפה. שם ע' ב'רד. סה\"מ תרל\"ה ח\"א ע' קל."],["303","46","<b>וע\"ז כתיב עולת תמיד העשוי' בהר סיני</b>: ראה אוה\"ת פינחס ע' עא."]]],[2002180145,"<b></b><span data-k=\"ks\">שם הוי' דסוכ\"ע, וז\"ע ב' שמות הוי' שבק\"ש בפסוק ראשון להיות היכל שם הוי' דסוכ\"ע המה, והכח ע\"ז הוא ממ\"ת שעכ\"ד פרחה נשמתן זהו הכח על ההעלאה, ומה שמאנכי נמשך שהוי' יהי' אלקיך זהו ההמשכה נחוח להוי' כו'.</span>\nג) <b>ומעתה</b> צ\"ל למה התמידין שהם עולות היו מכבשים דוקא<sup data-n=\"304\">47</sup> וכנ\"ל שרוב העולות הם מכבשים דוקא. הנה ארז\"ל במד\"ר במדבר פי\"ג דרנ\"ג ד'<sup data-n=\"305\">48</sup> שהוא בדפוס שקלאוו דף מ\"ו ע\"ד, שהקרבנות היו כנגד האבות, פרים בני בקר כנגד אברהם, אלים כנגד יצחק שהוא בחי' אילו של יצחק, כבשים כנגד יעקב כמ\"ש והכשבים הפריד יעקב, ולכן קול הכבשים מורה על רחמים היא מדתו של יעקב להיות ברחמיך הרבים רחם עלינו, והיינו שכדי שיהי' העלאת מ\"ן והמשכת מ\"ד צ\"ל נמשך כח ע\"ז מלמעלה שהגם שנת\"ל שהכח ניתן מהר סיני כו' מ\"מ הרי אנו מברכים נותן התורה לשון הוה<sup data-n=\"306\">49</sup> שכמו שיש יצ\"מ בכ\"י כמו\"כ יש בחי' מ\"ת<sup data-n=\"307\">50</sup>, וכמו שקודם מ\"ת כתיב ואשא אתכם על כנפי נשרים<sup data-n=\"308\">51</sup> בחי' רחמים ועי\"ז ואביא אתכם אלי, כמו\"כ ע\"י בחי' ר\"ר דיעקב נמשך להיות העלאת הקרבנות דאברהם ויצחק, וזהו ליעקב אשר פדה את אברהם<sup data-n=\"309\">52</sup>. ולכן בתפלה קודם ק\"ש אנו אומרים פסוקי רחמים והוא רחום כו', ואנו מבקשים ברחמיך הרבים רחם עלינו, וכן אבינו אב הרחמן המרחם רחם כו' היינו בכדי לעורר בחי' ר\"ר על ירידת הנשמה בגוף ונה\"ב מקום החשך וההעלם עוה\"ז השפל והגשמי, בכדי להיות בחי' ההעלאה בק\"ש שיהי' רוח האדם עולה בבחי' עולת תמיד למעלה מעלה באהבה בתענוגים כנ\"ל שזהו ע\"י בחי' כבשים דיעקב דוקא, בחי' בריח התיכון שמבריח מן הקצה אל הקצה<sup data-n=\"310\">53</sup> קצה העליון בחי' היותר גבוה כו'. ועוד מעלת הכבשים שטבעם הוא בבחי' ביטול יותר משארי הבע\"ח וכמ\"ש כרחל לפני גוזזי', משא\"כ בשור יש בחי' שור נגח<sup data-n=\"311\">54</sup> כו'. ועוי\"ל מעלת הכבשים שיש צמר בעורם שמהצמר עושים לבושים כמ\"ש ומגז כבשים יתחמם, ובעבודה היינו בחי' הלבושים דתומ\"צ שהתורה היא בחי' קווצותיו תלתלים תלי",[["304","47","<b>ומעתה צ\"ל למה התמידין שהם עולות היו מכבשים דוקא</b>: בהבא להלן (באות זה) ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380634\" data-slug=\"likkutei-torah\" data-id=\"4001380634\">לקו\"ת פינחס עח, ג</a>-<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380637\" data-slug=\"likkutei-torah\" data-id=\"4001380637\">ד. עט, ב</a>. אוה\"ת פינחס שם ס\"ע א'קיג ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380240\" data-slug=\"likkutei-torah\" data-id=\"4001380240\">לקו\"ת אמור לח, סע\"ג</a> ואילך. מאמרי אדה\"ז פרשיות ח\"ב ע' תקעט. סה\"מ תרכ\"ט ע' נז."],["305","48","<b>במד\"ר במדבר פי\"ג דרנ\"ג ד'</b>: דפים אלו הם ע\"פ דפוס אמשטרדם ת\"א-ב."],["306","49","<b>נותן התורה לשון הוה</b>: ראה לעיל ד\"ה מי זאת הנשקפה. וש\"נ."],["307","50","<b>שכמו שיש יצ\"מ בכ\"י כמו\"כ יש בחי' מ\"ת</b>: ראה אוה\"ת בראשית (כרך ו) תתרס, א-ב. לקו\"ת דרושים לחה\"ס פא, ג. ובכ\"מ."],["308","51","<b>שקודם מ\"ת כתיב ואשא אתכם על כנפי נשרים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380348\" data-slug=\"likkutei-torah\" data-id=\"4001380348\">לקו\"ת במדבר י, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381035\" data-slug=\"likkutei-torah\" data-id=\"4001381035\">האזינו עח, א</a> ואילך. מאמרי אדהאמ\"צ ויקרא ח\"א ע' כב. סה\"מ תרכ\"ז ע' תעה. תרל\"ג ח\"א ע' רטז."],["309","52","<b>ליעקב אשר פדה את אברהם</b>: כן הוא בכ\"מ בדא\"ח. ובהערת כ\"ק אדמו\"ר זי\"ע לתניא ספל\"ב (מא, ב): בקרא (ישעי' כט, כב): לבית יעקב. ובכמה מדחז\"ל (סנהדרין יט, ב. ועוד) מוכח דהכוונה ליעקב עצמו."],["310","53","<b>דיעקב דוקא, בחי' בריח התיכון שמבריח מן הקצה אל הקצה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310018\" data-slug=\"tanya\" data-id=\"3401310018\">תניא פי\"ג (יט, א</a>). אוה\"ת ויחי שפה, ב. סה\"מ תרל\"ד ע' רסא. וראה בהנסמן עוד במאמר זה בסה\"מ תרכ\"ט ע' קיז."],["311","54","<b>משא\"כ בשור יש בחי' שור נגח</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380234\" data-slug=\"likkutei-torah\" data-id=\"4001380234\">לקו\"ת אמור לז, א</a>-ב."]]],[2002180146,"תלים של הלכות, והוא בחי' ושער רישי' כעמר נקי בחי' צמר, ובחי' המצות זהו מבחי' לבושי' כתלג חיור, וב' בחי' אלו דתומ\"צ מרומז בצמר הכבשים שמגז כבשים יתחמם היינו לבושי' דמצות, וצמר הכבשים הוא בחי' שער רישי' כעמר נקי. ועוי\"ל טעם ד' שכבשים הוא מלשון כובש והיינו בעבודה בחי' כובש את יצרו<sup data-n=\"312\">55</sup> שע\"ז ארז\"ל איזהו גבור הכובש את יצרו שנאמר טוב ארך אפים מגבור, והיינו שע\"י שכובש את יצרו הוא ממשיך מבחי' א\"א בחי' סוכ\"ע והיינו כמו הקרבן כי קרבן בגימ' א\"א<sup data-n=\"313\">56</sup>. וזהו עלה בכבש ופנה לסובב<sup data-n=\"314\">57</sup> שע\"י העליות בבחי' כבש הוא בחי' כובש את יצרו עי\"ז ופנה לסובב הוא בחי' סוכ\"ע. ולכן עולת התמידין וכן רוב העולות הם מכבשים דוקא להיותם ע\"י עלייתם נמשך בחי' סוכ\"ע כו'.\n<span data-k=\"ks\"><b>קיצור.</b> רוב העולות מכבשים, לפי שהכבשים כנגד יעקב, ולכן קולם קול רחמים, שז\"ע התעוררות רחמים על הירידה בכדי שיהי' ההעלאה, וגם טבע הכבשים הם בביטול יותר משאר בע\"ח, וגם צמר הכבשים רומזים לבחי' לבושי' כו' ושער כו' כעמר נקי שהם תומ\"צ, וגם כבשים ל' כובש את יצרו שעי\"ז נמשך מבחי' א\"א, קרבן בגימ' א\"א, עלה ע\"י בחי' הכבשים ועי\"ז פנה לסוכ\"ע, ולכן רוב עולות מכבשים שע\"י עלייתם נמשך מבחי' סוכ\"ע.</span>",[["312","55","<b>שכבשים הוא מלשון . . כובש את יצרו</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380635\" data-slug=\"likkutei-torah\" data-id=\"4001380635\">לקו\"ת פינחס שם עח, ד</a>."],["313","56","<b>כי קרבן בגימ' א\"א</b>: ראה גם סה\"מ תרל\"ב ח\"א ע' קסא."],["314","57","<b>וזהו עלה בכבש ופנה לסובב</b>: ראה גם סה\"מ תקס\"ג ח\"א ע' שעט (בשם הה\"מ). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380635\" data-slug=\"likkutei-torah\" data-id=\"4001380635\">לקו\"ת פינחס עח, ד</a>. ד\"ה בשעה שהקדימו תשי\"ג (נדפס בתורת מנחם כרך ח' ע' 189)."]]],[2002180147,"<h3>[ושעיר עזים אחד] ומעתה כו' (ב)</h3>\n<b></b><b>בס\"ד. (ש\"פ חוקת, ט\"ל).</b>\n<b></b>חטאת ג' פי' כו' ב' המאה\"ג הוי' אלקים כו' כבשים ועזים (ד-וא\"ו)\nחקת\nד) <b>ומעתה</b> צ\"ל מה שהחטאת<sup data-n=\"315\">1</sup> היתה באה ע\"פ הרוב משעירים דוקא חוץ מחטאת יחיד שהי' כבשה, וחטאת הכפורים ופר כהן משוח כו', הנה חטאת יש בו ג' פירושים<sup data-n=\"316\">2</sup> הא' חטאת ל' חטא כמ\"ש לפתח חטאת רובץ והיצה\"ר יש לו ז' שמות ודוד קראו חטאת כמ\"ש וחטאתי נגדי תמיד, הב' חטאת לשון חסרון כמו והייתי אני ובני שלמה חטאים ופירש\"י כלומר חסרים וכמו מ\"ש קולע אל השערה ולא יחטיא מכלל מי שאינו מכוין אל השערה והיינו שחסר מעט נק' חוטא, הג' חטאת כמו",[["315","1","<b>ומעתה צ\"ל מה שהחטאת</b>: מאמר זה הוא המשך להמאמר שלפנ\"ז ד\"ה ובראשי חדשיכם. לכללות המאמר ראה אוה\"ת פינחס ע' א'קעב ואילך. ובאו\"א בסה\"מ תרכ\"ט ס\"ע קיז ואילך. וראה לקמן בהוספות הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה ומתחיל: ושעיר עזים."],["316","2","<b>הנה חטאת יש בו ג' פירושים</b>: בכל הבא להלן — ראה ד\"ה ושעיר עזים אחד לחטאת ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010022\" data-slug=\"or-hatorah-hb\" data-id=\"8159010022\">אוה\"ת פינחס ע' א'קסח</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010064\" data-slug=\"or-hatorah-hb\" data-id=\"8159010064\">וע' א'קפט</a> ואילך. וראה גם אוה\"ת חוקת ע' תשסב."]]],[2002180148,"תחטאני באזוב ואטהר וכמו וחטא את הבית ותרגומו ודכי ית ביתא לשון נקיות ונקיות מביאה לידי טהרה, ולכאורה איך שייך בחטאת לשון חטא וחסרון וגם לשון טהרה ונקיון שהם הפכים ממש, אך חטאת לשון טהרה קאי על קרבן חטאת שמנקה ומטהר את החטא והחסרון. ובתחלה צ\"ל מהו חטאת לשון חסרון למעלה כמ\"ש לחטאת להוי' שהוא משארז\"ל אמר הקב\"ה שעיר זה יהי' עלי כפרה על שמיעטתי את הירח<sup data-n=\"317\">3</sup> והוא חסרון הלבנה כמ\"ש יהי מארת חסר כתיב.\n<b>והענין</b> הוא דהנה כתיב ויעש אלקים את שני המאורות הגדולים את המאור הגדול כו' ואת המאור הקטן, ולכאורה הפסוק סותר עצמו מרישא לסיפא שבתחלה כתיב שני המאורות הגדולים ולבסוף כתיב המאור הגדול כו' ואת המאור הקטן. אך הענין הוא דהנה איתא בזהר שב' שמות הוי' אלקי' נק' שני מאורות הגדולים ששם הוי' נק' אור כמ\"ש ה' אורי וישעי, אתה נרי הוי', ושם אלקים נק' ג\"כ אור ונק' ג\"כ גדול וכמ\"ש גדול הוי' כו' וארז\"ל אימתי הוא גדול כשהוא בעיר אלקינו דוקא, הרי כי אז גם שם אלקים נק' גדול כי קרב לגבי דהינא ואידהין<sup data-n=\"318\">4</sup>, וזהו כשיש יחוד וחיבור שם הוי' בשם אלקים נקראים שני מאורות הגדולים כמ\"ש וידעת היום כו' כי הוי' הוא האלקים כולא חד בלא פרודא כלל, וזהו שני מאורות הגדולים, אבל כשאין שם הוי' מאיר בשם אלקים אז שם הוי' הוא המאור הגדול ושם אלקים הוא המאור הקטן והוא מחמת קטרוג הירח שאמרה א\"א לשני מלכים להשתמש בכתר א' השיב לה לכי ומעטי א\"ע מיעוט הלבנה, ואז את המאור הקטן לממשלת הלילה שהוא מורה על העלם והסתר דגלות הנמשל ללילה, וקוב\"ה בגלותא אסתלק לעילא וזהו מחמת חסרון הלבנה ומיעוט הירח.\n<b>ולהבין</b> זה על לשון החסידות, הנה ארז\"ל אימתי הוא גדול כשהוא בעיר אלקינו פי' עיר הוא מקיבוץ כמה בתים ובתים נעשים מאבנים, והנה אבנים הם אותיות כמ\"ש בס\"י שתי אבנים בונות שתי בתים כו', ונק' בחי' עולם הדבור עליון דבר ה' בשם עיר אלקינו כי הדבור שרשו משם אלקים, ופי' גדול הוי' בעיר אלקינו היינו כשהדבור מאיר בבחי' גילוי בעולמות כמ\"ש לע\"ל ונגלה כבוד הוי' וראו כל בשר כי פי הוי' דיבר, וזהו אימתי הוא גדול (בחי' ש' הוי') כשהוא בעיר אלקינו היינו כשבחי' דבור דבר הוי' מאיר בגילוי, ואז נק' שניהם מאורות הגדולים, אך ע\"י קטרוג הירח מארת חסר חסרון הלבנה שאין הדבור עליון מאיר בגילוי בעולמות כמו שעל זמן חורבן הבית נאמר מי כמוכה באלים הוי' שארז\"ל מי כמוכה באלמי', מרקדים כו' וכבי' כאלם לא יפתח פיו, בחי' נאלמתי דומי' החשיתי, כרחל לפני גוזזי' נאלמה, והוא בחי' גלות השכינה ואז קוב\"ה אסתלק לעילא ואזי נק' שם אלקים בשם מאור הקטן לממשלת הלילה. וזהו ג\"כ ענין ההפרש שבין משה רבינו<sup data-n=\"319\">5</sup> לשאר כל",[["317","3","<b>משארז\"ל אמר הקב\"ה . . כפרה על שמיעטתי את הירח</b>: ראה בכ\"ז בארוכה סה\"מ תרל\"ג ח\"ב ע' רנה ואילך. וש\"נ."],["318","4","<b>קרב לגבי דהינא ואידהין</b>: לשון חז\"ל — שבועות מז, ב."],["319","5","<b>ההפרש שבין משה רבינו לשאר כל הנביאים .ֿ. בזה . . בכה</b>: ראה בכ\"ז לעיל ד\"ה דבר גו' בהעלותך בתחילתו. וש\"נ."]]],[2002180149,"הנביאים, דהנה ארז\"ל משה נתנבא בזה וכל הנביאים נתנבאו בכה, פי' זה אספה\"מ שהוא בחי' גילוי המהות כמ\"ש לע\"ל הנה אלקינו זה, זה הוי' קוינו לו כו' דשם הוי' ושם אלקים שניהם בבחי' זה כמו שני מאורות הגדולים, וגם בקרי\"ס אמרו זה אלי כו', וכך נבואת משה הי' בחי' זה גילוי דיחו\"ע, לכן כתיב וידבר משה אל ראשי המטות כו' זה הדבר שהי' דבר ה' מאיר אצלו בגילוי גמור כמ\"ש וידבר הוי' אל משה. וזהו שאנו אומרים אחר ק\"ש ויציב ונכון כו' הדבר הזה פי' וקאי על מ\"ש קודם בק\"ש הוי' אחד שיהי' מאיר בגילוי גמור איך שאני הוי' לא שניתי והוא אחד בז' רקיעים וארץ וד\"ר העולם שהוא גילוי מקור וגדלות הדבור בבחי' זה. אבל כל הנביאים נתנבאו בכה בכף הדמיון אספשא\"מ כמו מראה הנק' שפיגל שאינם רואים בה הצורה ממש, רק דמות הצורה, והיינו שכמו שאין ערוך מאור הקטן לגבי מאור הגדול, כך כל הנביאים לגבי משה שלהנביאים לא הי' מאיר דבר הוי' דנבואה כ\"כ כמו למשה. וזהו שאנו מבקשים ובנה ירושלים, שע\"י בנין דעיר אלקינו גילוי הדבור תגדל כבוד הוי' ויהי' גדול הוי' בעיר אלקינו.\n<span data-k=\"ks\"><b>קיצור.</b> ג' פי' בתי' חטאת, וענין פי' חסרון למעלה ז\"ע מארת חסר, שני המאוה\"ג זה\"ע ב' שמות הוי' ואלקים ששניהם נק' גדולים כמ\"ש גדול הוי' בעיר אלקינו, וכדפי' בזח\"ג ויקרא מלכא בלא מטרוניתא לאו גדול איקרי, אבל בחורבן בהמק\"ד, שאינו מאיר הדיבור אזי ש' אלקים הוא המאור הקטן, וזהו ההפרש בין נבואת משה שנתנבא בזה זהו כמו שמאיר ה' אלקים וכמו הדבר הזה שקאי על ה' אחד שיהי' מאיר בחי' יחו\"ע, משא\"כ כל הנביאים נתנבאו בכה, כדמותינו בחי' מאוה\"ק, וזהו ובנה ירושלים בנין עולם הדבור כו'.</span>\nה) <b>ולהבין</b> זה בתוס' ביאור<sup data-n=\"320\">6</sup> צ\"ל מ\"ש בסש\"ב פי\"ב בשער היחוד<sup data-n=\"321\">7</sup>, בענין התחלקות מיני נבראים בשינוי הצירופים וחילופים ותמורות האותיות דעש\"מ שמתגלגלים בכ\"א אלפא ביתא דרל\"א שערים פנים ואחור כמו א\"ת ב\"ש ג\"ר ד\"ק, וא\"ל ב\"ם, שהצירופי אותיות דעש\"מ הכתובים בתורה מהם התהוות חיות הנבראים חשובים כללים כמו בריאת שמים וארץ וכדומה שמאיר בהם דבר הוי' בגילוי כמ\"ש לעולם ה' דברך נצב בשמים, אבל פרטי הנבראים אין קץ שאינם כתובים בתורה מקבלים חיותם והתהוותם משינוי הצירופים באופן אחר וחילופים ותמורות כמו בא\"ת ב\"ש, שמא' נעשה תי\"ו ומב' נעשה ש', והנה אין ההארה המאיר באותיות החילופים כמו בת' וש' כמו האור המאיר בא' וב' עצמן כי האלף למשל הוא עצם האור משא\"כ אות התי\"ו שמקבל מאל\"ף אף שמאיר בו האל\"ף אעפ\"כ הוא אות אחר שהוא תי\"ו ולא אל\"ף כו' לכן כל הנבראים היותר תחתונים במעלה ומדרגה מקבלים החיות מהאותיות שבריבוי הצירופים דחילופים ותמורות דתמורות עד נבראים",[["320","6","<b>(ה) ולהבין זה בתוס' ביאור</b>: בהבא להלן ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010032\" data-slug=\"or-hatorah-hb\" data-id=\"8159010032\">אוה\"ת</a> פינחס שם ע' א'קעג ואילך."],["321","7","<b>בסש\"ב פי\"ב בשער היחוד</b>: ראה גם סה\"מ תרכ\"ז ע' שסה."]]],[2002180150,"דעוה\"ז הגשמי' שמקבלים מצרופים היותר אחרונים לכן הם בהעלם והסתר אלקות לגמרי. ואיתא שם בסש\"ב המשל ע\"ז מאור הירח המאיר בלילה שזהו מה שקבלה הירח מהשמש, שאינו בערך ודוגמא לאור השמש המאיר ביום, והיינו כי מפני שהירח אין לה אור בעצם רק מה שמקבלת ההארה מאור השמש, והנה אף שהיא מקבלת האור מהשמש אין ערוך אור המאיר מהירח לגבי אור השמש עצמו עד שאינו נק' כ\"א אור דאור הארה דהארה שמתמעט האור, כך ע\"י ריבוי החילופים ותמורת האותיות דעש\"מ נתמעט ונתצמצם האור שמבחי' דבר הוי' ואינו מאיר בגילוי. כמו\"כ יובן למעלה דקודם הקטרוג של הירח היו הב' שמות הוי' אלקים שני המאורות הגדולים כמ\"ש כי שמש ומגן הוי' אלקים שהי' גילוי אור הוי' ממש ע\"י שם אלקים כמו שהשמש מאיר ע\"י המגן ונרתק, וזהו וידעת היום כו' כי הוי' הוא האלקים כולא חד בלא פרודא, וגדול הוי' בעיר אלקינו, אך אחר הקטרוג אמר לה לכי ומעטי א\"ע זהו כמו המשל משמש וירח המבואר לעיל הגם שהירח מקבל מהשמש האור אך האור דירח נתמעט לכן אין הגילוי דשמש הוי' מאיר בגילוי בדבור שהוא בחי' שם אלקים, והוא בחי' חסרון הלבנה וכמו חילופים ותמורות הנ\"ל. וזהו ועד בחילופי אתוון אחד, פי' כי אחד הוא בחי' גילוי דיחו\"ע בחי' זה הדבר דהיינו כמו הדבור שמאיר בגילוי, אבל ועד הוא בחילופי אתוון שהוא בחי' יחו\"ת שאין האור בגילוי כ\"כ כמו בחילופים ותמורות כנ\"ל. ועד\"ז ארז\"ל פני משה כפני חמה גילוי שמש הוי' בבחי' זה דיחו\"ע, ופני יהושע כפני לבנה שהוא אור הירח כמו שהוא אחר מיעוטה, לכן זקנים שבאותו דור אמרו אוי לאותה בושה ואוי לאותה כלימה, והיינו נגד גילוי שהי' בימי משה שהי' פני חמה דגילוי שמש הוי' (לכן משה לא אמר בשכמל\"ו בתורה).\n<b>והנה</b> אנשי יריחו היו כורכין<sup data-n=\"322\">8</sup> את שמע ויש פי' אחד שלא אמרו בשכמל\"ו שרצו שיהי' נמשך אצלם הביטול דואהבת מבחי' אחד יחו\"ע, אך אין הלכה כמותם, כי הם היו בחי' אנשי יריחו ע\"ש הירח, כי יריחו הי' עיר התמרים וכתיב צדיק כתמר יפרח, שצדיק שהוא בחי' יסוד נק' תמר, והנה תמר בגימ' שמש (שהוא בחי' שם הוי') ויריחו שהוא בחי' ירח הוא עיר התמרים, זהו ע\"ד עיר אלקינו שמאיר גילוי שם הוי' בשם אלקים, וכך יריחו עיר התמרים היינו בחי' יחוד שמשא בסיהרא שהוא בחי' שם הוי' ושם אלקים (וז\"ע הלולב שהוא בחי' כפות תמרים העיקר הוא שיהי' התאומות שלימות כי אם ניטל התאומות פסול, כי זהו רומז על בחי' יחוד דכר ונוקבא כחדא) ולכן אנשי יריחו שהוא בחי' יחוד שמשא וסיהרא ע\"ד כמו שמש ומגן הוי' אלקים לא היו אומרים בשכמל\"ו שהי' מאיר אצלם ע\"ד ביטול דיחו\"ע, אבל אין הלכה כמותם כי לא כל אדם יכול לקבל מבחי' ומדרגה זו כ\"א ע\"י בחי' ועד בחילופי אתוון כו' בחי' יחו\"ת, והוא מחמת מיעוט הירח. וזהו חטאת לשון חסרון הלבנה, עד שמזה נעשה למטה חטאת לשון חטא שהיצה\"ר דוד קרי' חטאת כמ\"ש לפתח חטאת רובץ,",[["322","8","<b>והנה אנשי יריחו היו כורכין</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380688\" data-slug=\"likkutei-torah\" data-id=\"4001380688\">לקו\"ת מסעי צא, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380973\" data-slug=\"likkutei-torah\" data-id=\"4001380973\">ר\"ה סג, ג</a>. לקמן ד\"ה וידבר גו' המטות. וש\"נ."]]],[2002180151,"והוא מחמת חסרון הלבנה למעלה עי\"ז בהשתלשלות למטה ע\"י ריבוי צמצומים נעשה יצה\"ר חטאת לשון חטא.\n<b>ולהבין</b> זה בעבודת האדם למטה<sup data-n=\"323\">9</sup> באדם ב' בחי' הנ\"ל, הנה כתיב וזרעתי את בנ\"י זרע אדם וזרע בהמה, זרע אדם הוא רוח האדם העולה למעלה ע\"י הדעת בק\"ש שהוא לשון התחברות, וזהו וידעת כו' כי הוי' הוא אלקים אין עוד מלבדו כו', וזהו כמו בחי' עולת תמיד דצדיקים, כי הדעת מחבר ראי' ושמיעה כי אינו דומה שמיעה לראי', פי' כי שמיעה הוא ההתבוננות אבל אינו נוגע אל עצמותו בפנימיותו כי שמיעה מרחוק משא\"כ ראי' הוא בחי' ראי' המהות אך ע\"י העמקת הדעת בבחי' שמיעה בחי' ההתבוננות אזי יהי' כאלו רואה ממש וכמו רואין את הנשמע שהדעת מחבר ב' בחי' ראי' ושמיעה כי דעת מזווג או\"א, וכמ\"ש והוי' עליהם יראה גילוי הוי' דחכמה בדבור דשם אלקים וכולא חד, אך זרע בהמה שאין להם דעת כ\"א רק שמיעה מרחוק הוי' נראה לי, יוכל להיות מזה חטאת ל' חסרון והוא בחי' היסח הדעת לכן יוכל להיות בחי' חטא, ואף כי אין זה רק בחי' שוגג כי קרבן חטאת לא הי' בא כ\"א על השוגג, אך גם בחי' שוגג אינו יכול להיות בבחי' זרע אדם שהם מקושרים תמיד לאלקות כמו האבות הן המרכבה ואיך ישכח על אלקות לעשות חטא ואין זה שייך כ\"א על נשמות דזרע בהמה שאין להם דעת והתקשרות כ\"כ לכן יכול להיות בחי' חטא בשוגג מחמת שכחה והיסח הדעת. וזהו משארז\"ל מרובים צרכי עמך ודעתם קצרה<sup data-n=\"324\">10</sup>, כי מחמת קוצר הדעת הוא מרובים צרכי עמך, והיינו כי מחמת קוצר וחסרון הדעת לאלקות נק' זרע בהמה ורוח הבהמה יורדת למטה בריבוי רצונות זרות מפנימיות הלב היפך דועמך לא חפצתי הנ\"ל, ומזה יכול לבוא לבחי' חטאת חטא וחסרון דיצה\"ר כו'. אך יש עוד פי' חטאת ל' טהרה ונקיון וקאי על בחי' קרבן חטאת בחי' תחטאני באזוב ואטהר, והוא ע\"י בחי' התשובה שהוא בחילא יתיר, כי ע\"י וחטאתי נגדי תמיד מזה בא לידי לב נשבר ונדכה אלקים לא תבזה ועי\"ז ממלא החסרון דחטאת גם למעלה. והנה ארז\"ל במקום שבע\"ת עומדין צדיקים גמורים א\"י לעמוד וזהו שבאמת שיש מעלה בחטאת לגבי עולה, ואף שהעולה היתה כולה כליל (זהו רק בענין הקרבת החלב), אך יש מעלה בחטאת שאינה בעולה והוא כי במתן דמים החטאת למעלה יותר מעולה כי העולה הי' טעון שתי מתנות שהם ארבע והיינו במזרחית צפונית ומערבית דרומית שהוא בחי' חיבור י\"ה וחיבור ו\"ה<sup data-n=\"325\">11</sup>, מזרחית צפונית חיבור י\"ה ומערבית דרומית חיבור ו\"ה, כי מזרח יו\"ד בחי' חכמה וצפון בחי' ה' ראשונה בחי' בינה, ומערבית דרומית בחי' חיבור ו\"ה כי דרום בחי' וא\"ו ומערב הוא בחי' ה' אחרונה של שם הוי' והוא בחי' גדול הוי' דחכמה בעיר",[["323","9","<b>ולהבין זה בעבודת האדם למטה</b>: בהבא להלן ראה גם אוה\"ת פינחס שם א'קעד ואילך."],["324","10","<b>וזהו משארז\"ל מרובים צרכי עמך ודעתם קצרה</b>: ברכות כט, ב. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370123\" data-slug=\"torah-or\" data-id=\"3901370123\">תו\"א וישלח כו, ג</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010036\" data-slug=\"or-hatorah-hb\" data-id=\"8159010036\">אוה\"ת</a> פינחס שם ע' א'קעה. המשך מים רבים תרל\"ו בתחילתו. ובכ\"מ."],["325","11","<b>כי העולה הי' טעון שתי מתנות שהם ארבע . . חיבור י\"ה וחיבור ו\"ה</b>: ראה גם אוה\"ת ויצא קפט, ב. ויקרא (כרך ב) ע' תכט ואילך. דרושים לר\"ה ע' א'שכד. סה\"מ תרכ\"ט שם ע' קכ."]]],[2002180152,"אלקינו בבחי' דיבור דשם אלקים, והיינו שההמשכה הוא רק משם הוי' כו' כנ\"ל, אבל כשבא לכלל מיעוט וחטא וחסרון הירח והיינו שפגמו בשם הוי' צריך להמשיך מלמעלה משם הוי' כדי לתקן כל הפגמי', וזהו קרבן חטאת והי' בה ארבע מתנות על ארבע קרנות כנגד ד' אותיות שם הוי', דהיינו ההמשכה הוא מלמעלה משם הוי' בבחי' ד' אותיות שם הוי' כו', ומתחלה הי' בא לקרן דרומית מזרחית שהוא בחי' מקור זריחת השמש<sup data-n=\"326\">12</sup> כמו ממזרח שמש כו', והוא מבחי' קוצו של יו\"ד של שם הוי' והוא בחי' והחכמה מאין תמצא שהוא בחי' כתר וכמו ביוהכ\"פ לפני הוי' תטהרו, ובבחי' זה חטאת גבוה מעולת תמיד דצדיקים וכמעלת הבע\"ת על הצדיקים שבמקום שבע\"ת כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ביאור הענין יובן מענין החילופים ותמורות שנת' בסש\"ב ח\"ב, שנת' שם המשל מאור הלבנה נגד אור השמש וקודם הקטרוג היו ע\"ד שמש ומגן שע\"י המגן דשם אלקים האיר שם הוי', אך ע\"י הקטרוג זהו כענין אור הלבנה שבאמת הוא ג\"כ מהשמש ועכ\"ז אינו בערך כלל, אחד, ועד, פני משה כפני חמה שמש הוי', ולכן אנשי יריחו היו כורכים כו' שרצו שהאהבה יהי' מהתבוננות יחו\"ע דאחד, רק שאין הלכה כמותם שלא כל הרוצה ליטול את השם יטול, יריחו עיר התמרים צדיק כתמר יחוד ה' אלקים, וזהו חטאת חסרון, ובעבודה זרע אדם העולה ע\"י הדעת שמחבר חו\"ג, משא\"כ זרע בהמה יכול להיות היסח הדעת שעי\"ז יכול לבוא לידי חטא בשוגג, משא\"כ האבות הן המרכבה איך ישכח כו', ומ\"מ מקום שבעת\"ש עומדים כו' וזהו מעלת החטאת ל' נקיון על העולה, שבעולה המתנות הם שתיים שהן ארבע מזרחית צפונית י\"ה, מערבית דרומית ו\"ה, אבל החטאת ד' מתנות, ובא לו לקרן קוש\"י, להמשיך מלמעלה מש' הוי' בש' הוי' ולכן מקום שבעת\"ש עומדים צ\"ג אינם יכולים לעמוד כו'.</span>\nוא\"ו) <b>ובזה</b> יובן<sup data-n=\"327\">13</sup> מה שעולת תמיד הי' מכבשים דוקא והחטאת הי' משעירים, כי הנה ארז\"ל מ\"ט עזי מסגי ברישא והדר אימרי כברייתו של עולם ברישא חשוכא והדר נהורא, נמצא שאימרי נק' נהורא והיינו לפי שאימרי הוא בחי' צדיקים ונק' אימרי ע\"ש מ\"ש את ה' האמרת היום כו' וה' האמירך היום כו' שהוא בחי' שבח וחשיבות וכמו שארז\"ל ע\"ז בגמ' ובמדרש אתם עשיתם אותי חטיבה אחת<sup data-n=\"328\">14</sup> בעולם שמע ישראל הוי' אלקינו הוי' אחד אף אני עשיתי אתכם חטיבה אחת בעולם ומי כעמך כישראל גוי אחד בארץ, וכ\"ז הוא בחי' אימרי בחי' צדיקים כו', ועזי הוא בחי' שעירים נק' חשך ברישא חשוכא, בחי' והי' במחשך מעשיהם זו מעשה",[["326","12","<b>ומתחלה הי' בא לקרן דרומית מזרחית שהוא בחי' מקור זריחת השמש</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830219\" data-slug=\"or-hatorah-hb\" data-id=\"8158830219\">אוה\"ת בלק ע' תתקה</a>."],["327","13","<b>ואו) ובזה יובן מה שעולת תמיד הי' מכבשים דוקא . . מ\"ט עזי מסגי ברישא</b>: ראה בכ\"ז גם סה\"מ תרכ\"ט שם ס\"ע קיח ואילך. וס\"ע קכ ואילך."],["328","14","<b>את ה' האמרת . . אתם עשיתם אותי חטיבה אחת</b>: ראה בכ\"ז בארוכה לקמן ד\"ה את ה' האמרת [ובהנסמן שם]."]]],[2002180153,"הרשעים, ויצה\"ר קרי' חטאת בחי' חטא ועון, אך ע\"י קרבן חטאת שהוא בחי' תשו' עילאה מעומקא דלבא אתהפכא מחשוכא דעזי ושעיר לנהורא. והנה יתרון האור הוא מן החשך דוקא כשהחשך עצמו דשעיר נהפך לאור ע\"י בע\"ת בחילא יתיר, והוא בחי' יתרון האור יותר מאור הנמשך ע\"י הכבשים בחי' צדיקים הנ\"ל, וזהו חטאת מל' תחטאני באזוב ואטהר כמו לפני הוי' תטהרו דיוה\"כ, תטהרו בגימ' כתר שהוא למעלה מבחי' אור הוי' דתומ\"צ דאימרי שהוא לבושי' כתלג חיור ושער רישי' כעמר נקי שהוא בחי' צמר כבשים כנ\"ל, אבל ע\"י התשובה דתחטאני באזוב ואטהר, משלג אלבין למעלה מלבושי' דתלג חיור דתו\"מ אלא הוא בחי' לובן העליון דלבנון די\"ג מדה\"ר וכמ\"ש בסש\"ב בשער התשובה פ\"ח<sup data-n=\"329\">15</sup>, שכדי למלאות הפגמים צריך שיומשך מבחי' קש\"י בחי' יגמה\"ר שלמעלה מעלה מש' הוי' והיינו ממזל ונקה מנקה הוא לשבים יעו\"ש.\n<b>וז\"ע</b> שהלבישה רבקה ליעקב את שני עורות גדיי העזים<sup data-n=\"330\">16</sup> על ידיו ועל חלקת צואריו והיו ידיו שעירות כידי עשו אחיו ואמר יצחק ראה ריח בני כריח שדה כו', ופירש\"י והלא אין לך ריח רע יותר משטף העזים אלא מלמד שנכנס עמו ריח ג\"ע. והענין הוא דהנה ע\"י יעקב נתבררו בחי' גדיי עזים וכמ\"ש במדרש דשני גדיי העזים היו כנגד שני שעירים דיוהכ\"פ, ולכן נק' שני גדיי עזים טובים כי לאחר הבירור המה יותר נעלים כי יתרון האור מהחשך דוקא, ולכן כתיב וירח את ריח בגדיו ויברכהו. והענין הוא דהנה ארז\"ל א\"ת בגדיו אלא ריח בוגדיו, והיינו כי ריח בגדיו הוא בחי' ריח דתומ\"צ בחי' לבושי' דתומ\"צ שע\"י צדיקים ובוגדיו הוא בחי' ריח דבע\"ת דמשכין לי' לקוב\"ה בחילא יתיר ע\"י אתכפי' ואתהפכא מחשוכא לנהורא ויתרון אור מתוך החשך כנ\"ל דעזי מסגי ברישא, ברישא חשוכא והדר נהורא, והיינו כשיעקב לבש בגדי עשו גם עורות גדיי העזים הלבישה על ידיו ועל חלקת צואריו הבריר אותם והי' כמו בחי' בע\"ת שהוא בחי' ריח בוגדיו. וזהו שנאמר בחטאת ר\"ח חטאת להוי' כנ\"ל שחטאת לשון חסרון הלבנה מיעוט הירח ואמר הקב\"ה שעיר זה<sup data-n=\"331\">17</sup> יהי' עלי כפרה על שמיעטתי את הירח, ופי' עלי כמו ותתפלל חנה על הוי' שכדי למלאות חסרון הלבנה שהו\"ע ב' שמות הוי' אלקים כנ\"ל צ\"ל הגילוי וההמשכה מלמעלה משם הוי' כמ\"ש ביוהכ\"פ לפני הוי' תטהרו והוא ענין התשובה שכתיב בה ג\"כ שובה ישראל עד הוי' אלקיך דהיינו עד שבחי' הוי' יהי' במדרגת אלקים וממילא ההמשכה מלמעלה משם הוי', והוא שכדי למלאות הפגם צריך להמשיך ממקום גבוה יותר מבחי' על הוי' כנ\"ל. אך עכשיו צ\"ל בחי' עולת תמיד, דאימרי יאה, כי חטאת",[["329","15","<b>בסש\"ב בשער התשובה פ\"ח</b>: הכוונה לאגרת התשובה פ\"ח (צח, א). וראה בהערות כ\"ק אדמו\"ר זי\"ע לס' התניא שנדפסו בהוספות לס' התניא אודות שם הספר וחלקיו."],["330","16","<b>וז\"ע שהלבישה רבקה ליעקב את שני עורות גדיי עזים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680272\" data-slug=\"torat-chaim\" data-id=\"2300680272\">תו\"ח תולדות קנג, ב</a>. סה\"מ תרכ\"ט שם ר\"ע קכ. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010058\" data-slug=\"or-hatorah-hb\" data-id=\"8159010058\">אוה\"ת</a> פינחס שם ס\"ע א'קפו."],["331","17","<b>וא' הקב\"ה שעיר זה יהי' עלי כפרה</b>: ראה גם סה\"מ תרכ\"ט שם ס\"ע קיט. תרל\"ב ח\"א ע' סה. תרל\"ג ח\"א ע' רנה. ח\"ב ע' תסז."]]],[2002180154,"לשון חסרון וחטא, וגם כי חטאת בחי' תשובה הוא לפי שעה, ועולת תמיד צ\"ל בתמידות בחי' צדיקים.\n<span data-k=\"ks\"><b>קיצור.</b> ולכן החטאת רובם משעירי עזים, כי עיזי מסגי ברישא מפני שברישא חשוכא, אמרי צדיקים האמרת, עיזי בעת\"ש, יתרון האור מתוך החשך, משלג אלבין לובן העליון, יגמה\"ר, מנקה הוא לשבים, שני גדיי עזים טובים לאחר הבירור, ריח בוגדיו, שובה עד שהוי' יהי' בבחי' אלקיך, ועכ\"ז תשובה לפי שעה, ואימרי מעלת הצדיקים היא תמיד כו'.</span>"],[2002180155,"<h3>לא הביט און כו' (א)</h3>\n<b></b><b>בס\"ד. (ש\"פ בלק, ט\"ל).</b>\n<b></b>עלו במח' כו' תאיר פניו כו' שבת פנים חדשות (פרק:א-ג)\nבלק\n<b>לא</b> הביט<sup data-n=\"332\">1</sup> און ביעקב ולא ראה עמל בישראל, ה' אלקיו עמו ותרועת מלך בו, הנה כמו שיעקב שלמטה הי' לו ב' שמות יעקב וישראל כן למעלה יש ב' בחי' אלו דיעקב וישראל שהם מדריגות שונות בעבודת ה'<sup data-n=\"333\">2</sup>, והם בחי' עבד ובחי' בן, והיינו כי יעקב הוא בחי' ומדריגת עבד כמ\"ש שמע יעקב עבדי, וכתיב אל תירא עבדי יעקב (ישעי' מ\"ד א\"ב), וישראל נק' בן כמ\"ש בני בכורי ישראל. ובעבודה בנפש האדם ב' בחי' דעבד ובן הם בחי' תורה ותפילה, כי תפילה היא בחי' עבודה כמ\"ש ולעבדו בכל לבבכם, וארז\"ל איזהו עבודה שבלב זו תפילה, שז\"ע בחי' עבודת עבד, וישראל היא מעלת ומדריגת התורה, ולכן בכל [התורה] נא' דבר אל בני ישראל, צו את בני ישראל, ולא אמר דבר או צו אל בני יעקב, מפני שמעלת ומדריגת התורה היא בחי' ישראל, וכמ\"ש ותורה שם בישראל.\n<b>ולהבין</b> זה צ\"ל מ\"ש במגילה שראה יחזקאל (יחזקאל ססי' ב') והיא כתובה פנים ואחור, פי' פנים ואחור פנים קאי על בחי' תורה כמ\"ש חכמת אדם תאיר",[["332","1","<b>לא הביט</b>: מאמר זה (והמאמר שלאחריו) מיוסד על ד\"ה על כן קראו, ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370543\" data-slug=\"torah-or\" data-id=\"3901370543\">תו\"א</a> מג\"א (הוספות) קכב, א. ועם הגהות באוה\"ת מג\"א ע' קצז ואילך. וראה גם שם ע' רכג ואילך. תוכן המאמר נמצא ג\"כ בשינויים ותוס' ביאורים: בד\"ה ע\"כ קראו בספרי ההנחות (של מאמרי אדהצ\"צ): מס' 1063 שכז, א. מס' 1077 צב, א (בגוכי\"ק אדמו\"ר מהר\"ש). ובדף שיח, א. כת\"י מס' 466 קנ, א (ד\"ה לא הביט). ד\"ה ע\"כ קראו בסה\"מ תרל\"ה ח\"א ע' קמו ואילך. ד\"ה שמע אלי יעקב עבדי בסה\"מ תרס\"ג ח\"ב ע' שלד ואילך. ד\"ה וידבר גו' במדב\"ס וד\"ה ועשית חג שבועות וד\"ה כי מראש צורים וד\"ה תתן אמת בהמשך תרס\"ו ע' רכח ואילך [בכ\"מ שם הוא לשון המאמר כאן בתוס' הגהות]. ד\"ה וקבל היהודים בסה\"מ תרע\"ח ע' קצו ואילך.\nמאמר זה נמצא ג\"כ לקמן בהנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע. וראה בהנסמן עוד לקמן בריש ס\"ו."],["333","2","<b>דיעקב וישראל שהם מדריגות שונות בעבודת ה'</b>: בהבא לקמן ראה ד\"ה לא הביט ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380600\" data-slug=\"likkutei-torah\" data-id=\"4001380600\">לקו\"ת בלק ע, ג</a> ואילך."]]],[2002180156,"פניו, ופי' רז\"ל במד\"ר קהלת ריש פ' ח' חכמת אדם קאי על הקב\"ה, דכתיב ואשמע קול אדם בין אולי (דניאל ח' ט\"ז) וכתיב ועל דמות הכסא דמות כמראה אדם (יחזקאל א' כ\"ו) ולכאורה אינו מובן איך שייך לומר בחי' כמראה אדם על הקב\"ה, הלא אין לו דמות הגוף ולא גוף, וכן צ\"ל במ\"ש נעשה אדם בצלמינו כדמותינו האיך יתכן לומר שהאדם נברא בצלם ודמות שלמעלה הלא אין לו דמות הגוף ולא גוף כו'.\n<b>אך</b> הענין הוא דהנה כתיב כי לא מחשבותי מחשבותיכם<sup data-n=\"334\">3</sup>, ולכאורה צ\"ל ענין אומרו שלא מחשבותי מחשבותיכם הלא עפ\"ע<sup data-n=\"335\">4</sup> גם דבורו אינו שוה לדבור האדם, ולמה על המחשבה דוקא אמר שלא מחשבותי מחשבותיכם. ויובן ע\"פ מארז\"ל בגמ' ובמד\"ר ז' דברים קדמו לעולם תורה ותשובה וג\"ע כו', ומחשבתן של ישראל קדמו לכל דבר, ונת' בכ\"ד פי' דברי אגדה אלו<sup data-n=\"336\">5</sup>, שהעולם נברא מבחי' הדבור כמ\"ש בדבר ה' שמים נעשו, ובעשרה מאמרות נברה\"ע, ואמנם ז' דברים אלו נמשכו מבחי' מחשבה שלמעלה מבחי' דבור, ובתוך בחי' מחשבה זו שקדמה למעלת העולם שנברא בדבור הנה מחשבתן של ישראל קדמו לכל. וזהו כוונת אומרם ז\"ל נש\"י עלו במח', היינו שעלו במח' בבחי' היותר עליונה היינו היותר קדומה כו'. וענין עלו במח' יובן עד\"מ שאנו רואים מי שיש [לו] בן יחיד<sup data-n=\"337\">6</sup> שחביב עליו ביותר ומתגעגע בו, הנה דמות דיוקנו חקוק על לוח לבבו ומוח זכרונו תמיד, ועד\"ז יובן ענין מה שנש\"י עלו בבחי' המחשבה. רק שלמטה אינו כמו למעלה, שלמטה א\"א שיצייר דמות בנו רק אחר שנולד וראה אותו בצלמו ובדמותו, משא\"כ למעלה יתכן ענין עלו במח' גם קודם שנתהוו, ונודע וכמשנת\"ל שהמח' שלמעלה אינו כמו מח' למטה, שלמטה גם כשיחשוב כל היום וכל הלילה לא יתהוה מזה מאומה אבל למעלה תומ\"י כשעלה במח' ענין נש\"י מיד נתהוו. וזהו שאה\"כ כי לא מחשבותי מחשבותיכם, אומרו מחשבותי דוקא, להיות כי מבחי' הדבור שלמטה יכול להיות ג\"כ ההתהוות וכמ\"ש דבר מלך שלטון שכאשר מצוה בדבורו לבד, הציווי גורם שיעשה על ידו, ע\"י מה שמצוה בדבורו, שהגם שלא הדבור לבדו הוא העושה עכ\"ז הדבור גורם עשיית זולתו עכ\"פ, אבל המחשבה שיחשוב שיעשה כן לא תפעול העשייה גם בזולת ג\"כ, משא\"כ למעלה שתיכף שעלה במח' מיד נתהווה, ולכן אמר שלא מח' מחשבותיכם. והגם כי דבורו ג\"כ אינו כדברי הנבראים, שהרי בנבראים הדבור הוא רק גרם המעשה לבד, ולא העושה, משא\"כ למעלה הדבור עצמו הוא העושה, אמנם דבר זה",[["334","3","<b>אך הענין הוא דהנה כתיב כי לא מחשבותי מחשבותיכם</b>: בהבא לקמן בפרק זה ראה המשך תרס\"ו שם ע' רכט ואילך."],["335","4","<b>עפ\"ע</b>: על פי ערך."],["336","5","<b>ונת' בכ\"ד פי' דברי אגדה אלו</b>: ראה סה\"מ תרכ\"ז ע' רלו. רמד. תרכ\"ט ע' קמט."],["337","6","<b>וענין עלו במח' יובן עד\"מ שאנו רואים . . בן יחיד</b>: הובא ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316520231\" data-slug=\"or-hatorah-hb\" data-id=\"8316520231\">אוה\"ת</a> מג\"א שם ע' קצח בהגה\"ה מאו\"ת להה\"מ. וראה אור תורה (הוצאת קה\"ת) ב, ג. וראה גם כתר שם טוב סי' רמא (לא, ב). הובא ונת' באוה\"ת משפטים ע' א'רסז. א'רעח. המשך תרס\"ו שם ע' רלא. המשך תער\"ב ח\"ב ס\"ע תתקב. סה\"מ מלוקט ח\"א ע' רעו. ח\"ב ע' ה. וש\"נ. ח\"ה ע' רפו. ח\"ו ע' קיט. ועוד."]]],[2002180157,"הוא לא בבחי' הדבור לבד כ\"א בכל המדות עליונות שהרי החסד שלמטה עד\"מ הוא רק גרם השפעת הטוב להחיות זולתו משא\"כ למעלה מדת החסד היא עצמה המחי' כמ\"ש מכלכל חיים בחסד, וכן מדת הגבורה, וא\"כ לכאו' בזה שוה הדבור שהיא מדת המל' לכל המדות דז\"א, אך באמת גם בזה חלוק הדבור מהחסד עד\"מ שדבורו של הקב\"ה חשיב מעשה פי' שהוא עצמו משתנה להיות בחי' מעשה, שלמטה דבור ומעשה ב' דברים הם, ולמעלה דבורו עצמו חשוב מעשה, משא\"כ בחסד אם היות שהוא עצמו מחיה ולא רק גורם החיות מ\"מ אינו משתנה להיות דבר אחר כמו עשיית דבר שמהות העשייה משונה ממהות הדבור. ואמנם בבחי' המחשבה משונה המח' שלמעלה ממח' שלמטה, שמהמחשבה שלמטה גם כשיחשוב כל היום כו' לא יתהוה מזה מאומה שגם זולתו לא ידע לעשות הדבר שחושב, וגם לא תפעול השפעת דבר מה, משא\"כ למעלה כשעלה במח' מיד נתהוה, ולכן א' כי לא מחשבותי מחשבותיכם שבחי' המחשבה שלמטה אין לה דמיון כלל לבחי' המחשבה שלמעלה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> יעקב וישראל עבד ובן, תפילה ותורה, מגילה כתובה פנים ואחור פנים הוא בחי' תורה חכ' אדם, ולכאורה איך שייך כמראה אדם<sup data-n=\"339\">7</sup>, מח' של ישראל קדמו לכ\"ד, ופי' עלו במח', שכמו שלמטה בן יחיד החביב חקוק במוח זכרונו, כך בני בכורי עלה במח', ולמעלה תיכף כשעלה מיד נתהוה וזהו כי לא מח' מחשבותיכם.</span>\nב) <b>והנה</b> בחי' זו מה שנש\"י עלו במחשבה<sup data-n=\"338\">8</sup>, ז\"ע בחי' כמראה אדם שאמר יחזקאל הנביא, כי באמת באוא\"ס עצומ\"ה אינו שייך כלל לומר כמראה אדם, כי אדם הוא בחי' התחלקות ג' קווין חסד דרועא ימינא גבורה דרועא שמאלא, ת\"ת גופא, שז\"ע בחי' ג' מדות חג\"ת, אבל אוא\"ס הוא למעלה מבחי' המדות וכמאמר לאו מכל אינון מדות איהו כלל, ואפי' החכמה כעשייה גשמיות נחשבת לפניו ית' כמ\"ש כולם בחכמה עשית, ומה שנק' בשם כמראה אדם זהו רק מה שנתלבש בבחי' מדות בשביל נש\"י, שז\"ע מה שנש\"י עלו במחשבה שזהו בחי' כמראה אדם מה שעל דמות הכסא דמות כמראה אדם עליו מלמעלה. ובמע\"ב אמר נעשה אדם בצלמינו פי' שכמו שנש\"י עלו בבחי' המח' קודם שנברה\"ע שזהו בחי' כמראה אדם כנ\"ל כן בבחי' צלם ודמות זה נעשה בחי' האדם שלמטה בעשייה. ועל בחי' כמראה אדם זה שלמעלה נאמר חכמת אדם תאיר פניו, פי' חכמת אדם קאי על התורה שנק' ג\"כ בשם אדם כמ\"ש זאת התורה אדם, רק שהיא בחי' חכמה שבאדם, והוא בחי' פנימי שבאדם היינו בחי' המוחין שבאדם העליון (ולהיות כי בבחי' התיקון הוא בחי' התכללות לכן גם בבחי' המוחין יש כלול כל הרמ\"ח איברין של אדם שהם רמ\"ח",[["339","7","<b>כמראה אדם . . בחי' התחלקות ג' קוין</b>: ראה בכ\"ז בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370317\" data-slug=\"torah-or\" data-id=\"3901370317\">תו\"א יתרו עא, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370323\" data-slug=\"torah-or\" data-id=\"3901370323\">עב, ד</a>. סה\"מ תרל\"ב ח\"א ע' יב. ס\"ע טו ואילך. ועוד."],["338","8","<b>והנה בחי' זו מה שנש\"י עלו במחשבה</b>: בהבא לקמן בפיסקא זו ראה המשך תרס\"ו שם ע'רלב ואילך."]]],[2002180158,"פקודין ושס\"ה ל\"ת הם שס\"ה גידים כו' ולכן אנו רואים שגידי המוח נמשכים בכל האברים אפי' ברגלים, והוא מפני שבמוח עצמו יש ג\"כ בחי' ציור אדם), ובחי' חכמת אדם זה דחכ' תאיר פניו של בחי' כמראה אדם שנת' לעיל שזהו מה שנש\"י עלו בבחי' המח', וכמו עד\"מ שאנו רואים למטה כשנופל לאדם איזה השכלה חדשה אשר מתענג בה מצהיבים פניו, וכמארז\"ל בר\"א שצהבו פניו מפני שמצא תוספתא חדתי<sup data-n=\"340\">9</sup>, וכן ארז\"ל שא\"ל מטרוניתא לריב\"ע<sup data-n=\"341\">10</sup> פניך דומים למלוה בריבית, או למגדלי חזירים, והשיב לה שהא והא אסורים לי, אלא שחכמת אדם תאיר פניו, והיינו מפני שבחכמה מלובש בחי' הענג, וכשמשיג השגה חדשה מאיר בה הענג אשר עי\"ז צוהבים פניו כו'. ועד\"ז יובן בבחי' תורה שזהו בחי' אדם פנימי הנ\"ל מלובש בה בחי' הענג שהוא בחי' עדן שלמעלה מבחי' גן וכמ\"ש ונהר יוצא מעדן להשקות את הגן וארז\"ל שמא תאמר גן זה עדן ת\"ל ונהר כו' גן לחוד ועדן לחוד, אשר עדן הוא בחי' עין לא ראתה אלא שמלובש בתורה בחי' גן סדרים דאורייתא, וזהו יוצא מעדן להשקות את הג\"ן סדרים דאורייתא, ולכן ע\"י חכמת אדם הוא בחי' תורה אדם פנימי, שבה מלובש בחי' עדן מקור התענוגים תאיר פניו של בחי' כמראה אדם העליון הנ\"ל.\n<b>והנה</b> אמרז\"ל במד\"ר נשא<sup data-n=\"342\">11</sup> פי\"א ע\"פ יאר ה' פניו אליך, יאר זה מאור תורה, וכן דרשו יאר ה' פניו אליך שיביט בך בפנים מאירות, והיינו שע\"י התורה נמשך למטה באדם ג\"כ בחי' הארת פנים, מן בחי' הארת פנים העליון כו'. דהנה בתורה [כתיב] הליכות עולם לו, שע\"י בחי' התורה נעשה בחי' ההילוך כו'. והענין הוא דהנה התורה שלמטה היא בחי' משל לבד וכמ\"ש כאשר יאמר משל הקדמוני<sup data-n=\"343\">12</sup> שקאי על התורה שהיא בחי' משל, וע\"ד דכתיב בשלמה וידבר שלמה שלשת אלפים משל, וענין המשל אם היות שהמשל מסתיר על הנמשל, מ\"מ ע\"י המשל מבינים הנמשל היטיב, שכאשר השכל עמוק מאד א\"א להשיגו כ\"א ע\"י התלבשותו בלבוש המשל, אשר ע\"י אמצעות המשל מבינים הנמשל בטוב כו', ולכן בשלמה דכתיב בו וה' נתן חכ' לשלמה פי' שנתן לו במתנה בחי' חכמה תתאה דמל' דאצי' המהוה בי\"ע לכן השיג שלמה שלשת אלפים משל נגד ג' עולמות בי\"ע<sup data-n=\"344\">13</sup> שבכל עולם יש אלף מדריגות שכל אחד הוא רק כמו משל לגבי שלמעלה הימנו, ונגד ג' עולמות אלו השיג שלשת",[["340","9","<b>וכמארז\"ל בר\"א שצהבו פניו . . שמצא תוספתא חדתי</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380697\" data-slug=\"likkutei-torah\" data-id=\"4001380697\">לקו\"ת מסעי צג, רע\"ב</a>. לעיל ע' שעה. ובכ\"מ. וראה סה\"מ מלוקט ח\"ב ע' עז."],["341","10","<b>שא\"ל מטרוניתא לריב\"ע</b>: לר' יהודה בר אלעאי (ברכות נה, א). וראה ס' מאמרי אדהצ\"צ הנחות — תרט\"ו ע' קיז."],["342","11","<b>והנה אמרז\"ל במד\"ר נשא</b>: בהבא לקמן בפיסקא זו ראה ד\"ה ועשית חג שבועות בהמשך תרס\"ו ע' רלז ואילך."],["343","12","<b>התורה . . בחי' משל . . כאשר יאמר משל הקדמוני</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370439\" data-slug=\"torah-or\" data-id=\"3901370439\">תו\"א מג\"א צח, ב</a>. אוה\"ת וארא ע' קנב. סה\"מ תרכ\"ט ע' צו. וש\"נ."],["344","13","<b>וידבר שלמה שלשת אלפים משל . . נגד ג' עולמות בי\"ע</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">תו\"א מקץ מב, ב</a>. מג\"א שם צח, ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שנ. [ובהמ\"מ לשם]. סה\"מ תרכ\"ט ע' צה. סה\"מ מלוקט ח\"ג ע' לז. סה\"ש תשמ\"ט ח\"א ע 151 הע' 31. ובכ\"מ."]]]]});
